// 자동 생성 파일 (v2_secretary/export_panel.py) — 논문 카드 세부(주요 내용·근거 문장). panel_data.js가 클 때만 채움.
window.PANEL_PAPERS = {"2611.33885": {"points": [{"subtitle": "상자 표면 메모리", "desc": "물체가 가려졌다가 다시 나타날 때 생김새를 복구하려고 3차원 상자 면에 이미지 잠재 값을 유지하고 목표 시점의 광선을 따라 불러오는데요. 뭔 소리냐면, 물체의 위치마다 그 모양을 기억하는 창고를 만들어 둔다는 말입니다.", "evidence": "Box-Surface Latent Memory retains image latents on box faces and retrieves them along rays in the target view."}, {"subtitle": "메모리 조건 조절", "desc": "불러온 토큰을 목표 시점 위치와 공유된 상자 지역 임베딩, 물체별 주의를 활용해 편집기에 공급하고, 일치 손실로 알맞은 관측을 보게 유도한다는 거예요. 이렇게 하면 여러 번 고쳐도 원래 생김새를 잃지 않는 장점이 생깁니다.", "evidence": "Geometry-Aligned Memory Conditioning supplies the retrieved tokens to a FLUX.2 editor using target-view positions, shared box-local embeddings, and object-wise attention."}, {"subtitle": "새로운 벤치마크", "desc": "연구진은 보정된 배치와 설계된 재방문이 포함된 LayoutLoop라는 새로운 벤치마크를 만들어서 실제 장면 데이터와 함께 실험해 봤는데요. 그 결과 제안한 방법이 능력을 잘 발휘한다는 것을 확인했다고 밝혔습니다.", "evidence": "We also introduce LayoutLoop, a multi-round 3D layout-controlled image editing benchmark with calibrated layouts and designed revisits."}], "easy1_evidence": "In a sequence of edits, however, the latest image can lose the appearance of an object when it is occluded or leaves view.", "easy2_evidence": "We introduce LayoutRecall, a multi-round editor that stores and reuses appearance in the local coordinate systems of 3D boxes.", "topic_evidence": "3D layout-controlled image editing gives users explicit control over object placement and camera viewpoint.", "limit_evidence": ""}, "2611.30025": {"points": [{"subtitle": "다임드 아토믹 웨이브 인테그레이션 뉴런(DAWIN) 구조", "desc": "공간 투영과 경과 시간에 따른 파동 여기를 서로 묶어서 폐쇄형 감쇠 진동 방식으로 복소수 상태를 통합했는데요, 미분 방정식을 푸는 별도의 수치 계산기를 쓰지 않아도 된다는 장점이 있습니다. 뭔 소리냐면, 복잡한 물리 계산 과정을 간소화하면서도 연속적인 시간 흐름을 자연스럽게 녹여냈다는 말이에요.", "evidence": "DAWIN couples spatial projection with elapsed-time-dependent wave excitation and integrates it into a local complex state through closed-form damped evolution, avoiding numerical differential equation solvers."}, {"subtitle": "다윈 리니어(DAWINLinear) 연산과 속도 개선", "desc": "트리톤(Triton) 기반의 프리픽스 스캔 병렬 구현 방식을 써서 길이 L인 시퀀스에 대해 로그 스케일의 병렬 깊이를 확보했는데요, 엔비디아 B200 그래픽처리장치에서 직렬 구현 방식에 비해 추론 속도가 2630배까지 빨라졌다고 합니다. 메모리 사용량도 맘바(Mamba)와 비교했을 때 최대 97.6%까지 줄어든 것으로 나타났어요.", "evidence": "An associative Triton prefix-scan implementation, DAWINLinear, uses FP32 accumulation and achieves O(log L) parallel depth for sequence length L."}, {"subtitle": "다양한 작업에서의 성능 검증", "desc": "불규칙한 진동자부터 무조코(MuJoCo) 동역학, 보행자 이동 경로, 피지오넷 2012(PhysioNet 2012) 임상 시퀀스까지 총 11가지 작업에서 테스트를 거쳤는데요, 뉴럴 CDE보다 9개 작업에서 앞섰고 덴스 클리니컬 동역학에서는 모든 시드에서 0.9531 노말라이즈드 루트 미언 스퀘어 에러(NRMSE)를 기록하며 가장 좋은 성적을 냈다고 밝혔습니다.", "evidence": "Across 11 parameter-matched tasks covering irregular oscillators, MuJoCo dynamics, pedestrian trajectories, and PhysioNet 2012 clinical sequences, DAWIN outperforms Neural CDE on 9 tasks and ReLU-MLP on 8."}], "easy1_evidence": "Conventional artificial neurons separate spatial feature aggregation from continuous physical time, limiting their ability to model irregular observations.", "easy2_evidence": "We introduce the Damped Atomic Wave Integration Neuron (DAWIN), a continuous-time primitive for replacing standard neural layers in MLPs, Transformers, and graph neural networks.", "topic_evidence": "We introduce the Damped Atomic Wave Integration Neuron (DAWIN), a continuous-time primitive for replacing standard neural layers in MLPs, Transformers, and graph neural networks.", "limit_evidence": "and establish bounded-input bounded-output stability for positive damping and sampling intervals bounded away from zero."}, "2611.34708": {"points": [{"subtitle": "공통 패턴 예측 단계", "desc": "첫 번째 단계인 스테이지 I에서는 후보 목록 전체의 이벤트를 갱신하고 결합해서 가용성을 고려한 공통 패턴 예측기를 학습하는데요. 이때 쿼리 쪽과 후보 목록 쪽을 동시에 마스킹하는 방식을 함께 적용한다는 거예요. 뭔 소리냐면, 전체 후보들의 흐름을 먼저 파악해서 기본적인 예측 틀을 잡는다는 말이에요.", "evidence": "In Stage I, INSPIRE learns an availability-aware shared-pattern predictor that fuses event-updated memory across the full candidate catalog while applying coordinated query- and catalog-side masking."}, {"subtitle": "개별 증거 어댑터 최적화", "desc": "두 번째 단계인 스테이지 II에서는 앞서 만든 예측기를 고정해 둔 채로 가벼운 개별 증거 어댑터(EA)를 최적화하는데요. 텍스트 의미와 상관관계가 가중된 장기 이벤트 통계를 결합하여 정답을 더 정확하게 찾도록 돕는다는 겁니다. 결과적으로 의미론적 사전 정보와 후보 수준의 점수 경쟁이 맞지 않는 경쟁자들을 잘 억제해 준다는 거예요.", "evidence": "Subsequently, Stage II freezes this predictor and optimizes a lightweight individual-evidence adapter (EA) combining textual semantic priors with correlation-weighted long-range event statistics under support- and role-balanced co-answer supervision with prior-odds debiasing and soft residual alignment."}, {"subtitle": "성능 향상 결과", "desc": "아이시스(ICEWS)와 지델트(GDELT) 이벤트 데이터셋을 바탕으로 네 가지 벤치마크에서 평가해 봤더니 신규 개체 순위 지표가 16.73퍼센트에서 88.83퍼센트까지 높아졌는데요. 개별 증거 어댑터를 더했을 때도 신규 개체 순위 지표가 8.28퍼센트에서 32.63퍼센트까지 추가로 오르는 모습을 보였다는 겁니다. 쉽게 말하면, 제안한 두 단계 방식이 새로운 정보가 적은 상황에서도 예측 성능을 뚜렷하게 끌어올렸다는 셈이에요.", "evidence": "Relative to paired Stage I predictors, EA further increases Emerging MRR by 8.28%-32.63%, Answer-new MRR by 7.81%-41.24%, and cohort macro MRR by 9.64%-39.94%, gains attributed to semantic priors and candidate-level score competition suppressing mismatched established competitors without zero-support prior shortcuts."}], "easy1_evidence": "However, current paradigms are fragmented: pattern-transfer methods lack catalog-wide event memory, whereas online memory models suffer from endpoint-role asymmetry that degrades unseen-answer ranking.", "easy2_evidence": "Across four benchmarks based on the ICEWS and GDELT event datasets, INSPIRE improves Emerging MRR by 16.73%-88.83% over the strongest baselines.", "topic_evidence": "To address these challenges, we propose INSPIRE (Integrating Shared Patterns and Individual Evidence for Reasoning), a two-stage forecasting framework over a known catalog.", "limit_evidence": ""}, "2611.34698": {"points": [{"subtitle": "실패 주도 데이터 플라이휠 구조", "desc": "실제 세계 장면을 다시 만들고 그 안에 필요한 요소를 넣어 가지고 있던 데이터에 없던 목표 상황을 만들어 봤는데요. 모델이 작업 조건과 난이도에 따라 얼마나 자주 실패하는지 실패 지도를 만들고, 잘 안 되는 조건에 더 많은 데이터 생성 몫을 얹어 준다는 거에요. 뭔 소리냐면, 모델이 자주 틀리는 곳에 공부를 더 시킨다는 말입니다.", "evidence": "It constructs target scenarios absent from the available data by inserting task-relevant entities into reconstructed real-world scenes, and evaluates the model against each behavioral requirement of the target task."}, {"subtitle": "가려진 보행자 상황 성능 검증", "desc": "가려진 보행자가 갑자기 튀어나오거나 정지선에서 양보하는 자율주행 상황에 적용해 봤는데요. AutoVLA 모델은 충돌 없이 지나가는 비율이 0.261에서 0.579로, ReCogDrive 모델은 0.390에서 0.765로 올랐다는 거예요. 불필요하게 브레이크를 밟는 비율은 0.013을 넘지 않았다고 합니다.", "evidence": "For occluded-pedestrian emergence, five rounds of post-training improve the critical-phase collision-free rate on the sealed test set from 0.261 to 0.579 for AutoVLA and from 0.390 to 0.765 for ReCogDrive, while the unnecessary braking rate in paired control scenarios never exceeds 0.013."}, {"subtitle": "세부 행동 패턴과 정지선 양보 결과", "desc": "세부적으로 뜯어봤더니 두 모델 모두 가리는 차량을 만나기 전에 미리 속도를 줄이는 법은 익혔지만, 보행자가 튀어나온 뒤에 밟는 브레이크는 여전히 제한적이라는 한계가 있었는데요. 정지선에서 멈추는 비율은 AutoVLA가 0.100에서 0.897로, ReCogDrive가 0.000에서 0.667로 뛰었다고 합니다.", "evidence": "Fine-grained evaluation reveals a pattern obscured by the collision-free rate alone: both VLA models learn anticipatory deceleration before reaching the occluding vehicle, while braking after pedestrian emergence remains limited."}], "easy1_evidence": "Pretrained vision-language-action (VLA) models rarely satisfy all behavioral requirements of a new platform, and teams without a large deployed fleet lack the data to address the resulting failures.", "easy2_evidence": "We propose a failure-driven data flywheel for post-training such models.", "topic_evidence": "We propose a failure-driven data flywheel for post-training such models.", "limit_evidence": "while braking after pedestrian emergence remains limited."}, "2611.34646": {"points": [{"subtitle": "REE 벤치마크의 구성", "desc": "연구진은 5개 과학 분야와 23개 도메인에 걸쳐 100개의 열린 연구 문제로 이루어진 REE라는 벤치마크를 소개했는데요. 뭔 소리냐면, 모든 문제가 실제 활발한 연구에서 뽑혀서 전문가들의 검토를 거쳤다는 말이에요.", "evidence": "It consists of 100 open-ended research problems spanning five broad scientific areas and 23 domains."}, {"subtitle": "반복 개선 평가 방식", "desc": "각 문제는 에이전트가 작동하는 시작 솔루션을 최대 12시간 동안 개선하는 과제로 주어졌는데요. REE는 비교 가능한 조건에서 평가된 기존 전문가 솔루션과 공통된 척도로 결과를 점수화한다는 겁니다.", "evidence": "Each problem is posed as a task of iterative improvement: an agent has up to 12 hours to improve a working starter solution, and REE scores the result on a common scale against an established expert solution evaluated under comparable conditions."}, {"subtitle": "에이전트의 성능 결과", "desc": "평가 대상이었던 4개 프론티어 에이전트 중 두 모델이 모든 과학 분야의 문제에서 전문가 솔루션을 능가하는 모습을 보였는데요. 쉽게 말하면, 에이전트들이 평균 두 시간 만에 전문가를 넘어섰고 주로 기존 방식을 조합해 활용했다고 보입니다.", "evidence": "Their runs also show how they do so: both agents surpass the expert solutions within the first two hours on average, and their best solutions mostly tailor or combine established methods of the field."}], "easy1_evidence": "Evaluating this ability requires benchmarks that pose open-ended research problems and measure improvements over established scientific methods.", "easy2_evidence": "By this measure, two of the four frontier agents we evaluate, Claude Opus 5.5 and GPT-6.1 Sol, outperform the expert solutions on 86% and 81% of problems, across all five scientific areas.", "topic_evidence": "We introduce REE (Research Entrance Exam), a benchmark that tests AI agents on scientific research.", "limit_evidence": ""}, "2611.34635": {"points": [{"subtitle": "제로히어로 틀과 사전 훈련", "desc": "연구진은 5천만 개보다 적은 매개변수를 가진 작은 언어 에이전트를 처음부터 훈련하기 위해 제로히어로라는 틀을 도입했습니다. 각 환경에서 큰 언어 모델이 전문가 역할을 맡고, 그 모델의 성공적인 경로를 모아서 상호작용 기록에 따른 전문가의 반응을 예측하도록 사전 훈련을 거쳤다는 거예요. 뭔 소리냐면, 큰 모델이 남긴 모범 답안을 작은 모델이 먼저 익히게 만든다는 말입니다.", "evidence": "We pretrain each SLA, which has fewer than 50 million parameters, to predict the expert's responses given the interaction history."}, {"subtitle": "PPO와 추론 정렬을 활용한 후속 훈련", "desc": "사전 훈련 뒤에는 근접 정책 최적화(PPO) 방식을 써서 에이전트가 자신의 상호작용을 통해 직접 후속 훈련을 받도록 했습니다. 이때 추론 정렬은 환경에서 받는 보상뿐만 아니라 에이전트가 행동과 함께 생성하는 언어에 대해서도 전문가의 감독을 함께 보태주는 역할을 하는데요. 쉽게 말하면, 행동만 평가하는 게 아니라 생각하고 말하는 과정까지 같이 다듬어 준다는 겁니다.", "evidence": "During post-training, reasoning alignment supplements environment rewards with expert supervision on the language the agent generates alongside its actions."}, {"subtitle": "세 가지 환경에서의 성능 평가", "desc": "연구진은 언어 이해와 생성이 모두 필요한 3가지 다단계 환경인 크래프터, 웹숍, 알프월드 다이얼로그에서 에이전트를 평가했습니다. 웹숍에서는 전문가 성능에 가까워졌고, 크래프터와 알프월드 다이얼로그 과제에서는 시연 전문가를 뛰어넘는 결과를 보였다고 밝혔는데요. 결과적으로 작은 모델이라도 올바른 훈련 틀을 거치면 복잡한 상호작용 과제에서 전문가 못지않은 성능을 낼 수 있다는 걸 보여준 셈이에요.", "evidence": "The agents approach expert performance on WebShop and surpass their respective demonstration experts on Crafter training rollouts and held-out Alfworld-Dialogue tasks."}], "easy1_evidence": "We introduce ZeroHero, a framework for training small language agents (SLAs) from scratch.", "easy2_evidence": "The agents approach expert performance on WebShop and surpass their respective demonstration experts on Crafter training rollouts and held-out Alfworld-Dialogue tasks.", "topic_evidence": "We introduce ZeroHero, a framework for training small language agents (SLAs) from scratch.", "limit_evidence": ""}, "2611.34612": {"points": [{"subtitle": "FWSP 방식 도입", "desc": "연구진은 프로빙과 계층화된 연산자 등을 묶은 FWSP라는 파이프라인을 만들었는데요, 토큰을 추가로 쓰지 않고도 자동 라우팅에서 83.3%의 성능을 기록해 33.3%인 27B LLM을 크게 앞섰다고 해요. 뭔 소리냐면, 복잡한 언어 모델의 도움 없이도 정해진 알고리즘만으로 신경망 가중치를 다룰 수 있다는 말이에요.", "evidence": "We show that for core structured editing regimes, an LLM optimizer is unnecessary, and introduce Forward Weight-Space Programming (FWSP): a deterministic pipeline combining probing, localization, stratified operators (O1-O4), automatic blind routing (83.3% vs. 33.3% for a 27B LLM with the same tool library), and paired verification with zero additional per-token computation."}, {"subtitle": "추론 모델 성능 향상", "desc": "추론형 언어 모델을 위해 프로텍테드 피셔게이트라는 읽기 수정 방식을 제안했는데요, DeepSeek-R1-0528-8B 모델에 적용해 보니 HumanEval pass@1 점수가 84.2%까지 올라갔다는 겁니다. 기존의 토큰을 깎아 먹던 방식보다 토큰은 23.4% 줄이면서도 성능은 14.6 pp 더 높였다는 걸 확인했어요.", "evidence": "For reasoning LLMs, we propose Protected FisherGate, a closed-form covariance-whitened readout edit orthogonal to normal-reasoning states: on DeepSeek-R1-0528-8B, a single frozen math-calibrated patch achieves 84.2% HumanEval pass@1 (1K budget; 75.4 +/- 9.4% across 3/5 Stage-4-passing subsets), beating 512-token-reserved budget forcing by +14.6 pp (-23.4% tokens) while transferring across HF-to-vLLM backends on full GSM8K and MATH-500."}, {"subtitle": "연산자 한계와 적용 범위 증명", "desc": "5가지 데이터 형식과 13개 모델을 거치며 부분 공간 얽힘과 고정 표현 범위라는 두 가지 연산자 한계를 증명했는데요, 이를 통해 FWSP로 위치를 잡은 LoRA가 순방향 전용 방식과 경사도 기반 방식을 이어준다는 점을 검증했다고 해요. 쉽게 말하면, 다양한 모델 환경에서 이 방식이 실제로 어떻게 작동하고 어디까지 통하는지 한계선을 분명히 그어 본 셈이에요.", "evidence": "Across five modalities and thirteen models (50K to 27B dense and FP8 MoE), we further prove and verify two operator boundaries, subspace entanglement and frozen representation span, where FWSP-localized LoRA bridges forward-only and gradient adaptation."}], "easy1_evidence": "Recent work on Weight-Space Programming uses LLMs to edit neural weights with forward passes only, conflating LLM scripting with the underlying algebra of forward-only editing.", "easy2_evidence": "We show that for core structured editing regimes, an LLM optimizer is unnecessary, and introduce Forward Weight-Space Programming (FWSP): a deterministic pipeline combining probing, localization, stratified operators (O1-O4), automatic blind routing (83.3% vs. 33.3% for a 27B LLM with the same tool library), and paired verification with zero additional per-token computation.", "topic_evidence": "We show that for core structured editing regimes, an LLM optimizer is unnecessary, and introduce Forward Weight-Space Programming (FWSP): a deterministic pipeline combining probing, localization, stratified operators (O1-O4), automatic blind routing (83.3% vs. 33.3% for a 27B LLM with the same tool library), and paired verification with zero additional per-token computation.", "limit_evidence": ""}, "2611.34576": {"points": [{"subtitle": "OKF 인덱스 기억과 절차 기억의 도입", "desc": "연구진은 대화 기록을 연결된 구조로 정리하는 OKF 인덱스 기억과, 에피소드에서 재사용 가능한 결정을 배우는 절차 기억을 제안했습니다. 뭔 소리냐면, 단순한 대화 텍스트 저장을 넘어서 정보의 흐름과 결정 과정을 체계적으로 학습한다는 말이에요.", "evidence": "We introduce Open Knowledge Format (OKF)-indexed episodic memory to organize interactions and retrieve related events through their lineage."}, {"subtitle": "성능과 토큰 효율성 비교 결과", "desc": "평가해 봤더니 OKF 인덱스 검색은 전체 이력 문맥보다 69% 적은 토큰을 쓰면서도 우선순위가 낮은 선호도 F1 점수 0.93-0.95를 기록했습니다. 절차 기억은 대화 턴 수를 최대 39% 줄여 주었으며, PersonaMem-v2에서는 전체 이력보다 90.5% 적은 입력 토큰으로 50.2%의 정확도를 보였다고 해요.", "evidence": "In our evaluation, OKF-indexed retrieval achieves low-priority preference F1 scores of 0.93-0.95 at medium and high preference overlap between hiring projects."}, {"subtitle": "모델별 특징과 모델 간 비용 대비 성능", "desc": "강화 학습을 거친 절차 기억은 올바른 기권과 정확한 필드 식별에서 각각 60%를 기록했으며, Jev 계열 모델은 대화 효율을 높이지만 시간적 증거를 놓칠 수도 있다는 점이 드러났습니다. 또한 GPT-5.6 Luna는 더 낮은 비용으로 GPT-5.4와 비슷한 수준의 성능을 낸다고 밝혔어요.", "evidence": "GPT-5.6 Luna performs comparably to GPT-5.4 at lower cost."}], "easy1_evidence": "Multi-session hiring assistants must infer evolving recruiter preferences and decision patterns across projects and time.", "easy2_evidence": "Procedure Memory reduces conversational turns by up to 39% relative to no memory.", "topic_evidence": "These findings highlight the value of structured episodic memory and learned decision procedures for efficient personalization and temporal reasoning.", "limit_evidence": ""}, "2611.34563": {"points": [{"subtitle": "스마트 제조와 IIoT", "desc": "IIoT와 AI 기술이 제조업 전반의 생산성과 효율을 끌어올리고 있다는 배경에서 출발했는데요, 연구진은 이를 바탕으로 실제 제조 공정에 적용할 수 있는 방법을 고민해 봤다는 겁니다.", "evidence": "The Industrial Internet of Things (IIoT) and Artificial Intelligence (AI) are driving Industry 4.0, enhancing productivity, automation, and efficiency in manufacturing systems."}, {"subtitle": "엣지 AI 모니터링 체계", "desc": "유제품 가공 공장의 회전 밸브를 대상으로 진동 데이터를 모아 엣지 기기에서 처리하는 구조를 설계했는데요, 뭔 소리냐면 중앙 서버로 데이터를 다 보내지 않고 현장에서 바로 상태를 파악하는 방식이라는 말이에요.", "evidence": "This study develops an Edge-AI-based condition monitoring framework, as a step towards predictive maintenance, for a rotary valve in a dairy processing pilot plant"}, {"subtitle": "예지 보전을 위한 데이터 수집", "desc": "저전력 IIoT 센서 노드를 이용해 진동 데이터를 수집하고 처리하도록 만들었는데요, 쉽게 말하면 장비가 고장 나기 전에 미리 감지하는 예지 보전으로 나아가는 첫걸음을 뗐다는 겁니다.", "evidence": "using vibration data collected via a low-power IIoT sensor node and processed on an edge device."}], "easy1_evidence": "This study develops an Edge-AI-based condition monitoring framework, as a step towards predictive maintenance, for a rotary valve in a dairy processing pilot plant, using vibration data collected via a low-power IIoT sensor node and processed on an edge device.", "easy2_evidence": "This study develops an Edge-AI-based condition monitoring framework, as a step towards predictive maintenance, for a rotary valve in a dairy processing pilot plant, using vibration data collected via a low-power IIoT sensor node and processed on an edge device.", "topic_evidence": "This study develops an Edge-AI-based condition monitoring framework, as a step towards predictive maintenance, for a rotary valve in a dairy processing pilot plant, using vibration data collected via a low-power IIoT sensor node and processed on an edge device.", "limit_evidence": ""}, "2611.34407": {"points": [{"subtitle": "에이전틱 워터폴 프레임워크 구축", "desc": "연구진은 언어 모델 기반 제어기를 사용해 지속적인 사용자 상태를 유지하고 콘텐츠 검색과 순위 매기기 및 상태 업데이트를 조율하는 에이전틱 워터폴 프레임워크를 설계했는데요, 명시적인 요청과 탐색 행동을 바탕으로 사용자의 변하는 요구를 파악해 시스템이 맞추도록 돕는다는 말이에요. 뭔 소리냐면, 시스템이 사용자의 진짜 의도를 계속 기억하고 반영하도록 구조를 짰다는 겁니다.", "evidence": "We address this problem with the Agentic Waterfall framework, whose language-model controller maintains persistent user state and coordinates content retrieval, ranking, and state updates."}, {"subtitle": "데이터셋과 재생 기반 평가 프로토콜", "desc": "시스템을 평가하려고 실제 콘텐츠 메타데이터와 시뮬레이션된 상호작용 이력을 합친 에이전틱 워터폴 데이터셋과 재생 기반 평가 프로토콜을 함께 만들었는데요, 공유된 이력 아래에서 시스템들을 관련성 점수와 추천이 사용자의 목표와 제약을 얼마나 만족하는지 블라인드 판정으로 비교한다는 겁니다.", "evidence": "To evaluate systems on this task, we contribute the Agentic Waterfall Dataset and a replay-based evaluation protocol."}, {"subtitle": "성능 검증과 개선 결과", "desc": "5개의 공개 벤치마크에서 기존의 강한 기준선들과 견줄 만한 성능을 유지했는데요, 에이전틱 워터폴 데이터셋에서는 두 가지 평가 모두에서 기존 최고 기준선보다 뛰어난 성과를 냈다는 겁니다. 쉽게 말하면, 최대 16.1%의 상대적 개선율을 보였다고 연구진은 밝혔습니다.", "evidence": "Agentic Waterfall remains competitive with strong baselines on conventional recommendation tasks across five public benchmarks."}], "easy1_evidence": "We formalize Agentic Waterfall Feed, a new problem of personalized information discovery in which users actively direct recommendations and the system adapts to evolving needs inferred from both explicit requests and browsing behavior.", "easy2_evidence": "Agentic Waterfall remains competitive with strong baselines on conventional recommendation tasks across five public benchmarks.", "topic_evidence": "We address this problem with the Agentic Waterfall framework, whose language-model controller maintains persistent user state and coordinates content retrieval, ranking, and state updates.", "limit_evidence": ""}, "2611.34254": {"points": [{"subtitle": "크루시블 벤치(Crucible Bench) 도입", "desc": "연구진은 디자인부터 분석까지 화학 연구의 네 가지 단계를 모두 평가하기 위해 크루시블 벤치를 만들었는데요. 이 벤치에는 18개의 발표된 데이터셋에서 가져온 12개 분야의 1,078개 과제가 담겨 있답니다. 에이전트들은 모델 컨텍스트 프로토콜을 거쳐 7개의 독립된 환경에서 75개의 도구를 쓸 수 있다는 거예요.", "evidence": "The benchmark contains 1,078 tasks in 12 task families curated from 18 published datasets, covering molecular design, synthesis planning, experimental execution, closed-loop optimization, simulation, and analytical characterization."}, {"subtitle": "실험 환경과 에이전트 평가", "desc": "실험실 과제에는 로봇 시뮬레이터나 미리 측정된 실험 데이터가 쓰였고, 격리된 채점기가 합성 경로와 실험 프로토콜을 검증했는데요. 14개의 LLM 에이전트를 시험해 본 결과, 가장 뛰어난 모델은 전체 점수 0.545를 기록했다고 해요. 그중에서도 합성 계획과 폐쇄 루프 최적화 분야가 가장 풀기 어려운 영역으로 나타났다는 말이에요.", "evidence": "We evaluate 14 LLMs as agents and find that the best achieves an overall score of 0.545, with synthesis planning and closed-loop optimization emerging as the hardest domains."}, {"subtitle": "오류 분석과 도구 활용의 한계", "desc": "전체 성능이 좋다고 해서 최적화 성능까지 높게 나오는 것은 아니며, 12위 모델이 최적화에서는 가장 높은 점수를 받기도 했답니다. 에이전트들이 도구를 실행하는 데는 성공하면서도 정작 화학적으로 틀린 결과를 내놓는 오류가 자주 보였다는 거예요. 더 강력한 모델일수록 도구를 써서 얻는 이점이 크지만, 화학 소프트웨어를 믿을 만하게 쓰는 것은 여전히 남은 과제라고 연구진은 밝혔어요.", "evidence": "Error analysis also shows that agents often submit chemically invalid results despite running their tools successfully."}], "easy1_evidence": "Large language models (LLMs) perform well on chemistry knowledge benchmarks, which mainly assess question answering and isolated tasks.", "easy2_evidence": "We evaluate 14 LLMs as agents and find that the best achieves an overall score of 0.545, with synthesis planning and closed-loop optimization emerging as the hardest domains.", "topic_evidence": "To address this gap, we introduce Crucible Bench to evaluate this ability across all four stages of the design-make-test-analyze (DMTA) cycle.", "limit_evidence": "Stronger models benefit more from tool access, but reliable use of chemical software remains a challenge that Crucible Bench can track as models improve."}, "2611.34250": {"points": [{"subtitle": "EBU 벤치마크 구축", "desc": "연구진은 12개의 의료 작업 그룹과 관련 기술을 묶어 자율 기술 사용 능력을 평가할 수 있는 EBU-Bench를 만들었는데요, 스스로 쓸 때와 명시적인 안내를 받아 읽고 쓸 때의 기술 사용 정확도 차이를 EBU 격차로 정의해 측정했어요. 그랬더니 모든 모델 조합에서 평균 43.94퍼센트포인트(pp)의 격차가 나타났다는 겁니다.", "evidence": "We construct EBU-Bench, a challenging benchmark covering 12 medically relevant task groups and associated skills, to evaluate agents' ability to use available skills autonomously."}, {"subtitle": "EBU-Evolve를 통한 개선", "desc": "자율 실행과 안내받은 실행의 피드백을 모아 효과적인 지침으로 바꿔주는 EBU-Evolve를 제안했는데요, 이를 적용한 기술은 자율 실행 정확도가 33.33에서 55.17퍼센트포인트(pp)만큼 좋아졌어요. 기술이 공개된 뒤에도 EBU 현상은 계속 남을 수 있지만, 새로운 의료 작업에서도 정확도가 올라간다는 장점이 있다는 거예요.", "evidence": "Relative to their pre-evolution versions, the revised skills improve skill-use accuracy during autonomous execution by 33.33 to 55.17 pp and continue to yield improvements when transferred across multiple models and harnesses."}, {"subtitle": "모델과 도구에 따른 차이", "desc": "모델과 기술이 같아도 도구(harness)에 따라 자율 기술 사용 정확도가 달라져서 모델 순위까지 바뀔 수 있음을 확인했는데요, 같은 모델이라도 도구에 따라 자율 사용 정확도가 38.96퍼센트포인트(pp)까지 차이가 났다는 말이에요. 뭔 소리냐면, 모델 성능뿐만 아니라 어떤 도구와 함께 쓰느냐가 결과에 큰 영향을 준다는 겁니다.", "evidence": "Our results show that autonomous skill-use accuracy varies across harnesses with the model and skill held fixed, and model rankings can change."}], "easy1_evidence": "We observe that even when a skill specifies the rules and procedures needed for a task, agents may fail to apply them effectively during autonomous execution, a phenomenon we call skill Enable But Underuse (EBU).", "easy2_evidence": "Motivated by these observations, we propose EBU-Evolve, which uses execution feedback from autonomous and explicitly guided skill use to distill effective guidance into reusable skill instructions.", "topic_evidence": "To evaluate and address EBU, we introduce MedSkill-E$^{2}$, a framework for evaluating and evolving skills for medical agents.", "limit_evidence": ""}, "2611.34248": {"points": [{"subtitle": "섀플리 값의 한계", "desc": "기존의 강화학습에서는 어떤 특징이 행동을 이끄는지 섀플리 값으로 설명했지만, 에이전트의 확실성까지는 보여주지 못했거든요. 뭔 소리냐면, 확실성을 파악하려면 특징들이 불확실성에 미치는 영향도 알아야 하는데 기존 방식으로는 한계가 있었다는 말이에요.", "evidence": "Shapley values in reinforcement learning are used to explain which observation features drive an agent's behavior and expected return, but not its certainty."}, {"subtitle": "EXPOSURE 모델 제안", "desc": "그래서 연구진은 행동 선택과 섀플리 설명을 동시에 처리하는 마스크 인식 신뢰 네트워크인 EXPOSURE를 만들었는데요. 관측 누락에 따른 관찰 부분과 환경의 무작위성으로 인한 고유 부분으로 나누어 반환값의 분산을 설명하고, 신뢰도의 엔트로피까지 함께 계산해 준다는 겁니다.", "evidence": "We propose EXPOSURE, which uses one mask-aware belief network for both action selection and Shapley explanations."}, {"subtitle": "실험 결과와 정확도", "desc": "정확한 섀플리 값을 계산할 수 있는 틱택토와 지뢰찾기 환경에서 테스트해 봤더니, 기대 반환값과 불확실성을 더 정확하게 설명하면서 신뢰 불확실성까지 독보적으로 짚어내는 것으로 나타났어요. 쉽게 말하면, 기존보다 훨씬 정밀하게 에이전트의 속내를 파악할 수 있게 되었다는 말이에요.", "evidence": "In tic-tac-toe and Minesweeper, where exact Shapley values are computable, EXPOSURE gives more accurate explanations of expected return and its uncertainty, while uniquely explaining belief uncertainty."}], "easy1_evidence": "Shapley values in reinforcement learning are used to explain which observation features drive an agent's behavior and expected return, but not its certainty.", "easy2_evidence": "We propose EXPOSURE, which uses one mask-aware belief network for both action selection and Shapley explanations.", "topic_evidence": "We propose EXPOSURE, which uses one mask-aware belief network for both action selection and Shapley explanations.", "limit_evidence": ""}, "2611.34247": {"points": [{"subtitle": "날짜별 지식 그래프 재구축", "desc": "연구진은 2020년부터 최신 버전까지 연도별로 바이오 지식 그래프를 다시 만들어 2020년 이후의 시간순 평가 환경을 마련했는데요. 뭔 소리냐면, 모델이 학습한 시점과 실제 사건이 일어난 시점을 정확히 갈라놓으려고 과거의 데이터 상태를 연도별로 똑같이 재현했다는 말이에요.", "evidence": "We rebuild a dated biomedical knowledge graph as it stood at the end of each year from 2020 up to its newest version."}, {"subtitle": "검색 기능 없는 모델의 성능", "desc": "지식 검색을 붙이지 않은 모델들은 치료 분야별 과거 임상 횟수를 세어보는 단순한 기준과 비슷한 수준의 순위 매기기 실력을 보여줬는데요. 연구진은 결정 시점보다 앞선 근거를 가져다 써도 모델 학습 전후를 막론하고 성능이 아주 조금 오르는 데 그쳤다고 밝혔어요.", "evidence": "Without retrieval, the models rank about as well as trial history, a count of each target's past trials in the same therapeutic area, also after their training cutoffs."}, {"subtitle": "미래 정보 유출 문제 확인", "desc": "가장 최신 지식 그래프를 쓰면 6개 중 5개 모델의 성능이 뚜렷하게 올라갔지만, 이 경로에는 이미 결정 이후 날짜로 찍힌 해당 쌍의 임상 시험 정답이 포함되어 있다는 한계가 있거든요. 그래서 연구진은 약물 타깃을 평가할 때 결정 이전의 근거와 결정 이후의 결과를 철저히 날짜별로 갈라야 한다고 강조했습니다.", "evidence": "Evaluations of target prioritisation should date both features and labels, with evidence from before the decision and outcomes after it."}], "easy1_evidence": "We recast each target-disease hypothesis as a dated event, the pair's first clinical trial.", "easy2_evidence": "The newest graph raises five of six models clearly above that baseline, but its paths usually include the answer: the pair's own trial, dated after the decision.", "topic_evidence": "We then ask six open language models, with and without this graph, which targets will enter a first trial for a disease the next year.", "limit_evidence": "The newest graph raises five of six models clearly above that baseline, but its paths usually include the answer: the pair's own trial, dated after the decision."}, "2611.34112": {"points": [{"subtitle": "연구 종합과 규모", "desc": "2017년부터 2026년 9월까지 13,884개의 고유 기록 중 엄선한 2,289편의 연구를 20개의 방법론적 범주로 나누어 살펴봤는데요. 이산적 하드 선택 방식이 토큰 수준에서는 70%, 쿼리 수준에서는 83%, 태스크 수준에서는 91%를 차지한다는 점을 확인했어요. 뭔 소리냐면, 각 분야에서 명확하게 선택하고 넘어가는 방식을 주로 썼다는 말이에요.", "evidence": "Discrete hard selection accounts for 70%, 83%, and 91% of token-, query-, and task-scale literature respectively, and computational overhead appears as a top operational bottleneck across every layer."}, {"subtitle": "안전장치의 불균형", "desc": "계층마다 안전장치를 다루는 방식에 차이가 있었는데요. 레이어 내부 게이팅은 부하 분산을 우선시하면서 불확실성 추정은 잘 다루지 않는 반면, 모델 선택이나 에이전트 조율은 신뢰도 임계값과 예산 규칙에 의존하면서도 오류가 연쇄적으로 번지는 문제를 마주하고 있다는 겁니다.", "evidence": "Engineering safeguards remain sharply asymmetric: intra-layer gating prioritizes load balancing while rarely incorporating uncertainty estimation, whereas model selection and agent orchestration rely on confidence thresholds and budget rules while confronting miscalibration and cascading errors."}, {"subtitle": "에이전트 연구의 빠른 성장과 위험", "desc": "특히 에이전트 기반 태스크 위임 분야에서 출판량이 가장 빠른 속도로 늘고 있다고 밝혔는데요. 장점은 관련 연구가 빠르게 확장된다는 점이지만, 대신 라우팅 메커니즘을 실험적으로 분리하기가 어려워 방법론적 편향 위험이 가장 높다는 단점도 같이 따라온다는 겁니다.", "evidence": "At the same time, publication volume is accelerating fastest in agentic task delegation, where routing mechanisms are least often isolated experimentally and methodological bias risk is highest."}], "easy1_evidence": "Yet token-level gating in sparse neural architectures, query-level model cascades, and task-level multi-agent coordination have largely progressed in disconnected research silos, obscuring recurring system failures and transferable fixes.", "easy2_evidence": "In this systematic review, we synthesize 2,289 studies published between 2017 and September 2026 (selected from 13,884 unique records) across 20 methodological families under a unified two-step inspect-then-allocate framework.", "topic_evidence": "In this systematic review, we synthesize 2,289 studies published between 2017 and September 2026 (selected from 13,884 unique records) across 20 methodological families under a unified two-step inspect-then-allocate framework.", "limit_evidence": ""}, "2611.34011": {"points": [{"subtitle": "철회 프레임워크 확장", "desc": "연구진은 FIPA-ACL performative disconfirm을 활용해 의무론과 결과주의를 바탕으로 발언을 평가하는 믿음 기반 틀을 철회 영역까지 넓혔는데요. 정직하게 한 발언이 나중에 틀린 것으로 드러났을 때 도덕적 근거에 따라 철회 의무가 어떻게 달라지는지 따져보려는 거예요. 뭔 소리냐면, 기존의 말하기 윤리를 철회 상황에 그대로 적용해 검증해 봤다는 말이에요.", "evidence": "Using the FIPA-ACL performative disconfirm, we extend a belief-based framework that evaluates speech acts under deontologism and consequentialism to the case of retraction."}, {"subtitle": "의무론의 한계와 새로운 의무", "desc": "발언 당시의 진실성을 따지는 의무론의 정직 의무만으로는 이미 한 발언의 철회를 요구할 수 없다는 사실을 증명했는데요. 대신 화자가 더 이상 믿지 않는 내용을 청자가 계속 믿게 내버려 두는 것을 금지하는 지속 의무를 추가해야 한다고 제안했어요. 쉽게 말하면, 발언 당시 거짓이 아니었더라도 나중에 오류를 알았다면 방치하면 안 된다는 겁니다.", "evidence": "We prove that the honesty duty of deontologism, which bears on utterances when they are made, never requires retracting an erroneous truth, and add a persistent one, which forbids letting the addressee believe what the speaker no longer believes."}, {"subtitle": "법률 자문 사례 분석", "desc": "답변 세트 프로그래밍으로 구현한 법률 자문 사례를 적용해 봤더니, 의무론과 결과주의 모두 철회가 필요하다고 가리켰는데요. 하지만 피해를 막기에는 너무 늦은 시점이라면 결과주의에서는 더 이상 철회를 요구하지 않는다는 결과가 나왔어요. 타이밍에 따라 철회 필요성이 달라진다는 점을 구체적으로 보여준 셈이라는 말이에요.", "evidence": "On a legal-advice case implemented in Answer Set Programming, we show that deontologism and consequentialism both require the retraction, but that consequentialism no longer does once it comes too late to prevent harm."}], "easy1_evidence": "We prove that the honesty duty of deontologism, which bears on utterances when they are made, never requires retracting an erroneous truth, and add a persistent one, which forbids letting the addressee believe what the speaker no longer believes.", "easy2_evidence": "On a legal-advice case implemented in Answer Set Programming, we show that deontologism and consequentialism both require the retraction, but that consequentialism no longer does once it comes too late to prevent harm.", "topic_evidence": "Using the FIPA-ACL performative disconfirm performative, we extend a belief-based framework that evaluates speech acts under deontologism and consequentialism to the case of retraction.", "limit_evidence": ""}, "2611.33966": {"points": [{"subtitle": "패턴마이너(PatternMiner)의 작동 방식", "desc": "연구진이 개발한 패턴마이너는 대형 언어 모델 에이전트가 수학적 데이터셋을 만들고, 좁은 범위의 기계 학습 모델을 학습시킨 뒤 해석 기법으로 패턴을 추출해 추측을 세우는 방식으로 작동해요. 뭔 소리냐면, AI가 직접 가설을 세우고 수학 소프트웨어를 호출해서 반례를 찾으며 가설을 계속 다듬어간다는 말이에요.", "evidence": "In PatternMiner, an LLM agent generates mathematical datasets based on an initial broad question, trains narrow machine learning models on them, uses interpretability techniques to extract patterns from these trained models, and uses these patterns to formulate conjectures."}, {"subtitle": "가설의 진화와 증명 과정", "desc": "만약 반례가 나오면 이를 피드백으로 삼아 가설을 수정하거나 학습과 해석 과정을 다시 거치게 되는데요, 에이전트가 언제든 증명을 시도할 수 있도록 허용하면서 반복적으로 가설을 발전시킨다는 거예요. 이렇게 세워진 추측은 여러 번의 상호작용을 거치며 점점 더 정교해진다는 겁니다.", "evidence": "Once an initial conjecture has been formulated, PatternMiner instructs the agent to search for counterexamples using calls to mathematical software."}, {"subtitle": "다섯 가지 양수성 문제 해결", "desc": "연구진은 이 시스템을 대수조합론의 5가지 유명한 양수성 문제에 적용해 보았는데요, 그 결과 슈베르트 양수성과 사영, 제한된 카즈단-루스틱 조합 불변량 추측 등에 관한 여러 새로운 정리들을 증명해 냈다고 밝혔어요. 쉽게 말하면, 기존에 풀기 까다로웠던 수학적 문제들에서 새로운 공식을 이끌어내는 데 성공했다는 셈이에요.", "evidence": "PatternMiner proves several new theorems related to Schubert positivity and projection, a character-row evaluation formula, a restricted version of the Kazhdan--Lusztig combinatorial invariance conjecture, and Schur positivity for a family of immanant coefficients."}], "easy1_evidence": "The latter is limited in its ability to move beyond simple empirical pattern detection while the former is not well-designed for direct, open-ended exploration of large mathematical datasets.", "easy2_evidence": "PatternMiner proves several new theorems related to Schubert positivity and projection, a character-row evaluation formula, a restricted version of the Kazhdan--Lusztig combinatorial invariance conjecture, and Schur positivity for a family of immanant coefficients.", "topic_evidence": "In this paper we introduce PatternMiner, a system that combines these two paradigms.", "limit_evidence": ""}, "2611.33909": {"points": [{"subtitle": "경험 추출과 비교", "desc": "중간 추론과 도구 사용을 평가하고 성공과 실패를 거듭 비교해 유용한 관행과 근거가 뒷받침된 회피 지침을 뽑아냈는데요, 이 경험들은 원천 대화까지 추적할 수 있는 조건이 달린 작업 흐름으로 합쳐진다는 말이에요.", "evidence": "EGSE evaluates intermediate reasoning and tool use and contrasts repeated successful and failed rollouts to extract useful practices and evidence-supported avoidance guidance."}, {"subtitle": "도서관 구축과 추론 활용", "desc": "도서관에 기술을 더하거나 합칠 때는 원천 근거를 따지는 검토와 실행 검증을 거치도록 했는데요, 추론할 때는 영상 종류와 질문 과제, 질병 분류에 따라 알맞은 작업 흐름을 골라 증거를 모으고 해석하는 데 쓴다는 겁니다.", "evidence": "Library additions and merges require source-grounded review and execution validation."}, {"subtitle": "실험 결과와 성능", "desc": "4가지 흉부 엑스레이 벤치마크 실험을 해 봤더니, EGSE가 기존 의료 에이전트와 기술 발전 방식보다 추론 정확도가 높으면서 도구 호출은 줄어드는 것으로 나타났는데요, 7개 기초 모델에서도 정확도가 꾸준히 오르고 데이터셋 사이 기술 전송도 뒷받침된다고 해요.", "evidence": "Experiments across four chest X-ray benchmarks show that EGSE outperforms representative medical agents and skill evolution methods in reasoning accuracy while reducing tool calls."}], "easy1_evidence": "A correct final answer can conceal flawed reasoning or tool use, synthesized advice may lack source support, and superficially similar cases may require different diagnostic procedures.", "easy2_evidence": "In this paper, we propose EGSE, an evidence-grounded skill evolution framework that distills historical dialogues from similar cases into reusable conditional workflows and progressively refines a multi-faceted skill library through supported and validated updates to improve medical agents.", "topic_evidence": "In this paper, we propose EGSE, an evidence-grounded skill evolution framework that distills historical dialogues from similar cases into reusable conditional workflows and progressively refines a multi-faceted skill library through supported and validated updates to improve medical agents.", "limit_evidence": ""}, "2611.33879": {"points": [{"subtitle": "포크(FORK)의 작동 방식", "desc": "노출된 메시지와 허용된 결정을 바탕으로 안전장치의 자연어 기술 라이브러리를 기울기 없는 방식으로 수정해 나간다는 거예요. 뭔 소리냐면, 사람이 일일이 규칙을 짜는 대신 공격자와 함께 부딪히며 기술을 다듬는다는 말이에요.", "evidence": "Each exploited message and permissive decision gives FORK evidence for a gradient-free revision of its natural-language skill library."}, {"subtitle": "포크-월드(FORK-World) 평가 결과", "desc": "세 에이전트를 평균 낸 결과, 포크는 적응형 공격 아래서 공격 성공률을 78.4%에서 14.1%까지 낮췄는데요, 동시에 작업 유용성은 85% 이상으로 유지해 기존 방법들보다 뛰어난 성능을 보였다는 겁니다.", "evidence": "Averaged over three agents on FORK-World, FORK cuts attack success rate (ASR) under adaptive attack from 78.4% to 14.1% and keeps utility above 85%, outperforming baselines on both ASR and utility."}, {"subtitle": "엠티-에이전트리스크(MT-AgentRisk) 일반화 성능", "desc": "훈련 과정에서 보지 못한 새로운 환경과 작업에서도 공격 성공률을 70.6%에서 9.1%로 낮추는 모습을 보였는데요, 이때 93.1%라는 높은 정상 유용성도 함께 챙겼다는 겁니다. 쉽게 말하면, 새로운 환경에 놓여도 방어 능력이 잘 통한다는 말이에요.", "evidence": "Notably, on MT-AgentRisk, whose environments and tasks are unseen in training, FORK lowers ASR from 70.6% to 9.1% with 93.1% benign utility."}], "easy1_evidence": "When a guardrail rejects an LLM agent's action, its message reaches any attacker observing the trajectory: a fixed refusal leaves benign users unable to recover, whereas an explanation can tell the attacker what to try next.", "easy2_evidence": "We study this as safe disclosure: explaining rejections so that authorized tasks recover without increasing adaptive attack success.", "topic_evidence": "Because hand-written rules alone cannot anticipate how adaptive attackers probe decisions or use messages, we introduce FORK, which co-evolves a guardrail's natural-language decision and disclosure skills with an attacker that reads every public message.", "limit_evidence": ""}, "2611.33836": {"points": [{"subtitle": "란턴(LANTERN) 프레임워크 구조", "desc": "연구진은 모델 개발 과정을 오류 주도 순환 방식으로 바꿨는데요. 실패 조사 과정에서 놓친 모든 병려를 네 가지 원인 중 하나로 분류하고, LLM 멘토가 근거 획득, 시각 표현, 학습 정책, 결정 집계라는 네 가지 수준을 한 번에 하나씩 수정한다는 거예요. 여기에 테스트 데이터 없이 첫 번째 라운드 전에 고정된 규칙으로 유지 여부를 정하고 모든 도구 호출을 감시하는 방식을 썼다는 겁니다.", "evidence": "LANTERN recasts model development as an error-driven loop: a failure census attributes every missed lesion to one of four causes, an LLM mentor revises one of four levels (evidence acquisition, visual representation, learning policy, decision aggregation) per round, and a rule frozen before the first round decides what is kept, without test data and with every tool call audited."}, {"subtitle": "브라츠-메트(BraTS-MET) 성능 향상 결과", "desc": "15번의 자동화된 라운드를 거쳤더니, 미세 조정한 4B 크기의 MLLM이 브라츠-메트(BraTS-MET) 데이터셋에서 스캔당 거짓 양성 1개 조건 기준으로 병려를 찾는 비율이 기존 75%에서 94%까지 올라갔는데요. 이는 기존 최첨단 MLLM 5개가 시작 프로토콜에서 보여준 최대 51%나 0.1~1 mL 크기 기준 29%보다 훨씬 높다는 거예요. 외부 코호트에서는 89%, 보지 못한 수막종(Meningiomas)에서는 77%의 성능을 보여주었다는 겁니다.", "evidence": "Over 15 unattended rounds, LANTERN raises a fine-tuned 4B MLLM from finding 75% to 94% of lesions at one false positive per scan on BraTS-MET, and 91% of those of 0.1-1 mL, compared with at most 51% and 29% for five frontier MLLMs read under the starting protocol; the gains hold on an external cohort (89%) and on unseen meningiomas (77%)."}, {"subtitle": "자기 주도적 재귀 개선의 가능성", "desc": "이러한 결과는 MLLM이 놓친 실수를 그 원인과 연결해 분석하면 안정적인 재귀적 자기 개선을 이끌어낼 수 있음을 보여준다고 연구진은 밝혔는데요. 뭔 소리냐면, 단순히 정답만 맞히는 학습이 아니라 어디서 틀렸는지를 역추적하는 구조가 의료 영상 같은 복잡한 판독 분야에서 모델의 한계를 극복하는 핵심 열쇠라는 말이에요.", "evidence": "These results show that an MLLM's own misses, attributed to their causes, can drive its reliable recursive self-improvement."}], "easy1_evidence": "Brain metastases expose this gap: at 384 px a 0.1 mL lesion covers less than a quarter of one visual token, and at one false positive per scan frontier MLLMs find fewer than 30% of lesions of 0.1-1 mL.", "easy2_evidence": "We introduce LANTERN (Lesion-finding AgeNt Through Error-driven Recursive learNing), a framework in which an MLLM improves recursively from its own misses.", "topic_evidence": "We introduce LANTERN (Lesion-finding AgeNt Through Error-driven Recursive learNing), a framework in which an MLLM improves recursively from its own misses.", "limit_evidence": ""}, "2611.33822": {"points": [{"subtitle": "절차적 기억의 구축과 재구성", "desc": "연구진의 외부 루프는 성공적인 훈련 실행에서 절차적 기억을 쌓고 작업 진행 상황을 추상적 상태로 나타내는데요, 새로운 진행 구분을 배우면 예전 실행 증거를 다시 훑어보며 상태 할당을 재평가하고 지원하는 절차를 재조직한다고 해요. 뭔 소리냐면, 새로운 상황을 배울 때마다 옛날에 해 둔 기억의 틀을 다시 고쳐 쓴다는 말이에요.", "evidence": "Its outer loop builds procedural memory from successful training executions, representing task progress as abstract states and procedures between states as directed acyclic graphs of operations and dependencies."}, {"subtitle": "내부 루프의 실행과 성능 평가", "desc": "테스트 시점에 기억을 고정한 상태에서 내부 루프가 초기 분할을 다듬고 환경 피드백으로부터 수정해 나가는데요, 알프월드와 사이언스월드(ScienceWorld)에서 세 번의 시드로 평가해 봤더니 다섯 가지 세팅 중 네 곳에서 비교군 중 가장 높은 평균 성능을 보였다는 거예요. 예를 들어 알프월드에서 큐웬3-4B 모델과 함께 쓰였을 때 86.3% 성공률을 기록했다고 해요.", "evidence": "With memory fixed at test time, the inner loop refines an initial decomposition and revises it from environmental feedback, combining applicable procedure fragments with task-specific steps missing from memory."}, {"subtitle": "토큰 효율성과 구성 요소 분석", "desc": "메타디컴프는 리액트와 오토라인에 비해 다섯 가지 세팅 모두에서 더 적은 추론 토큰을 썼는데요, 구성 요소 소거 실험에서는 초기 스키마를 고정하거나 역사적 재투영을 빼면 성능이 떨어진다는 점이 확인되었어요. 쉽게 말하면, 기억을 동적으로 고쳐 쓰고 토큰을 아끼는 게 이 방법의 핵심이라는 겁니다.", "evidence": "MetaDecomp also uses fewer inference tokens than ReAct and AutoRefine in all five settings."}], "easy1_evidence": "Reusing past experience in long-horizon tasks requires more than storing successful procedures: Language agents must distinguish which procedures apply and what work remains as execution progresses.", "easy2_evidence": "Evaluated on ALFWorld and ScienceWorld over three seeds, MetaDecomp achieves the highest mean performance among the compared methods in four of five settings, for example, an 86.3% success rate on ALFWorld with Qwen3-4B.", "topic_evidence": "We introduce MetaDecomp, an in-context meta-learning framework for adaptive task decomposition that jointly learns a task-relative state space and reusable procedures.", "limit_evidence": ""}, "2611.33818": {"points": [{"subtitle": "기존 방법의 충돌 원인", "desc": "수화 생성 모델에서 최적 운송(OT)과 분류기 없는 안내(CFG)를 함께 쓸 때, 조건 드롭아웃 때문에 서로 부딪히는 문제가 생겼다는 거예요. 뭔 소리냐면, 하나의 노이즈 샘플이 서로 다른 동역학을 가진 목표 동작들과 연결되면서 의미 전달을 방해한다는 말이에요.", "evidence": "Under the condition dropout, one noise sample can be paired with target motions exhibiting incompatible motion dynamics, interfering with the semantic guidance when the text condition is present."}, {"subtitle": "스펙트럼 최적 운송(SOT) 제안", "desc": "그래서 연구진은 기존 동작 공간 비용에 주파수 특징 거리를 더한 SOT(Spectral Optimal Transport) 방식을 내놓았는데요. 목표 동작의 시간 및 주파수 구조를 맞추는 방향으로 연결을 다시 조절해서 CFG와 함께 쓸 때의 문제를 바로잡겠다는 겁니다.", "evidence": "To address this issue, we propose Spectral Optimal Transport (SOT), which augments the pose-space cost with a spectral feature distance, reweighting the coupling toward the temporal-frequency structure of the target motions, thereby improving the performance when using CFG."}, {"subtitle": "성능 검증 결과", "desc": "실험을 거쳐 정량적, 정성적 측면에서 제안한 방법이 얼마나 효과적인지 확인했다고 해요. 쉽게 말하면, 기존 방식에서 부딪히던 한계를 넘어서 수화 생성 품질을 끌어올렸다는 겁니다.", "evidence": "The quantitative and qualitative experiments demonstrate the effectiveness of the proposed method."}], "easy1_evidence": "While classifier-free guidance (CFG) could be applied to further strengthen the semantic alignment theoretically, its training involves conditional and unconditional training, which may contradict the pose-space OT, thus reducing the generation quality.", "easy2_evidence": "To address this issue, we propose Spectral Optimal Transport (SOT), which augments the pose-space cost with a spectral feature distance, reweighting the coupling toward the temporal-frequency structure of the target motions, thereby improving the performance when using CFG.", "topic_evidence": "To address this issue, we propose Spectral Optimal Transport (SOT), which augments the pose-space cost with a spectral feature distance, reweighting the coupling toward the temporal-frequency structure of the target motions, thereby improving the performance when using CFG.", "limit_evidence": ""}, "2611.33794": {"points": [{"subtitle": "두 가지 거짓 성능 요인 분리", "desc": "연구진은 내부 심사위원을 쓰는 똑같은 반복 과정 속에서 거짓 성능의 원인을 두 가지로 나눠 살펴봤습니다. 심사위원의 자체 오류와 보이지 않는 조건으로 이어지지 않는 전이 간극이라는 말이에요. 뭔 소리냐면, 안에서 좋아 보인다고 해서 진짜로 실력이 늘었다고 볼 수는 없다는 겁니다.", "evidence": "Running the same loop under each judge, we separate two sources of a false gain, which we call judge error (the loop's judge is wrong on its own data) and transfer gap (a real gain there does not carry over to unseen conditions)."}, {"subtitle": "주행과 조작 실험 결과", "desc": "실험을 해 봤더니 조작 과제에서는 성공 분류기가 196개의 실패 중 65개를 받아들였고, 주행에서는 안쪽 기준만 믿으면 안 되는 경우를 확인했습니다. 바깥쪽 심사위원을 쓰자 주행 반복 결과에서 기존 내부 평가보다 더 높은 0.674 PDMS 점수를 기록했는데요. 59개의 손실은 걸러내고 12개 중 11개의 진짜 이득을 정확히 받아들였다는 셈이에요.", "evidence": "When the sealed test decides, a driving loop built to improve ends with a better policy than under its own critic (0.674 against 0.649 PDMS, from 0.638), and on driving pairs with known sealed gain the test accepted 11 of 12 real gains and none of 59 losses."}, {"subtitle": "실제 차량 주행 실험", "desc": "실제 도로 차량 실험에서도 강화된 버전이 원래 버전보다 곡선 구간을 더 멀리 주행했습니다. 6쌍의 블라인드 실험 모두에서 더 깊게 들어갔지만, 완주하지는 못했다는 한계도 함께 확인했어요. 쉽게 말하면, 안쪽 증거만으로는 성능 향상을 믿을 수 없기에 바깥쪽 평가가 꼭 필요하다는 겁니다.", "evidence": "In a real-world field experiment on a published improvement step, the reinforced version drove further into a curve than the version it started from in all 6 blind pairs, though neither completed it."}], "easy1_evidence": "However, the judge is usually trained or chosen inside the same loop, so its evidence is not independent of the policy.", "easy2_evidence": "We introduce SealedLoop, an evaluation framework that adds a sealed judge: an evaluator outside the loop that the improver cannot see or optimize against.", "topic_evidence": "SealedLoop offers a foundation for trustworthy self-improvement of embodied policies, in which progress is judged by evidence the improving system cannot influence.", "limit_evidence": "In a real-world field experiment on a published improvement step, the reinforced version drove further into a curve than the version it started from in all 6 blind pairs, though neither completed it."}, "2611.33715": {"points": [{"subtitle": "다중 논문 통합의 난제", "desc": "여러 논문의 내용을 엮을 때는 논문 간의 관계를 찾아내어 하나의 일관된 흐름으로 합쳐야 하는데요, 동시에 발표자마다 선호하는 구성과 강조하는 내용이 크게 달라서 개인 맞춤 설정이 필수적이라는 말이에요.", "evidence": "This task introduces two main challenges: (i) combining multiple sources into a coherent narrative requires identifying cross-paper relationships and synthesizing their content, and (ii) the desired organization and emphasis varies substantially across presenters, making personalization essential for user satisfaction."}, {"subtitle": "KeyDeck 프레임워크 제안", "desc": "그래서 연구진은 개별 논문과 교차 논문 분석을 통해 내용의 공통점을 묶고, 참고 자료를 바탕으로 발표자의 취향을 추론해 슬라이드를 맞춰주는 KeyDeck을 만들었는데요, 이는 다중 논문 슬라이드 생성을 지원하는 첫 번째 프레임워크라는 거예요.", "evidence": "Motivated by these challenges, we propose KeyDeck, the first multi-PTSG framework that integrates per-paper and cross-paper analysis to identify relationships among sources and synthesize their contributions into a coherent narrative, and reference-guided personalization to infer presenters' narrative, content, textual, and visual preferences and adapt slide generation accordingly."}, {"subtitle": "성능 평가 결과", "desc": "연구진이 전문가가 직접 만든 100개의 다중 논문 발표 자료로 구성된 벤치마크인 KeyBench를 통해 평가해 봤더니, KeyDeck이 기존 방식보다 슬라이드 생성 품질과 맞춤 설정 만족도 등에서 더 우수한 결과를 보였다고 주장했어요.", "evidence": "Our results demonstrate that KeyDeck outperforms existing approaches in multi-PTSG quality, personalization adherence, and conversational goal satisfaction."}], "easy1_evidence": "This task introduces two main challenges: (i) combining multiple sources into a coherent narrative requires identifying cross-paper relationships and synthesizing their content, and (ii) the desired organization and emphasis varies substantially across presenters, making personalization essential for user satisfaction.", "easy2_evidence": "Motivated by these challenges, we propose KeyDeck, the first multi-PTSG framework that integrates per-paper and cross-paper analysis to identify relationships among sources and synthesize their contributions into a coherent narrative, and reference-guided personalization to infer presenters' narrative, content, textual, and visual preferences and adapt slide generation accordingly.", "topic_evidence": "Motivated by these challenges, we propose KeyDeck, the first multi-PTSG framework that integrates per-paper and cross-paper analysis to identify relationships among sources and synthesize their contributions into a coherent narrative, and reference-guided personalization to infer presenters' narrative, content, textual, and visual preferences and adapt slide generation accordingly.", "limit_evidence": ""}, "2611.33707": {"points": [{"subtitle": "로컬 기술 추출(LSE)", "desc": "먼저 에이전트의 궤적에서 작업 적용 조건과 실행 전략이 담긴 기술 패치, 그리고 작업 실행 결과를 뽑아내는데요. 뭔 소리냐면, 원본 데이터를 그대로 공유하지 않고 꼭 필요한 정보만 압축해서 꺼내 온다는 말이에요.", "evidence": "Specifically, LSE first extracts skill patches (i.e., task applicability conditions and execution strategies) and task execution outcomes from trajectories."}, {"subtitle": "개인화된 기술 선택(PSS)", "desc": "그다음 실행 결과를 바탕으로 각 기술 패치가 클라이언트의 작업에서 얼마나 잘 작동했는지 평가하고 적용 조건을 더해 맞춤형 기술 세트를 만드는데요. 쉽게 말하면, 남이 쓴 기술 중에서도 내게 진짜 도움이 되는 것만 골라 담는 셈이에요.", "evidence": "PSS then uses these outcomes to evaluate each skill patch's performance on client tasks and incorporates its task applicability condition to construct a personalized skill set for each client."}, {"subtitle": "작업 인식 기술 라우팅(TASR)", "desc": "마지막으로 적용 조건을 살펴보고 현재 작업에 꼭 알맞은 기술 패치들을 골라내어 에이전트가 움직일 때 길잡이로 쓰게 하는데요. 연구진은 개인화된 기술 선택에 대한 이론적 보장도 함께 제공했다고 밝혔습니다.", "evidence": "Finally, TASR adaptively selects a task-relevant subset of skill patches based on their applicability conditions to guide agent execution."}], "easy1_evidence": "However, existing FSL methods typically share skills based on skill similarity without considering their contributions to heterogeneous tasks across clients, thereby degrading agent performance.", "easy2_evidence": "To address this challenge, we propose P-FedSkill, a personalized FSL framework that comprises three key components: local skill extraction (LSE), personalized skill selection (PSS), and task-aware skill routing (TASR).", "topic_evidence": "To tackle this issue, federated skill learning (FSL) has emerged as a solution by distilling trajectories into compact skill representations and uploading them to a central server for sharing.", "limit_evidence": ""}, "2611.33706": {"points": [{"subtitle": "반복적 도구 재계획", "desc": "중간에 나온 관찰 결과를 바탕으로 도구를 고르는 방법과 파라미터를 동적으로 다듬어서 도구를 쓰는 신뢰성을 높였어요. 뭔 소리냐면, 한 번 정해진 도구와 값에 갇히지 않고 중간 과정을 보며 계속 수정한다는 말이에요.", "evidence": "First, we introduce Iterative Tool Replanning, which dynamically refines tool selection and parameters based on intermediate observations, improving the reliability of tool usage."}, {"subtitle": "증거 일관성 검증", "desc": "최종 예측과 모아둔 증거가 서로 잘 맞는지 확인하는 답 검증 방법을 만들어서 증거와 추론이 겉도는 문제를 줄였어요. 쉽게 말하면, 찾아낸 증거와 내놓은 답이 서로 딴소리를 하지 않게 묶어주는 셈이에요.", "evidence": "Second, we develop Evidence Consistency Verification, an answer validation mechanism that improves alignment between the final prediction and the collected evidence, mitigating evidence--reasoning inconsistencies."}, {"subtitle": "선택적 증거 라우팅", "desc": "외부 증거가 꼭 필요한지 따져보는 적응형 빠르고 느린 추론 전략을 넣어 튼튼함과 효율성을 함께 챙겼는데요. 눈으로 보기 쉬운 질문은 바로 풀고, 복잡하거나 위험한 경우에만 도구를 써서 증거를 모은다는 겁니다.", "evidence": "In addition, to balance robustness and efficiency, EVA incorporates Selective Evidence Routing, an adaptive fast--slow reasoning strategy that determines when external evidence is necessary."}], "easy1_evidence": "Hallucinations in multimodal large language models (MLLMs) often arise from visual assumptions that go unchecked.", "easy2_evidence": "In this work, we propose EVA, an Evidence-seeking Visual Agent that reframes multimodal reasoning as an explicit process of evidence acquisition and verification.", "topic_evidence": "In this work, we propose EVA, an Evidence-seeking Visual Agent that reframes multimodal reasoning as an explicit process of evidence acquisition and verification.", "limit_evidence": ""}, "2611.33679": {"points": [{"subtitle": "가짜 질문 생성의 필요성", "desc": "모델이 캐시를 정리할 때 미래의 디코딩 질문을 미리 알 수 없기 때문에 추가 단계를 거쳐야 하는 문제가 있었는데요. 첫 번째 출력 토큰의 임베딩을 활용해 저비용으로 가짜 질문을 만들 수 있는지 알아보기 시작했다는 겁니다. 뭔 소리냐면, 복잡한 추가 연산 없이 첫 토큰만으로 미래를 예측해 보겠다는 말이에요.", "evidence": "Can we use the embedding of the first output token, already available from the final prefill logits, to construct low-cost pseudo queries that approximate future decoding queries?"}, {"subtitle": "FTQ-8의 한계와 FBQ의 도입", "desc": "처음에는 첫 토큰 ID를 연속된 미래 위치에 여덟 개 복사해 쓰는 FTQ-8로 시작했으나, 일반적인 시작 단어는 실제 후속 토큰들과 잘 맞지 않는다는 단점이 있었는데요. 이를 해결하기 위해 연구진은 첫 임베딩을 유지하고 일곱 개의 남은 위치에 더할 오프셋을 학습시키는 FBQ 방식을 제안했다는 겁니다. 쉽게 말하면, 엉뚱한 추정을 줄이기 위해 위치별로 알맞은 값을 학습으로 보정해 준 셈이에요.", "evidence": "Faster and Better Query (FBQ) preserves the first embedding and learns an additive offset at each of the seven remaining positions."}, {"subtitle": "LongBench 성능 평가", "desc": "LongBench에서 실험해 본 결과, FBQ는 여덟 단계의 룩어헤드 Q-캐시와 비슷한 수준의 성능을 보여주었다고 하는데요. 모든 프로브 쿼리를 단 한 번의 순방향 패스로 계산한다는 장점이 있음을 확인했다는 겁니다. 결과적으로 같은 캐시 예산 안에서 효율성과 성능을 모두 챙긴 것으로 보입니다.", "evidence": "On LongBench, FBQ performs comparably to eight-step Lookahead Q-Cache at the same cache budget, using a single forward pass to compute all probe queries."}], "easy1_evidence": "When a large language model (LLM) evicts prompt keys and values at the end of prefill, it must decide what to keep before it sees the queries from subsequent decoding steps.", "easy2_evidence": "Faster and Better Query (FBQ) preserves the first embedding and learns an additive offset at each of the seven remaining positions.", "topic_evidence": "Faster and Better Query (FBQ) preserves the first embedding and learns an additive offset at each of the seven remaining positions.", "limit_evidence": ""}, "2611.33664": {"points": [{"subtitle": "슬라이스플래너 구조", "desc": "연구진은 망 조율을 하나의 가설로 다루는 슬라이스플래너를 제안했는데요. 핵심 성능 지표(KPI, Key Performance Indicator)와 제약 조건을 거친 뒤에 실제 개선이 확인될 때만 적용하는 방식이거든요. 뭔 소리냐면, 무조건 바꾸는 게 아니라 검증을 거쳐서 안전하게 고친다는 말이에요.", "evidence": "We present SlicePlanner, a logic-guided closed-loop framework that treats each RAN reconfiguration as a controlled hypothesis: proposed from live and historical KeyPerformance Indicator (KPI) evidence, filtered through explicit SLA constraints and mined RAN control rules, and committed only when post-action measurements confirm improvement."}, {"subtitle": "두 에이전트의 협력", "desc": "이 시스템은 슬라이스센스(SliceSense)와 슬라이스가드(SliceGuard)라는 두 에이전트로 이루어져 있는데요. 슬라이스센스는 지표를 모니터링하고 후보 행동을 고르며, 슬라이스가드는 결과를 검증하고 문제가 생기면 되돌린다는 겁니다. 쉽게 말하면, 한쪽은 찾아서 제안하고 다른 쪽은 안전한지 검사하는 셈이에요.", "evidence": "SlicePlanner comprises two cooperating agents: SliceSense, which monitors live KPIs, retrieves context-conditioned evidence, and ranks candidate RAN actions through a surrogate-guided admissibility filter; and SliceGuard, which validates post-action KPI responses, rolls back harmful configurations, and refreshes rules under distribution drift."}, {"subtitle": "성능 검증 결과", "desc": "오픈에어인터페이스(OpenAirInterface) 등의 도구를 써서 무선으로 검증해 봤는데요. 정적 방식에 비해 지연 위반을 최대 86% 줄이고, 심층 강화학습 방식보다도 50% 줄였다고 해요. 통신 처리량은 비슷하게 유지하면서도 온라인 재학습 없이 작동한다는 점이 특징이라는 겁니다.", "evidence": "Validated over the air using OpenAirInterface, FlexRIC, and commercial Sierra Wireless 5G devices, SlicePlanner reduces SLA latency violations by up to 86% over static slicing and 50% over Deep Reinforcement Learning (DRL)-based slicing, while maintaining comparable cell throughput and auditable decisions without online retraining."}], "easy1_evidence": "Adaptive network slicing in Open Radio Access Network (O-RAN) demands reconfiguration decisions that respond to live traffic conditions while remaining safe with respect to Service Level Agreement (SLA) constraints, a combination that purely data-driven controllers cannot reliably guarantee without continuous retraining.", "easy2_evidence": "Validated over the air using OpenAirInterface, FlexRIC, and commercial Sierra Wireless 5G devices, SlicePlanner reduces SLA latency violations by up to 86% over static slicing and 50% over Deep Reinforcement Learning (DRL)-based slicing, while maintaining comparable cell throughput and auditable decisions without online retraining.", "topic_evidence": "We present SlicePlanner, a logic-guided closed-loop framework that treats each RAN reconfiguration as a controlled hypothesis: proposed from live and historical KeyPerformance Indicator (KPI) evidence, filtered through explicit SLA constraints and mined RAN control rules, and committed only when post-action measurements confirm improvement.", "limit_evidence": ""}, "2611.33639": {"points": [{"subtitle": "실험 설계와 데이터 구성", "desc": "연구진은 SWE-bench Verified에서 가져온 90개의 Django 패치를 가지고 Opus, Sonnet, Haiku 세 모델을 낮은 노력부터 높은 노력까지 조절해 가며 테스트해 봤어요. 강화된 SWE-ABS 시험으로 확인해 보니 그중 55개는 틀린 패치였고 35개는 맞는 패치였다고 해요. 뭔 소리냐면, 테스트를 통과했어도 숨겨진 결함이 있는 코드들을 AI가 잡아내는지 보려고 철저하게 판별해 봤다는 말이에요.", "evidence": "Claude Opus 5.5 (preregistered), Sonnet 5.5 and Haiku 5.5 (exploratory) each reviewed the same 90 agent-written Django patches from SWE-bench Verified at low, medium and high effort."}, {"subtitle": "노력 수준별 성능과 비용 비교", "desc": "모든 모델에서 높은 노력을 쓸 때 틀린 패치를 덜 받아줬는데요, 거짓 성공률이 Opus는 0.45 대 0.67, Sonnet은 0.49 대 0.65, Haiku는 0.51 대 0.78로 나타났어요. Opus의 경우 중간 노력이 높은 노력과 비교해 15% 포인트 이내의 성능을 유지하면서 비용은 20% 절감됐다고 해요. 대신 Sonnet과 Haiku는 비용을 39%와 51%까지 줄였지만 성능이 충분히 유지된다는 점은 증명하지 못했다는 거예요.", "evidence": "In every model, high effort accepted fewer wrong patches than low (false success .45 against .67 for Opus, .49 against .65 for Sonnet, .51 against .78 for Haiku), a supported difference for Opus and Haiku."}, {"subtitle": "추가 분석과 한계점", "desc": "추가로 살펴보니 대부분의 거절 사유는 테스트된 결함을 구체적으로 지적하는 내용이었고 노력을 높일수록 그런 거절이 늘어났다고 해요. 그렇지만 어떤 설정도 완벽하지 않아서 모든 모델이 틀린 패치의 최소 45%는 그냥 통과시켰다는 한계가 있어요. 쉽게 말하면, 아무리 노력을 올려도 AI 리뷰어가 틀린 코드를 완전히 걸러내지는 못한다는 겁니다.", "evidence": "Exploratory coding showed that most rejections named the tested defect and that effort added such rejections."}], "easy1_evidence": "We asked how much effort a reviewer needs to catch plausible-but-wrong patches, which pass a benchmark's tests but fail stronger ones.", "easy2_evidence": "For Opus, medium was non-inferior to high within 15 percentage points (difference .018, 95% CI [-.065, .108]) and cost 20% less, short of the preregistered 30%.", "topic_evidence": "We asked how much effort a reviewer needs to catch plausible-but-wrong patches, which pass a benchmark's tests but fail stronger ones.", "limit_evidence": "For 32 of the 55 wrong patches the issue may not require what the failing test checks; without them, neither accuracy hypothesis holds for any model."}, "2611.33617": {"points": [{"subtitle": "통합 분석 표현과 매핑", "desc": "이 표현은 자오선 형상과 독립적인 경계 각도 법칙을 통해 기하학적 제어를 정의하는데요, 이 제어들을 블레이드 표면으로 연결하기 위해 이방성 편미분 방정식(PDE)을 쓴다는 거예요. 뭔 소리냐면, 설계 규칙을 실제 날개 모양으로 바꿔 주는 핵심 수학적 다리 역할을 한다는 말이지요.", "evidence": "The representation defines geometric controls through meridional geometry and independent boundary angle laws."}, {"subtitle": "매개변수 보정과 역방향 복구", "desc": "기하학적 매개변수 보정(GPC)은 공동 기하학 인코더와 매개변수 디코더를 써서 회전자 종류와 치수에서 나온 초기 제어를 다듬어 준다는 거예요. 또 역방향 복구 기능은 기존 CAD를 같은 기하학적 제어로 바꿔서 다시 만들고 계속 편집할 수 있게 해 준다는 겁니다.", "evidence": "Geometric parameter correction (GPC) uses a joint geometric encoder and a parameter decoder to refine controls initialized from rotor category and dimensions."}, {"subtitle": "실험 결과와 성능", "desc": "실험을 해 봤더니 베인크래프트는 이방성 제어와 매개변수 편집을 잘 지원한다는 점을 보여 줬는데요, 회전자 CAD 생성 작업에서 대표적인 기준 모델들보다 더 뛰어난 성능을 냈다고 연구진은 밝혔어요. 쉽게 말하면, 기존 방법들보다 모양을 제어하고 다시 쓰기가 훨씬 수월하다는 걸 증명한 셈이에요.", "evidence": "Experiments demonstrate that VaneCraft supports anisotropy control and parameter editing and outperforms representative baselines in rotor CAD generation tasks."}], "easy1_evidence": "However, creating models for different rotors requires different modeling processes, making it difficult to control geometry through design intent and reuse existing models.", "easy2_evidence": "We introduce VaneCraft, an agent-driven framework for rotor generation, inverse recovery, and editing through a unified analytical representation.", "topic_evidence": "We introduce VaneCraft, an agent-driven framework for rotor generation, inverse recovery, and editing through a unified analytical representation.", "limit_evidence": ""}, "2611.33594": {"points": [{"subtitle": "참여형 벤치마크 구축", "desc": "연구진은 누구나 쉽게 참여해 두 쌍 중 더 비슷한 것을 고르는 강제 선택 방식을 통해, 깨끗한 선호 데이터를 꾸준히 모을 수 있는 대화형 플랫폼인 Aligned Machine을 도입했는데요. 비전문가도 쉽게 접근할 수 있어서 안정적인 데이터 수집과 강건한 집계를 뒷받침한다는 겁니다. 뭔 소리냐면, 사람들이 직관적으로 참여하는 과정에서 모델 평가용 데이터를 차곡차곡 쌓는 구조라는 말이에요.", "evidence": "Participants complete a cognitively-natural, forced-choice task, comparing two pairs of items (text or images) and selecting which pair is more similar."}, {"subtitle": "모델 평가 결과", "desc": "초기 배포에서 115명의 참가자가 2,875개의 레이블된 쌍을 모았고, 이를 바탕으로 12개의 널리 쓰이는 임베딩 모델을 평가해 봤더니 모델과 사람의 판단이 부분적으로만 일치한다는 사실이 드러났는데요. 텍스트 전용 모델이 멀티모달 모델보다 전체 일치도가 더 높았다는 장점이 있는 반면, 멀티모달 성능은 이미지 간 비교에서 가장 강하고 텍스트 간 비교에서 가장 낮게 나타나는 등 작업 유형별로 차이를 보였다는 겁니다.", "evidence": "Using HASB, we evaluated 12 widely used embedding models and found only partial alignment between embedding similarity and human judgments."}, {"subtitle": "향후 확장성과 의의", "desc": "이 플랫폼은 참여가 늘어날수록 함께 진화하도록 설계되어 있어서, 장기적인 분석이나 도메인별 연구뿐만 아니라 편향 감지나 개념 표류 측정까지 뒷받침할 수 있다고 하는데요. 쉽게 말하면, 대중의 참여와 엄격한 비교 평가를 결합하여 임베딩 모델의 의미적 일치 여부를 꾸준히 감사할 수 있는 확장 가능한 프레임워크를 제공한다는 겁니다.", "evidence": "By combining accessible public participation with rigorous comparative evaluation, HASB provides a scalable and accountable framework for auditing semantic alignment in embedding models."}], "easy1_evidence": "Existing benchmarks typically rely on static, expert-labeled pairs with coarse Likert-style annotations, limiting scalability and making it difficult to obtain consistent, high-confidence annotations.", "easy2_evidence": "We introduce Aligned Machine, an interactive, public-facing platform that transforms broad participation into a continuously growing Human-Aligned Similarity Benchmark (HASB) for evaluating semantic alignment in embedding-based systems.", "topic_evidence": "We introduce Aligned Machine, an interactive, public-facing platform that transforms broad participation into a continuously growing Human-Aligned Similarity Benchmark (HASB) for evaluating semantic alignment in embedding-based systems.", "limit_evidence": ""}, "2611.33555": {"points": [{"subtitle": "PeerShift 시험 세트 구축", "desc": "기계학습과 생명과학, 사회과학을 포함하는 여러 분야에서 5,430개의 리뷰를 모아 새로운 시험 세트인 PeerShift를 만들었는데요. 학문 분야마다 다른 리뷰 규칙과 다양한 AI 생성 방식을 섞어서 검증의 정확도를 높였다는 겁니다. 뭔 소리냐면, 한 가지 분야가 아니라 여러 학문의 특성이 섞인 복잡한 환경에서 탐지기가 얼마나 잘 작동하는지 시험해 봤다는 말이에요.", "evidence": "We evaluate PeerReveal on PeerShift, a new, challenging test set of 5,430 reviews spanning multiple domains, including machine learning, life sciences, and social sciences, combining variation in disciplinary review conventions with diverse AI review-production mechanisms."}, {"subtitle": "기본 탐지기 성능", "desc": "새로 개발한 탐지기인 PeerReveal은 일반적인 학습을 거쳤을 때 이 벤치마크에서 70.52%의 종합 Macro-F1을 기록했는데요. 이는 가장 성능이 좋았던 기존 기준 모델보다 11.48포인트 더 나아진 결과로 보입니다.", "evidence": "With regular training, PeerReveal achieves 70.52% pooled Macro-F1 on this benchmark, improving over the strongest baseline by 11.48 points."}, {"subtitle": "적대적 학습을 통한 성능 향상", "desc": "까다로운 리뷰를 만들어내도록 최적화된 작은 지역 생성기를 활용해 적대적 학습 프레임워크를 개발했는데요. 이 방식을 적용했더니 종합 Macro-F1 성능이 70.52%에서 82.40%까지 크게 높아졌다는 겁니다.", "evidence": "We develop an effective and practical adversarial training framework that further improves the detector's generalization using a small local generator optimized to produce challenging reviews, raising pooled Macro-F1 from 70.52% to 82.40%."}], "easy1_evidence": "Can we distinguish fully AI-generated reviews from those using AI only to rewrite human judgement?", "easy2_evidence": "We develop an effective and practical adversarial training framework that further improves the detector's generalization using a small local generator optimized to produce challenging reviews, raising pooled Macro-F1 from 70.52% to 82.40%.", "topic_evidence": "To this end, we introduce PeerReveal, a new detector that grounds its decisions in learned relationships between a review's claims and reference claims drawn from AI-generated reviews of the same paper, complemented by review-level textual signals.", "limit_evidence": ""}, "2611.33394": {"points": [{"subtitle": "확신 점수 모델 설계", "desc": "연구진은 2B 파라미터 크기의 단일 백본을 바탕으로, 최종층 숨은 상태에 선형 확신 점수 머리를 붙이거나 닫힌 모델을 위한 텍스트 전용 메타모델을 훈련했어요. 데이터는 약 98%의 SQuAD와 나머지는 TruthfulQA로 이루어진 채점된 답변들을 썼다는 겁니다. 뭔 소리냐면, AI가 낸 답의 맞고 틀림을 점수로 매겨서 걸러낼 수 있도록 구조를 짜 봤다는 말이에요.", "evidence": "A linear confidence score head is fitted to the final-layer hidden state of the frozen LLM backbone, and text-only metamodels are trained as an alternative for closed models."}, {"subtitle": "기준 모델과의 성능 비교", "desc": "여러 기준 모델들과 성능을 견주어 봤더니, 제안한 확신 점수 머리가 모든 기준과 메타모델보다 뛰어난 모습을 보였는데요. 높은 정확도를 요구하는 목표 속에서도 가장 많은 작업량을 자동으로 처리해 냈다고 해요. 프롬프트로 얻은 확신 점수는 그럴듯해 보여도 문턱값으로 쓰기에는 해상도가 부족했다는 겁니다.", "evidence": "Against multiple baselines, the confidence score head outperforms all baselines and metamodels, automating the largest fraction of the workload at high accuracy targets."}, {"subtitle": "활용 범위와 기대 효과", "desc": "이러한 확신 점수 체계는 LLM 기반 에이전트가 자동으로 일할 때의 안전성을 높여준다고 해요. 나아가 안전성이나 준법 감시 같은 다른 속성들을 걸러내는 데도 맞춤형으로 쓸 수 있다는 겁니다. 쉽게 말하면, AI가 실수를 줄이고 더 안전하게 제 역할을 하도록 돕는 튼튼한 울타리가 생겼다는 말이에요.", "evidence": "The proposed confidence scoring framework enhances the safety of automating LLM-based agents and can be adapted to gate other properties, including safety or compliance."}], "easy1_evidence": "However, LLMs may produce incorrect answers with high confidence, limiting their applicability in decisions that affect individuals and organizations.", "easy2_evidence": "This work uses supervised learning to train models to predict the correctness of LLM-generated answers, enabling automated confident responses and routing uncertain ones for human review.", "topic_evidence": "The proposed confidence scoring framework enhances the safety of automating LLM-based agents and can be adapted to gate other properties, including safety or compliance.", "limit_evidence": "Although transferability to unseen datasets is modest, the confidence score head remains the most robust approach."}, "2611.33322": {"points": [{"subtitle": "브랜드 회상과 분류 측정", "desc": "연구진은 333개의 제품 카테고리에 속한 1,000개의 기업용 소프트웨어 브랜드를 두고 모델의 성능을 따로 측정해 봤는데요. 젬마 4 12B 모델에 물어봤을 때 510개를 떠올려 51%의 회상률을 기록했다는 겁니다. 뭔 소리냐면, 모델이 브랜드를 기억하는 능력과 카테고리를 맞추는 능력이 서로 다를 수 있다는 말이에요.", "evidence": "On Gemma 4 12B, with no external retrieval, category prompts elicit 510 brands (51.0%)."}, {"subtitle": "선다형 검사와 오류율", "desc": "선다형 카테고리 시험을 해 봤더니 787개 브랜드는 정답이 1등이었지만 194개는 엉뚱한 것이 먼저 나왔고 19개는 구분이 잘 안 됐는데요. 구분이 끝난 981개 중 전체 오류율은 19.8%였다고 해요. 하지만 확률 차이가 0.6보다 큰 547개 브랜드의 경우 오류율이 3.5%까지 뚝 떨어졌다는 겁니다.", "evidence": "Among the 981 separated rankings, the error rate is 19.8%."}, {"subtitle": "버전별 변화와 감성 분석", "desc": "젬마의 네 세대를 거치며 측정한 회상률은 각각 39.8%, 44.3%, 51.1%, 51.0%로 나타났는데요. 표현 방식을 바탕으로 만든 감성 지표는 실제 고객 평점과 선형적인 연관성이 거의 없었다고 해요. 쉽게 말하면, 기술적 범위는 회상과 관련이 있어 보이지만 감성 지표만으로는 실제 평점을 알기 어렵다는 셈이에요.", "evidence": "A separate representation-based sentiment measure has little linear association with customer ratings (r=0.03, n=921)."}], "easy1_evidence": "A language model can name a brand without classifying it correctly.", "easy2_evidence": "The findings support reporting recall and category accuracy separately.", "topic_evidence": "This study measures these outcomes separately for 1,000 B2B SaaS Brands across 333 product categories.", "limit_evidence": "These are within-cohort measurements, not calibrated confidence estimates."}, "2611.33263": {"points": [{"subtitle": "임상 기반 분류 체계 도입", "desc": "연구진은 해로움이 무엇인지, 누가 관련되었는지, 언제 발생하는지 세 가지 차원으로 나누는 임상 기반 분류 체계를 소개했는데요, 해로움의 성격과 개입 결정을 분리해서 안전 정책을 명시적인 임상가 큐레이션 지침으로 지정할 수 있게 만들었다는 거예요. 뭔 소리냐면, 모델 가중치 외부에서 감사와 업데이트를 할 수 있다는 말이에요.", "evidence": "We introduce a clinically grounded taxonomy that characterizes harm along three dimensions: what the harm is, who is involved, and when it occurs."}, {"subtitle": "MindGuard2 모델 훈련과 성능", "desc": "연구진은 짧은 추론 흔적과 추론 길이 페널티가 있는 강화 학습을 써서 MindGuard2라는 35B-A3B 추론 기반 가드 모델을 훈련했는데요, 공개 벤치마크와 실제 대화에서 훨씬 더 큰 GLM-5.3과 비슷한 균형 정확도를 대략 10배 낮은 중앙값 지연 시간에서 달성했다고 해요. 쉽게 말하면, 추론의 이점을 지키면서도 연산 부하를 줄였다는 겁니다.", "evidence": "On two public benchmarks and real-world conversations, MindGuard2 achieves balanced accuracy comparable to the substantially larger GLM-5.3 at approximately 10x lower median latency, advancing the accuracy-latency Pareto frontier."}, {"subtitle": "오탐지율 감소와 자원 공개", "desc": "이 모델은 높은 재현율에서 낮은 오탐지율을 달성해 안전하지 않은 상황을 감지하는 것과 지원을 방해하고 사용자 신뢰를 떨어뜨릴 불필요한 개입 위험 사이의 균형을 돕는다는 장점이 있는데요, 연구진은 합성 데이터와 대화, 분류 체계로 주석을 단 공개 벤치마크를 함께 공개했다고 해요.", "evidence": "Furthermore, it achieves low false-positive rates at high recall, helping balance the need to detect unsafe situations against the risk of unnecessary interventions that may disrupt support and undermine user trust."}], "easy1_evidence": "Existing guard models primarily identify categories of harmful content, often overlooking the context needed to determine an appropriate response.", "easy2_evidence": "We then train MindGuard2, a 35B-A3B reasoning-based guard model using supervised fine-tuning on short reasoning traces followed by reinforcement learning with a reasoning-length penalty, to minimize inference overhead while preserving the benefits of reasoning.", "topic_evidence": "We introduce a clinically grounded taxonomy that characterizes harm along three dimensions: what the harm is, who is involved, and when it occurs.", "limit_evidence": ""}, "2611.33190": {"points": [{"subtitle": "다양한 역할 비교", "desc": "연구진은 Jev를 최적화 도구, 성능 예측기, 영역 안내자 등 세 가지 방식으로 나누어 여덟 가지 AI 튜닝 작업에서 전통적인 방식과 대규모 언어 모델(LLM)에 견주어 봤는데요. 전통적인 최적화 도구는 여덟 번 중 여섯 번에서 1위를 차지했고, 기존 예측기 역시 일곱 번이나 Jev보다 뛰어난 성능을 보였다는 거예요. 뭔 소리냐면, 범용 모델이 모든 면에서 기존 방식을 압도한 건 아니라는 말이에요.", "evidence": "To assess where it helps, we compare its use as an optimizer, performance predictor, and region guider against conventional methods and a large language model (LLM) on eight AI tuning tasks."}, {"subtitle": "영역 안내의 효과", "desc": "그렇지만 Jev를 영역 안내자로 쓸 때는 원래의 튜너가 고른 것보다 혼란도가 더 낮은 설정값을 찾아내는 결과를 냈는데요. 추가적인 결정 시간과 응용 프로그램 프로그래밍 인터페이스(API) 비용을 받아들일 수 있다면 품질을 높이는 이득을 얻을 수 있다는 겁니다. 쉽게 말하면, 특정 역할에서는 비용을 더 쓰는 대신 더 나은 결과를 챙길 수 있다는 셈이에요.", "evidence": "Through region guidance, however, it finds configurations with lower perplexity than those selected by the native tuner, offering a quality gain when additional decision time and API fees are acceptable."}, {"subtitle": "실용적인 권고사항 도출", "desc": "이러한 결과들을 바탕으로 연구진은 결정 역할을 어떻게 고를지, 기존 예측기를 계속 남겨둘지, 그리고 튜닝 품질과 비용을 어떻게 맞출지에 대한 실용적인 권고사항들을 내놓았는데요. 비용과 성능 사이에서 어떤 방식을 택해야 할지 구체적인 기준을 제시했다는 말이에요.", "evidence": "These findings yield actionable recommendations on selecting the decision role, retaining conventional predictors, and balancing tuning quality against cost."}], "easy1_evidence": "AI configuration tuning searches for settings that improve the performance of AI systems under a limited budget.", "easy2_evidence": "Through region guidance, however, it finds configurations with lower perplexity than those selected by the native tuner, offering a quality gain when additional decision time and API fees are acceptable.", "topic_evidence": "We investigate whether general-purpose decision models can guide tuning, using Jev as a deployed representative that returns structured choices and numeric scores across diverse tasks.", "limit_evidence": ""}, "2611.33160": {"points": [{"subtitle": "예산 제약과 세 가지 축", "desc": "연구진은 AI 시스템이 훈련 예산, 결정 시간 예산, 컨텍스트 인프라 예산이라는 세 가지 축으로 움직인다고 봤는데요. 기존 연구는 모델 크기나 결정 과정에만 집중했지만, 이번에는 결정을 내리기 전에 필요한 정보를 채워주는 인프라 예산에 주목했다는 거예요. 뭔 소리냐면, AI를 둘러싼 환경 전체를 분석 단위로 잡아야 한다는 말이에요.", "evidence": "We frame a model as $P_\theta(d\nic)$ within a system governed by three budgets: training $B_\theta$, decision-time $B_d$, and context-infrastructure $B_c$."}, {"subtitle": "실패 원인 분석과 다섯 단계 수명 주기", "desc": "정보가 얼마나 가치 있는지 따져보고, 배포된 상태와 모델이 보는 정보를 따로 나누어 가용성과 정확도에서 생기는 실패를 짚어봤는데요. 이어서 현재 쓰이는 기술들을 다섯 가지 단계의 정보 흐름으로 정리하고, 통제된 예산 실험과 비용 대비 효용 곡선을 제안했다는 거예요. 쉽게 말하면, 정보가 어떻게 흘러가고 어디서 막히는지 낱낱이 파헤쳐 보자는 겁니다.", "evidence": "We then organize current mechanisms through a five-operation context lifecycle and propose controlled budget interventions and utility-cost curves for evaluation."}, {"subtitle": "앞으로의 연구 과제와 방향", "desc": "연구진은 앞으로 실효성 있는 보고와 상호작용 데이터, 전체 비용이 반영된 인프라 구축이 중심이 되어야 한다고 밝혔는데요. 적응형 시스템의 안전성과 거버넌스까지 함께 챙겨야 한다는 점을 강조했다는 거예요. 뭔 소리냐면, 똑똑한 AI를 만들려면 주변 인프라와 안전장치까지 판을 새로 짜야 한다는 말이에요.", "evidence": "The resulting agenda centers on grounded reporting, interaction-data and full-cost infrastructure, and safety and governance for persistent, adaptive systems."}], "easy1_evidence": "Many failures of deployed AI arise not from weak inference but from a mismatch between the state a task depends on and the context available when the system acts.", "easy2_evidence": "We call the effort to reduce this bottleneck context scaling.", "topic_evidence": "We call the effort to reduce this bottleneck context scaling.", "limit_evidence": ""}, "2611.33086": {"points": [{"subtitle": "불확실성 신호 수집", "desc": "연구진은 버트(BERT) 기반 개체명 인식 모델에 보조 머리를 달고 몬테 카를로(MC) 드롭아웃을 써서 시작과 끝 경계 확률이나 퍼지 엔트로피 같은 3가지 신호를 뽑아냈거든요. 뭔 소리냐면, 데이터가 얼마나 헷갈리는지 그 정도를 숫자로 챙겨둔다는 말이에요.", "evidence": "Using a BERT-based NER model augmented with two auxiliary span-boundary prediction heads, we apply Monte Carlo (MC) dropout at inference time to derive three mention-level proxy signals: the MC-averaged start-boundary probability, the MC-averaged end-boundary probability, and De Luca-Termini fuzzy entropy computed over the Begin-Inside-Outside (BIO) predictive distribution."}, {"subtitle": "후보 생성 단계에 적용", "desc": "그렇게 모은 신호들을 가지고 개체 연결을 위한 후보 생성 단계에서 퍼지 잘라내기 기준을 조절하도록 만들었는데요. 모호한 상황 속에서도 후보를 더 알맞게 잘 건져내도록 돕는 역할을 하는 겁니다.", "evidence": "These signals are used to adapt the fuzzy cutoff in candidate generation (CG) for EL."}, {"subtitle": "성능 평가 결과", "desc": "마이트 아택(MITRE ATTCK) 지식베이스와 연결된 아노시티알(AnnoCTR) 데이터셋에서 시험해 봤더니, 상위 10개 재현율이 0.6186에서 0.7966으로 올랐다는 걸 확인했어요. 쉽게 말하면, 헷갈리는 정보까지 품고 갔더니 원하는 걸 찾아내는 능력이 더 좋아졌다고 보입니다.", "evidence": "On the AnnoCTR dataset linked to the MITRE ATTCK knowledge base, the boundary-aware and dual-signal fuzzy linking approaches improve Recall@10 from 0.6186 to 0.7966."}], "easy1_evidence": "Entity Resolution (ER) pipelines often collapse ambiguity into early hard decisions: upstream Named Entity Recognition (NER) selects a single span and type, and downstream Entity Linking (EL) treats that choice as ground truth.", "easy2_evidence": "On the AnnoCTR dataset linked to the MITRE ATTCK knowledge base, the boundary-aware and dual-signal fuzzy linking approaches improve Recall@10 from 0.6186 to 0.7966.", "topic_evidence": "Therefore, this work presents a proof-of-concept for uncertainty-aware ER that treats uncertainty as native data that should be preserved and exploited throughout ER pipelines.", "limit_evidence": "The contribution lies not in an end-to-end optimised ER pipeline but in establishing uncertainty preservation as a viable and beneficial component of ER pipelines, enabling downstream EL to make better-informed decisions under uncertainty."}, "2611.33012": {"points": [{"subtitle": "실험 설계와 오류 주입", "desc": "연구진은 416개의 결함 있는 경로와 8가지 오류 범주, 그리고 6개의 오픈 웨이트(open-weight) 거대 언어 모델(LLM) 판사를 활용해 실험을 설계했는데요. 올바른 경로와 결함 있는 경로를 서로 비교해서 판사들이 단순히 많은 행동을 위험하다고 표시하는 게 아니라 실수를 진짜로 알아보는지 측정해 봤다는 거예요. 뭔 소리냐면, 무조건 불합격을 주는 게 아니라 진짜 오류를 가려내는지 엄격하게 뜯어봤다는 말이에요.", "evidence": "The experiments include 416 faulty trajectories, eight error categories, and six open-weight LLM judges."}, {"subtitle": "임상 증거와 EHR 기록의 영향", "desc": "판사에게 최종 답변만 보여주면 바른 경로의 56%를 위험하다고 잘못 표시하면서도 최종 결과가 안 바뀐 오류는 구별하지 못했는데요. 전체 경로 정보와 실제 전자건강기록(EHR) 응답을 함께 주었더니 안전하지 않은 행동을 구별하는 점수가 0.75까지 올라가고 판별력도 0.39만큼 좋아졌다는 겁니다. 쉽게 말하면, 판사에게 판단의 근거가 되는 원본 기록을 쥐어줄수록 실수를 잡아내는 눈이 확실히 밝아진다는 거예요.", "evidence": "When shown only the final answer, judges cannot distinguish errors that leave it unchanged, while flagging 56% of correct trajectories."}, {"subtitle": "추론 과정 포함의 한계와 규칙 기반 검사기 결합", "desc": "오히려 에이전트의 추론 과정을 포함하는 것은 전체 성능을 높이지 못했고 잘못 보고된 임상 값을 찾아내는 능력을 0.18만큼 떨어뜨렸는데요. 벤치마크의 원래 채점기는 의도적으로 건너뛴 검사 38개를 모두 통과시켰지만, 거대 언어 모델(LLM) 판사에 전체 전자건강기록(EHR) 기반의 규칙 기반 검사기를 섞었더니 주입된 결함의 97%를 찾아냈다는 겁니다. 다만 메드가마(MedGemma)는 일반 목적 모델보다 성적이 낮았고 잠재적으로 위험한 약물 과다 복용을 놓친 유일한 판사였다고 해요.", "evidence": "We also find that the benchmark's original grader accepts all 38 trajectories with an intentionally skipped laboratory check, while combining LLM judges with a rule-based checker informed by the full EHR record detects 97% of injected faults."}], "easy1_evidence": "As clinical AI agents begin to interact with electronic health records (EHRs), large language models (LLMs) are increasingly used to evaluate their actions.", "easy2_evidence": "With full trajectory information, the ability to distinguish unsafe actions from correct ones reaches a score of 0.75, and providing actual EHR responses improves discrimination by 0.39.", "topic_evidence": "We investigate this question using MedAgentBench by introducing controlled clinical errors into verified agent trajectories.", "limit_evidence": "which remain the hardest errors to detect."}, "2611.32848": {"points": [{"subtitle": "측정 도구 오류의 영향", "desc": "연구진은 측정 도구에서 발생하는 오류가 양자화(모델 경량화 기술)의 실제 효과와 섞여 잘못 보고될 수 있음을 지적했어요. 모든 정밀도에서 일정하게 나타나는 오류는 비교 대상을 축소시키기만 하지만, 압축 방식과 상호작용하는 오류는 없던 효과를 만들어내거나 방향을 뒤집기도 한다는 거예요. 뭔 소리냐면, 평가 방식 자체의 결함이 모델 성능 변화로 오인될 수 있다는 말입니다.", "evidence": "Instrument error that is the same at every precision can shrink a paired comparison but cannot create or reverse an effect."}, {"subtitle": "평가 방식 간의 불일치", "desc": "20억 개 미만의 매개변수를 가진 8개의 지시어 미세조정 모델을 대상으로 네 가지 측정 방식을 비교해 봤는데요. 빈칸 채우기와 선다형 객관식 채점은 서로의 잡음이 허용하는 범위를 훨씬 넘어설 정도로 결과가 달랐고, 이들의 상관계수는 최고 0.77에 비해 고작 0.10에 불과했다고 해요. 쉽게 말하면, 어떤 평가 방식을 쓰느냐에 따라 압축 모델의 성능이 완전히 다르게 평가된다는 겁니다.", "evidence": "Cloze and lettered multiple-choice scoring disagree about the effect of quantization far more than their noise allows: their estimates correlate at \r{ho} = 0.10, against a ceiling of about 0.77."}, {"subtitle": "배치 의존성과 모델별 차이", "desc": "LLM.int8() 방식은 어떤 항목들이 같은 배치로 묶이느냐에 따라 답변과 생성 결과가 달라졌고 단순 패딩만으로도 답변이 바뀔 수 있었어요. 반면에 NF4 방식은 배치와 무관하게 일정한 결과를 보여주어 상대적인 안정성을 확인했는데요. 다만 가장 크게 보고된 보정 손실 중 상당수는 응답 편향의 변화에서 기인한다는 점을 함께 밝혔습니다.", "evidence": "LLM.int8() answers and generations depend on which items share a batch, and padding alone changes its answers."}], "easy1_evidence": "Error that interacts with quantization can do both, and it is reported as an effect of quantization.", "easy2_evidence": "Cloze and lettered multiple-choice scoring disagree about the effect of quantization far more than their noise allows: their estimates correlate at \r{ho} = 0.10, against a ceiling of about 0.77.", "topic_evidence": "We estimate this interaction for four measurement choices in 8 instruction-tuned models below two billion parameters, at float16, LLM.int8() and NF4, on identical items.", "limit_evidence": ""}, "2611.32646": {"points": [{"subtitle": "로커스트 벤치마크 구축", "desc": "연구진은 네덜란드 통계청의 2천 개 넘는 표와 의미론적 지식 그래프를 묶어서 LOCuST 벤치마크를 만들었어요. 그래프가 표의 정의와 계층 구조를 설명해 주니까, 시스템이 수많은 코드 속에서 알맞은 표를 찾아낼 수 있게 된다는 거예요. 뭔 소리냐면, 복잡한 메타데이터를 모델이 이해할 수 있는 길잡이를 붙여 줬다는 말이에요.", "evidence": "To address this gap, we introduce LOCuST, a text-to-SQL benchmark that pairs over two thousand English and Dutch tables from Statistics Netherlands with a semantic knowledge graph."}, {"subtitle": "다양한 질문과 새로운 평가 지표", "desc": "이 벤치마크에는 단순 값 가져오기부터 합계, 비율 계산, 조인까지 여러 쿼리와 집계 유형에 맞춰 전문가가 직접 단 질문들이 들어 있어요. 표준 평가 방식에 더해, 정답이 틀렸어도 쿼리가 얼마나 근접했는지 보여 주는 관측 F1 측정 지표도 함께 넣었거든요. 쉽게 말하면, 질문의 난이도뿐만 아니라 모델의 오차까지 세밀하게 잴 수 있게 만들었다는 거예요.", "evidence": "Alongside standard evaluation measures, we introduce an observation F1 metric that measures how close a query is to the ground truth even when the answers are different."}, {"subtitle": "최신 언어 모델 평가 결과", "desc": "연구진이 여러 최신 대형 언어 모델들을 시험해 봤는데요, 모델들이 공공 통계 질문에 답하는 올바른 SQL 코드를 작성하는 데 큰 어려움을 겪었다고 밝혔어요. 성능이 부족하다는 단점이 드러났지만, 거꾸로 말하면 앞으로 공공 데이터 분야에서 모델들이 풀어야 할 명확한 과제가 생겼다는 뜻이기도 하거든요.", "evidence": "We evaluate a variety of state-of-the-art LLMs and find that they struggle to write SQL that answers the questions correctly."}], "easy1_evidence": "However, existing text-to-SQL benchmarks do not resemble this setting.", "easy2_evidence": "We evaluate a variety of state-of-the-art LLMs and find that they struggle to write SQL that answers the questions correctly.", "topic_evidence": "To address this gap, we introduce LOCuST, a text-to-SQL benchmark that pairs over two thousand English and Dutch tables from Statistics Netherlands with a semantic knowledge graph.", "limit_evidence": ""}, "2611.32320": {"points": [{"subtitle": "모나드 기반 알파-베타 가지치기", "desc": "연구진은 연속자 모나드와 독서자 모나드를 섞어서 알파-베타 가지치기를 새롭게 정의해 봤는데요. 이동 가능한 수의 타입을 건드리지 않고 모나드 결과 안에 제한 범위를 넣는 방식이라는 겁니다.", "evidence": "We present a monadic formulation of alpha-beta pruning based on the combination of the continuation monad and the reader monad."}, {"subtitle": "최적의 플레이 계산과 성능", "desc": "결과 타입에 이동 순서까지 확장해서 최적의 결과와 플레이를 모두 찾아내도록 만들었는데요. 틱택토 게임에 적용해 봤더니 전체 탐색과 비교해서 평가하는 플레이 수가 39배나 줄어드는 효율을 보였다는 말이에요.", "evidence": "We illustrate our approach with an implementation of Tic-Tac-Toe, observing a 39-fold reduction in the number of plays evaluated, compared with exhaustive search, in computing an optimal play."}, {"subtitle": "정확성 증명과 의의", "desc": "이 모나드 방식이 기존의 완전 탐색 미니맥스 검색과 완전히 똑같은 결과를 낸다는 점을 공식적으로 증명했어요. 뭔 소리냐면, 인공지능의 기본 알고리즘을 표준 모나드 추상화로 표현하고 검증할 수 있다는 걸 보여줬다는 말이에요.", "evidence": "Finally, we formally establish the correctness of our construction by proving that the monadic alpha-beta search computes the same optimal outcomes and plays as exhaustive minimax search."}], "easy1_evidence": "Unlike previous approaches that encode alpha-beta bounds into the types of available moves, our construction records these bounds within monadic outcomes, leaving the move types unchanged.", "easy2_evidence": "We illustrate our approach with an implementation of Tic-Tac-Toe, observing a 39-fold reduction in the number of plays evaluated, compared with exhaustive search, in computing an optimal play.", "topic_evidence": "We present a monadic formulation of alpha-beta pruning based on the combination of the continuation monad and the reader monad.", "limit_evidence": ""}, "2611.32304": {"points": [{"subtitle": "3D 트리거 최적화", "desc": "첫 번째 단계에서는 정책 모델을 고정한 채로 미분 가능한 렌더링과 멀티모달 감독을 활용해 3D 트리거의 질감과 크기 등을 최적화했는데요. 뭔 소리냐면, 적은 양의 독성 시연 데이터 속에서도 트리거와 목표 행동 사이의 연결 고리를 더 튼튼하게 만든다는 말이에요.", "evidence": "Stage I freezes the policy and uses differentiable rendering and multimodal supervision to optimize a 3D trigger's texture, translation, and scale, strengthening trigger-target associations from limited poisoned demonstrations."}, {"subtitle": "이중 LoRA 적용과 분리", "desc": "두 번째 단계에서는 소스 선택형 이중 LoRA(Low-Rank Adaptation) 방식을 써서 정상적인 업데이트와 뒷문 업데이트를 서로 분리했는데요. 이렇게 하면 두 학습 과정 사이의 간섭을 줄일 수 있고, 마지막에는 열 단위 보정과 분석적 융합을 거쳐 하나의 통합된 정책으로 합친다는 거예요.", "evidence": "Building on the optimized trigger, Stage II applies source-selective dual-LoRA adaptation to decouple clean and backdoor updates and mitigate their interference, followed by learned column-wise calibration and analytic fusion into a unified policy."}, {"subtitle": "실험 결과 및 성능", "desc": "OpenVLA와 $\\pi_0$ 계열 모델을 네 가지 LIBERO 스위트에서 실험해 봤더니 모든 기존 공격 방식보다 일관된 성능 향상을 보였다고 하는데요. 쉽게 말하면, LIBERO-Spatial 환경의 OpenVLA-OFT에서 단 1%의 독성 데이터만으로 목표 성공률은 86.4%, 기존 작업 성공률은 95.2%에 가까웠다고 보입니다.", "evidence": "With only 1% poisoned data, our method achieves 86.4% target success and 95.2% clean-task success on OpenVLA-OFT in LIBERO-Spatial."}], "easy1_evidence": "However, high poisoning rates may compromise clean-task performance, whereas low rates leave target-trajectory supervision scarce and backdoor learning vulnerable to interference from dominant clean-task updates.", "easy2_evidence": "To resolve this trade-off at low poisoning rates, we propose a two-stage co-optimization framework guided by vision, language, and action.", "topic_evidence": "To resolve this trade-off at low poisoning rates, we propose a two-stage co-optimization framework guided by vision, language, and action.", "limit_evidence": ""}, "2611.32247": {"points": [{"subtitle": "VerClin 프레임워크 도입", "desc": "환자 대화 내용을 사례로 바꾸고 가이드라인의 조건과 예외 사항을 실행 가능한 지식으로 추출해 내는데요. 결정론적 추론기를 써서 불확실성을 남기면서도 추적 가능한 가이드라인 일치 결과를 만들어 낸다는 겁니다.", "evidence": "We introduce VerClin, an explainable framework that extracts guideline conditions, exclusions, recommendations, and priorities into executable knowledge and represents patient conversations as scoped cases."}, {"subtitle": "전문 에이전트와 형식 제약 채널", "desc": "여러 전문 에이전트가 가이드라인이 사례에 맞는지 확인하고, 상담 모델이 형식 제약 채널을 통해 가이드를 종합하는데요. 우선순위와 트리거 강도 순서를 바탕으로 위험도가 높지만 트리거가 약한 가이드라인까지 수면 위로 끌어올린다는 말이에요.", "evidence": "Multiple specialty agents then screen matched guidelines for case applicability, and a consultation model synthesizes accepted guidance through specialty recommendations and a sentence-preserving formal-constraint channel."}, {"subtitle": "성능 평가와 구성 요소 분석", "desc": "HealthBench Hard와 HealthBench Professional에서 직접 생성 방식과 상위 5개 검색증강생성 방식보다 더 뛰어난 결과를 보였는데요. LLMEval-Med 하위 집합에서는 직접 생성보다 앞서고 상위 5개 검색증강생성과는 비슷하다는 점을 확인했어요.", "evidence": "VerClin outperforms direct generation and Top-5 RAG on HealthBench Hard and HealthBench Professional."}], "easy1_evidence": "Clinical reasoning from incomplete or conflicting patient evidence must account for low-probability but high-risk concerns while remaining grounded in health guidelines.", "easy2_evidence": "We introduce VerClin, an explainable framework that extracts guideline conditions, exclusions, recommendations, and priorities into executable knowledge and represents patient conversations as scoped cases.", "topic_evidence": "Refining and Aligning Clinical Reasoning with Health Guidelines via Formal Constraints", "limit_evidence": ""}, "2611.32209": {"points": [{"subtitle": "교차 기억 추론", "desc": "엑스마인드는 최근 교통 상황을 담은 작업 기억과 위험했던 순간의 에피소드 기억을 합쳐서 작동하는데요. 에이전트가 먼저 현재 상황에서 결정을 내린 다음에, 꺼내온 과거 경험과 비교해 보면서 충돌이 생기면 수정된 두 번째 결정을 내린다는 말이에요.", "evidence": "XMind integrates working memory of recent traffic states with episodic memory of critical risk events."}, {"subtitle": "반사실적 검증", "desc": "믿을 수 있는 에피소드 기억을 만들기 위해서 교통 환경을 흔들며 반사실적 시뮬레이션을 돌려 다른 행동들을 시험해 보는데요. 검증된 결과들을 구조화된 위험 캡슐 형태로 저장해 두고, 공간 위험 패턴과 시나리오 의미를 함께 맞춰서 찾아낸다는 겁니다.", "evidence": "To construct reliable episodic memory, XMind evaluates alternative actions through counterfactual rollouts under perturbed traffic conditions and stores the verified outcomes as structured risk capsules."}, {"subtitle": "시뮬레이션과 성능", "desc": "폐쇄 루프 고속도로 시뮬레이션에서 엑스마인드는 83.3퍼센트에서 93.3퍼센트 사이의 성공률을 기록했는데요. 케이-리스크(K-Risk) 평가에서도 보지 못했던 실제 고위험 상황에서 더 낮은 결정 위험을 보여주었다는 거예요.", "evidence": "Across closed-loop highway simulations, XMind achieves success rates of 83.3-93.3%, exceeding the strong baseline by 6.6 percentage points on average."}], "easy1_evidence": "Memory-augmented large language model (LLM) driving agents can reuse past experience, yet previously learned corrections often fail to transfer when traffic conditions change.", "easy2_evidence": "We introduce XMind, a training-free framework that enables LLM-based driving to \"Think Twice\" through cross-memory reasoning.", "topic_evidence": "We introduce XMind, a training-free framework that enables LLM-based driving to \"Think Twice\" through cross-memory reasoning.", "limit_evidence": ""}, "2611.31969": {"points": [{"subtitle": "기존 증류 방식의 한계", "desc": "여러 전문가 모델을 하나로 합치는 기존의 온폴리시 증류(OPD) 방법은 교사 모델의 외삽을 통해 감독을 강화하지만, 학생 모델 자체의 학습 과정은 반영하지 못한다는 한계가 있었어요. 뭔 소리냐면, 학생이 실제로 얼마나 성장했는지는 보지 않고 교사의 방향만 강요했다는 말이에요.", "evidence": "Recent methods strengthen supervision through teacher extrapolation, constructing stronger proxy teachers that allow distilled students to surpass the original specialists."}, {"subtitle": "덱스오피디(DexOPD) 방법의 도입", "desc": "이를 해결하려고 연구진은 교사 외삽 감독을 유지하면서 과거의 학생 모델을 기준 삼아 학생 스스로를 확장하는 이중 외삽법(Dual-extrapolation on-policy distillation)을 적용했어요. 여러 초기 노이즈로 탐색을 넓히고 작업 보상을 활용해 후보 품질의 차이를 정규화된 보조 회귀 방향으로 바꾼다는 겁니다.", "evidence": "DexOPD retains extrapolated teacher supervision while leveraging a lagging historical student as the reference for student self-extrapolation."}, {"subtitle": "성능 평가 결과", "desc": "젠에발(GenEval), 광학 문자 판독(OCR), 드로우벤치(DrawBench)에서 시험해 봤더니, SD3.5-Medium 통합 학생 모델이 젠에발 0.9736, OCR 0.9515, 드로우벤치 미학 점수 6.4875를 기록했는데요, 기존 전문가 교사들과 모든 비교 모델들을 뛰어넘는 성과를 냈다는 거예요.", "evidence": "The resulting unified SD3.5-Medium student achieves a GenEval reward of 0.9736, an OCR score of 0.9515, and a DrawBench Aesthetic score of 6.4875, surpassing the corresponding specialist teachers as well as all evaluated OPD and multi-task reinforcement learning baselines across these three benchmarks while preserving standard single-model inference."}], "easy1_evidence": "However, their extrapolation directions remain defined solely by frozen teacher and reference models, leaving the student's own training progress unexploited.", "easy2_evidence": "Empirically, we evaluate DexOPD on GenEval, OCR, and DrawBench.", "topic_evidence": "To address this limitation, we introduce DexOPD, a dual-extrapolation on-policy distillation method for diffusion models.", "limit_evidence": ""}, "2611.31954": {"points": [{"subtitle": "동적 토큰 프루닝", "desc": "연구진은 내부 어텐션에 의존하지 않고도 지각적 의미를 통해 효과적인 토큰 선택을 유도할 수 있음을 보였는데요. 뭔 소리냐면, 장면의 의미 구조 변화에 맞춰 선택 크기를 바꿀 수 있다는 말이에요. 이 방식을 통해 고정된 의미 크기의 한계를 넘어서려 했다는 겁니다.", "evidence": "We show that perceptual semantics can guide effective token selection without relying on internal attention when the selection scale adapts to the scene's evolving semantic structure."}, {"subtitle": "온라인 조절과 비동기 실행", "desc": "지각 온도 파라미터를 사용해 유지되는 표현의 크기를 제어하는 TauPrune-VLA를 도입했는데요. 연속 프레임 사이의 안정성을 활용해 현재 관측에서 구한 유지 인덱스를 다음 정책 호출에 적용한다고 해요. 쉽게 말하면, 토큰 선택이 추론과 비동기로 작동해서 프루닝 오버헤드를 줄인다는 셈이에요.", "evidence": "This continuity allows retention indices computed from the current observation to be applied at the next policy invocation, enabling token selection to run asynchronously with inference and reducing pruning overhead."}, {"subtitle": "성능 검증", "desc": "다양한 VLA 모델과 시뮬레이션 벤치마크에서 평가해 봤더니, 기존 성공률을 거의 유지하면서도 최대 1.86배의 추론 속도 향상을 이뤄냈다고 밝혔는데요. 여기에 두 가지 실제 로봇 플랫폼에서도 그 효과를 추가로 검증했다고 해요. 속도가 빨라지는 장점이 있는 반면, 실제 환경에서의 광범위한 적용성은 추가로 살펴봐야 한다는 겁니다.", "evidence": "Evaluated across diverse VLA models and simulation benchmarks, TauPrune-VLA achieves up to a $1.86\\times$ inference speedup while maintaining near-baseline task success rates."}], "easy1_evidence": "Vision-language-action (VLA) models must process continuous streams of visual observations, and the resulting computational cost limits real-time robotic control.", "easy2_evidence": "Based on this observation, we introduce TauPrune-VLA, a training-free method that controls the scale of the retained perceptual representation through a single perception temperature \\tau.", "topic_evidence": "We show that perceptual semantics can guide effective token selection without relying on internal attention when the selection scale adapts to the scene's evolving semantic structure.", "limit_evidence": ""}, "2611.31864": {"points": [{"subtitle": "숫자 튜닝의 효과", "desc": "연구진이 35개 작업에서 숫자 설정값을 조율해 봤더니, 한 설정은 기본값보다 정확도가 2.9포인트 오르고 비용이 18% 더 들었으며 다른 설정은 정확도를 유지하면서 비용을 32% 낮췄다는 거예요. 뭔 소리냐면, 숫자 조율만으로는 정확도를 크게 높이는 데 한계가 있다는 말이에요.", "evidence": "On 35 tasks, with whole groups of tasks held out from tuning, one tuned configuration gains 2.9 points of top-1 accuracy (HR@1) over the default at 18% more cost, and another keeps the accuracy of the default at 32% lower cost."}, {"subtitle": "구조적 선택의 중요성", "desc": "정확도는 숫자 튜닝이 닿지 않는 구조적 선택에 크게 좌우되는데요. 소스 열을 하나의 타겟 테이블에 제한하는 방식을 쓰면 MIMIC-III에서 OMOP로 가는 작업에서는 정확도가 30포인트 오르고 데이터베이스 뷰로 만든 작업에서는 52포인트 내려간다는 거예요.", "evidence": "Restricting the search for each source column to one assigned target table changes HR@1 by +30 points on a MIMIC-III to OMOP task and by -52 points on a task built from database views, more than numeric tuning gains on nine of ten test tasks."}, {"subtitle": "오라클과 LLM 판사", "desc": "작업마다 설정을 골라주는 오라클을 써도 41개 작업에서 87.8%에 그치는데, 이는 같은 작업 안의 열마다 더 나은 설정이 다르기 때문이에요. 그래서 파이썬과 파이프라인이 두 설정을 모두 돌리고 LLM 판사가 의견이 갈리는 26%의 열에서 답을 고르게 하여 91.5%의 정확도에 도달했다고 밝혔어요.", "evidence": "The pipeline therefore runs both settings, and an LLM judge chooses among their candidate answers on the 26% of columns on which they disagree."}], "easy1_evidence": "First, tuning buys cost and a little accuracy.", "easy2_evidence": "The pipeline therefore runs both settings, and an LLM judge chooses among their candidate answers on the 26% of columns on which they disagree.", "topic_evidence": "We tuned all of them for an LLM pipeline for schema matching and mapping, with accuracy and cost as joint objectives, and we show what this buys, what it cannot buy, and where the remaining accuracy is.", "limit_evidence": ""}, "2611.31833": {"points": [{"subtitle": "다섯 단계 평가 구조", "desc": "해석 방법을 효과적으로 구별하기 위해 과제 맞춤형 기초와 엄격한 지식적 근거를 포함한 다섯 등급으로 나누어 평가하도록 했는데요. 뭔 소리냐면, 단순히 모델을 설명하는 것을 넘어서 데이터 과학의 원칙을 바탕으로 신뢰 수준을 꼼꼼히 따진다는 말이에요.", "evidence": "To differentiate interpretation methods effectively and systematically, TRUST grades interpretation across five tiers: Task-Aligned PDR Foundations, Rigorous Epistemic Grounding, Unifying Semantic Understanding, Scope Transferability, and Targeted Prospective Validation."}, {"subtitle": "랜덤 포레스트 사례 분석", "desc": "연구진은 반복 랜덤 포레스트(iRF) 계열을 처음부터 끝까지 적용해 보는 사례 연구를 보여 줬는데요. 이 과정에서 특정 단계를 통과하지 못하는 다른 대형 언어 모델(LLM) 해석 방법들과 어떻게 다른지 비교해 봤다는 겁니다.", "evidence": "We present a start-to-finish case study of the iterative Random Forest (iRF) family under TRUST and contrast it with other LLM interpretation methods that struggle to clear specific tiers."}, {"subtitle": "자율 에이전트 확장", "desc": "마지막으로 트러스트 원칙들이 자율 에이전트(Autonomous Agentic) 틀로 어떻게 확장될 수 있는지에 대한 짧은 초기 생각도 함께 덧붙였는데요. 쉽게 말하면, 사람과 기계가 협력하는 작업뿐만 아니라 앞으로의 자율 시스템에도 이 평가 원칙이 바탕이 된다는 거예요.", "evidence": "Finally, we conclude with brief initial thoughts on how TRUST principles can extend in autonomous agentic frameworks."}], "easy1_evidence": "As AI transitions to sociotechnical deployments, uninterpretable models pose serious threats to reliability, public trust and contestability.", "easy2_evidence": "To this end, we propose TRUST, a tiered evaluation framework that builds upon the Predictability-Computability-Stability (PCS) principles for Veridical Data Science (VDS) and the Predictive, Descriptive and Relevant (PDR) foundations.", "topic_evidence": "Our core vision is that elevating the evaluation of interpretation methods to a core AI assessment metric will drive robust knowledge discovery from data (KDD) and ensure safe, contestable sociotechnical deployments of AI.", "limit_evidence": ""}, "2611.31787": {"points": [{"subtitle": "사이피그투데이터(SciFig2Data) 구성 방식", "desc": "이 시스템은 문서 요소 찾기, 복합 그림 쪼개기, 광학 문자 판독(OCR) 기반 의미 필터링, 스윈(Swin) 기반 차트 분류, 그리고 멀티모달 대형 언어 모델(MLLM) 재구성을 한데 묶었는데요. 여기에 폴더 단위 일괄 실행, 임시 저장(캐싱), 구조화된 기록 기능을 더해 대규모 처리를 뒷받침한다는 거예요. 뭔 소리냐면, 그림을 찾고 쪼개는 것뿐만 아니라 컴퓨터가 대량으로 빠르게 처리하도록 여러 기술을 짜깁기했다는 말이에요.", "evidence": "The system integrates multi-scale document element detection, adaptive compound figure decomposition, two-stage OCR-based semantic filtering, Swin-based chart classification, and instruction-guided multimodal large language model (MLLM) reconstruction."}, {"subtitle": "실제 문헌 검증 결과", "desc": "독성학과 약리학 논문 605편과 지질 나노입자(LNP) 논문 551편이라는 두 가지 생명의학 문헌 모음에서 이 작업을 시험해 봤는데요. 그 결과 독성학·약리학 모음에서는 468개, 지질 나노입자 모음에서는 242개의 표 형태 결과물을 성공적으로 되살려냈다는 겁니다. 쉽게 말하면, 실제 논문들에 들어 있는 그림 데이터를 뽑아내는 데 꽤 쓸만하다는 걸 숫자로 보여준 셈이에요.", "evidence": "The pipeline successfully reconstructed 468 and 242 tabular outputs from the respective corpora, illustrating its practical applicability to literature-scale scientific data harvesting."}, {"subtitle": "인공지능을 위한 과학(AI4Science) 응용", "desc": "되살려낸 측정값들을 설명문에 나오는 실험 메타데이터(부수 정보)와 연결해 주는데요, 이렇게 하면 학술 출판물의 그림 증거를 나중에 인공지능을 위한 과학(AI4Science) 응용 프로그램에 바로 쓸 수 있는 구조화되고 맥락이 풍부한 데이터 기록으로 바꿔준다는 거예요.", "evidence": "By associating reconstructed measurements with caption-derived experimental metadata, SciFig2Data provides a workflow for transforming graphical evidence in scholarly publications into structured, context-enriched data records for downstream AI4Science applications."}], "easy1_evidence": "Scientific measurements reported in scholarly articles are often embedded in compound figures rather than available as machine-readable data.", "easy2_evidence": "We present \\textit{SciFig2Data}, an automated, high-throughput workflow for harvesting structured experimental data from scientific PDF repositories.", "topic_evidence": "By associating reconstructed measurements with caption-derived experimental metadata, SciFig2Data provides a workflow for transforming graphical evidence in scholarly publications into structured, context-enriched data records for downstream AI4Science applications.", "limit_evidence": ""}, "2611.31737": {"points": [{"subtitle": "중요도 기반 정밀도 할당", "desc": "혼합 전문가 라우터가 주는 중요도 신호를 활용해서 꼭 필요한 전문가에게는 더 높은 정밀도를 얹어 주도록 했는데요, 뭔 소리냐면 모델의 정확도가 떨어지지 않게 붙들어 매는 역할이라는 말이에요. 따로 미리 학습을 다시 하거나 오프라인으로 분석할 필요가 없다는 장점도 같이 가지고 있거든요.", "evidence": "A sensitivity-aware allocator leverages intrinsic importance signals from the Mixture-of-Experts (MoE) router to assign higher precision to critical experts, preserving accuracy."}, {"subtitle": "GPU 노화 속도 개선 결과", "desc": "서버나 데스크탑, 임베디드 기기에서 실제로 돌려봤더니 발열 때문에 생기는 그래픽카드의 노화 속도가 25%에서 33%까지 줄어든다고 하는데요, 쉽게 말하면 기기가 뜨거워져서 닳아 없어지는 속도를 확실히 늦췄다는 셈이에요.", "evidence": "Experiments on server, desktop, and embedded platforms demonstrate that GreenDynaMix reduces the temperature-induced aging rate of GPUs during LLM inference by 25-33%."}, {"subtitle": "처리 속도 회복과 정확도 비용", "desc": "8비트와 4비트를 섞어 쓸 때는 혼란도 비용이 0.9%에서 1.6% 정도로 적게 들면서 속도를 회복하지만, 메모리 사정 때문에 4비트와 2비트를 섞어야 할 때는 이 비용이 9.4%까지 올라간다는 건데요. 속도와 효율을 챙기면서도 상황에 따라 정확도에서 감수해야 하는 부분이 달라진다는 말이에요.", "evidence": "Without offline profiling or model retraining, it recovers throughput at a perplexity cost of 0.9-1.6% with 8-bit/4-bit mixed precision, rising to 9.4% where memory forces 4-bit/2-bit."}], "easy1_evidence": "Because GPU temperature fluctuates continuously with workload intensity and ambient conditions, keeping it in a safe range requires real-time frequency scaling, which inevitably comes at the cost of either throughput or accuracy.", "easy2_evidence": "To address this tightly coupled challenge, we propose GreenDynaMix, the first runtime system to jointly integrate a DVFS-based thermal manager with a dynamic precision-tuning throughput compensator.", "topic_evidence": "To address this tightly coupled challenge, we propose GreenDynaMix, the first runtime system to jointly integrate a DVFS-based thermal manager with a dynamic precision-tuning throughput compensator.", "limit_evidence": ""}, "2611.31708": {"points": [{"subtitle": "프리첼 구성", "desc": "연구진은 세 가지 고리화 화학 방식을 담은 285개의 복합체 세트와 입력 형식 변환 및 구조 검증 계층, 그리고 결합 거리와 고리 닫힘을 확인하는 평가 도구를 하나로 묶었는데요. 뭔 소리냐면, 데이터 준비부터 입력 변환, 화학적 유효성 검사까지 한 번에 처리하도록 설계했다는 말이에요.", "evidence": "PRETZEL has three components: PRETZEL-SET, an evaluation set annotated by cyclization chemistry and chemical novelty; PRETZEL-TWIST, a specification layer that compiles a single canonical macrocycle description into each engine's native input format and verifies the returned structure; and PRETZEL-SALT, an evaluation suite pairing standard pose metrics with validity checks for bond distances, bond angles, dihedrals, and ring closure."}, {"subtitle": "모델별 예측 성능", "desc": "알파폴드3와 볼츠-2, 프로테닉스-v2, 하이폴드3를 대상으로 시험해 봤더니, 프로테닉스-v2가 2 A 미만 19.3%, 5 A 미만 37.5%의 결과를 냈는데요. 머리-꼬리 고리화는 비교적 잘 다루지만 고정형 표적에서는 성능이 떨어진다는 특징이 보인다는 겁니다.", "evidence": "Using these, we evaluate AlphaFold3, Boltz-2, Protenix-v2, and HighFold3."}, {"subtitle": "화학적 유효성의 한계", "desc": "위치 정확도는 괜찮아 보여도 화학적 유효성은 약해서, 온전한 결합을 갖춘 예측은 최대 8.1%에 불과했는데요. 고리화 과정을 일차적인 구조가 아니라 단순한 부가 정보로 다루기 때문에 이런 문제가 생긴다고 연구진은 분석했어요.", "evidence": "Chemical validity is weaker still: at most 8.1% of predictions have a fully valid set of inter-residue bonds, and no engine closes every macrocycle in more than 80.7% of its predictions, so pose accuracy alone is an insufficient criterion."}], "easy1_evidence": "Yet published evaluations rely on small, loosely curated target sets that differ from paper to paper, so results are not comparable, and most report pose RMSD alone, without checking whether the predicted molecule is chemically correct.", "easy2_evidence": "Protenix-v2 achieves the best median RMSD at 9.05 A, with 19.3% of predictions under 2 A and 37.5% under 5 A.", "topic_evidence": "We introduce PRETZEL (Prediction of Ring-Enclosed Topology: Zero-shot Evaluation of cycLic peptides), a benchmark of 285 curated cyclic peptide-protein complexes spanning three cyclization chemistries, all post-dating the training cutoff of every model evaluated.", "limit_evidence": "These failures share a cause: co-folding models place macrocycles without representing them, treating cyclization and non-canonical chemistry as annotations layered onto a residue sequence rather than as first-class structure."}, "2611.31621": {"points": [{"subtitle": "짧은 문맥에서의 신뢰성 활용", "desc": "연구진은 긴 궤적에서 성능이 떨어지는 모델이라도 짧은 문맥에서는 여전히 신뢰할 수 있게 행동한다는 점을 관찰했는데요. 추론 역사가 길어져도 짧은 맥락에서의 이런 행동 양상을 그대로 보존하는 데 초점을 맞췄다는 말이에요. 뭔 소리냐면, 모델의 전체 성능이 무너지기 전에 짧은 단위로 끊어서 성질을 유지하겠다는 겁니다.", "evidence": "We observe that a reasoning model that degrades over long trajectories still behaves reliably in short contexts."}, {"subtitle": "TruSuCo 방식과 학습 과정", "desc": "훈련에는 4k 토큰 추론 접두사가 있는 수천 개의 질문이 쓰였으며 정답이나 외부 교사는 필요 없었다고 해요. 추론 과정을 잘라내고 요약한 뒤 이어서 진행하는 TruSuCo를 통해 요약기를 훈련했다는 겁니다.", "evidence": "Training uses a few thousand questions with 4k-token reasoning prefixes and does not need answers or external teachers."}, {"subtitle": "성능 향상 결과", "desc": "고정된 32k 토큰 예산 아래서 학습된 요약기는 수학 벤치마크와 리즈닝 짐(Reasoning Gym) 퍼즐의 9가지 설정 모두에서 기본 추론보다 최대 7.7포인트, 학습되지 않은 요약기보다 최대 12포인트 향상된 성능을 보였는데요. 128k 토큰에서는 AIME 2024-2026 기준으로 기본 모델보다 10포인트 더 앞선다고 밝혔어요. 쉽게 말하면, 예산이 커질수록 기본 추론과의 성능 차이가 더 벌어진다는 말이에요.", "evidence": "Under a fixed 32k-token budget, the trained summarizer improves on vanilla reasoning and on an untrained summarizer in all nine settings across mathematical benchmarks and Reasoning Gym puzzles, by up to 7.7 points and 12 points, respectively."}], "easy1_evidence": "Reasoning models degrade as their context grows, so longer reasoning traces do not by themselves give longer effective horizons.", "easy2_evidence": "Motivated by this, we train a separate summarizer with Delta-KL, a reward computed from the frozen reasoning model's token-level predictions on sampled continuations, and run inference by truncating the trace, summarizing it, and continuing from the summary (TruSuCo).", "topic_evidence": "Motivated by this, we train a separate summarizer with Delta-KL, a reward computed from the frozen reasoning model's token-level predictions on sampled continuations, and run inference by truncating the trace, summarizing it, and continuing from the summary (TruSuCo).", "limit_evidence": ""}, "2611.31610": {"points": [{"subtitle": "감시의 어려움", "desc": "최신 초거대 언어 모델들은 뚜렷한 생각의 흐름을 남기지 않고도 깊은 추론을 해내는데요, 이 때문에 추론 과정을 읽어내기 점점 어려워지고 비용 절감을 위해 비동기식으로 검사하는 일이 잦아졌다는 겁니다. 쉽게 말하면, 모델이 무슨 생각을 하는지 실시간으로 따라가며 살펴보기 점차 힘들어지고 있다는 말이에요.", "evidence": "Frontier models like GPT-6 Astra are increasingly able to do substantial reasoning without a monitorable chain of thought, chains of thought are becoming less legible, and are often monitored asynchronously to reduce cost."}, {"subtitle": "구역화 기반 구조 제안", "desc": "그래서 연구진은 기존의 GRAM, SGTM, DEMix, BTS 같은 방법들을 바탕으로 위험한 능력을 구역별로 나누는 구조적 변경을 제안했는데요, 전략적 적대 행위로 이어질 수 있는 위험한 추론 방식을 생각의 흐름 방식보다 훨씬 저렴하게 감시할 수 있다는 겁니다. 이 방식은 생각의 흐름 자체를 감시하기 어려운 미래에도 계속 살아남을 수 있는 대안으로 보입니다.", "evidence": "We propose a modification to existing LLM architectures based on GRAM, SGTM, DEMix, BTS, and similar methods to compartmentalize dangerous capabilities so that their use, especially in combination with dangerous reasoning types that may indicate strategic adversarial use, can be monitored more cheaply than chain of thought in a way that might outlast monitorable chain of thought."}, {"subtitle": "장단점과 추가 이점", "desc": "이 새로운 구조는 여러 변형을 통해 성능과 감시 사이의 균형을 잡도록 설계되었으며, 필요할 때 특정 기능을 아예 제거할 수 있는 장점도 함께 지니고 있다고 해요. 뭔 소리냐면, 감시 비용을 낮추는 동시에 모델의 위험성을 통제할 수 있는 다양한 실마리를 제공한다는 말입니다.", "evidence": "We propose several variants of this architecture designed to balance tradeoffs and discuss other benefits, such as capability removal."}], "easy1_evidence": "Frontier models like GPT-6 Astra are increasingly able to do substantial reasoning without a monitorable chain of thought, chains of thought are becoming less legible, and are often monitored asynchronously to reduce cost.", "easy2_evidence": "We propose a modification to existing LLM architectures based on GRAM, SGTM, DEMix, BTS, and similar methods to compartmentalize dangerous capabilities so that their use, especially in combination with dangerous reasoning types that may indicate strategic adversarial use, can be monitored more cheaply than chain of thought in a way that might outlast monitorable chain of thought.", "topic_evidence": "We propose a modification to existing LLM architectures based on GRAM, SGTM, DEMix, BTS, and similar methods to compartmentalize dangerous capabilities so that their use, especially in combination with dangerous reasoning types that may indicate strategic adversarial use, can be monitored more cheaply than chain of thought in a way that might outlast monitorable chain of thought.", "limit_evidence": ""}, "2611.31554": {"points": [{"subtitle": "부분 실행과 해로운 복구 측정", "desc": "10개 모델의 200개 에피소드 표본을 조사해 보니, 데이터베이스 상태로 확인된 부분 실행 143개 중 30개에서 해로운 복구가 일어났고 층화 가중치로 24.6%의 추정치가 나왔다는 거예요. 이 해로운 복구 중 3분의 2는 효과가 중복되었고 나머지는 데이터 삭제나 잘못된 첫 쓰기였다는 말입니다.", "evidence": "In a stratified random sample of 200 candidate episodes across ten models, 145 are partial executions confirmed by the database state."}, {"subtitle": "중복 호출 규칙의 한계", "desc": "반복 호출을 찾는 규칙을 적용해 봤더니 중복은 75%를 잡았지만 전체 해는 41%만 찾았다는 한계가 드러났는데요. 뭔 소리냐면, 단순한 중복 탐지 방식으로는 에이전트가 저지르는 다양한 형태의 해를 완벽하게 막기 어렵다는 말이에요.", "evidence": "A rule that searches for repeated calls finds 75% of duplications but only 41% of all harm."}, {"subtitle": "식별자 방식의 효과 비교", "desc": "모델이 제공한 식별자는 같은 작업에도 새 식별자를 만들어 내서 해를 줄이지 못한 반면, 호출 내용에서 유도한 식별자는 해로운 쓰기 매치에 도움을 주었다고 해요. 다만 잘못된 첫 번째 쓰기에는 대응하지 못한다는 점도 같이 확인되었다는 셈이에요.", "evidence": "Identity derived from the call content, evaluated counterfactually on the sample, would have matched every harmful write in 14 to 18 of the 30 harmful recoveries, but in none of those with a wrong first-time write, and it would also have matched writes required by the task in 30 episodes."}], "easy1_evidence": "It is unknown how often such a recovery harms the external state when the failure occurs naturally in the code written by the agent.", "easy2_evidence": "Based on these results, we outline design requirements for safer agent recovery.", "topic_evidence": "In this paper, we measure it on recorded trajectories of AppWorld agents.", "limit_evidence": ""}, "2611.31457": {"points": [{"subtitle": "택시 시스템의 대규모 처리", "desc": "수백만 단계에 이르는 데이터를 효율적으로 다루기 위해 확장 가능한 분석 방법들을 조합했는데요, 묶음 분석을 통해 단계별 분류 체계를 만들어서 데이터의 구조화된 개요를 제공한다는 겁니다. 뭔 소리냐면, 방대한 데이터 속에서 핵심 흐름을 빠르게 찾아낸다는 말이에요.", "evidence": "Taxi scales to millions of steps efficiently."}, {"subtitle": "하이브리드 파이프라인과 모델 통합", "desc": "묶음 분석과 질의 기능을 코딩 에이전트의 안내에 따라 함께 쓰도록 엮었는데요, 상태와 제한된 질문을 유형화된 확률적 결정으로 직접 바꾸는 제브 스타일의 결정 모델도 실험적으로 포함시켰다는 거예요. 단순 조회로는 부족한 의미적 라우팅과 평가를 저렴하게 채워 준다고 합니다.", "evidence": "Taxi also includes an experimental integration of Jev-style decision models: models that map state and bounded questions directly to typed, probabilistic decisions."}, {"subtitle": "확장 가능한 생태계와 모듈식 설계", "desc": "내장된 평가 도구와 일일 보고서를 포함한 확장 가능한 생태계를 제공하는데요, 개인과 팀이 쉽게 가져다 쓸 수 있도록 모듈식으로 설계되어 있다는 겁니다. 쉽게 말하면, 필요에 따라 쉽게 붙였다 뗄 수 있는 구조라는 말이에요.", "evidence": "To accommodate growth, Taxi is designed to be modular, hackable, and easy to plug-and-play for individuals and teams."}], "easy1_evidence": "In this technical report, we present Taxi -- a system for debugging, clustering, and monitoring agents at scale.", "easy2_evidence": "Clustering and querying are best used together in a hybrid pipeline guided by a coding agent.", "topic_evidence": "In this technical report, we present Taxi -- a system for debugging, clustering, and monitoring agents at scale.", "limit_evidence": ""}, "2611.31215": {"points": [{"subtitle": "ActSpace-Bench 도입", "desc": "연구진은 72개의 실제 실내 장면을 담은 994개의 질문과 234번의 탐색으로 이루어진 평가 틀인 ActSpace-Bench를 만들었는데요, 모델이 처음 한 장의 시점에서 출발해 실제 프레임을 돌아다니며 답을 찾게 만들었다는 겁니다. 뭔 소리냐면, 증거가 주어지지 않은 상태에서 스스로 찾아야 하는 환경을 구축했다는 말이에요.", "evidence": "We present ActSpace-Bench, a benchmark of 994 questions across 234 exploration episodes in 72 real-scanned indoor scenes, where a model starts from a single view, navigates real captured frames, and must gather evidence before answering."}, {"subtitle": "통제된 평가 방식", "desc": "이 탐색이 진짜 목적을 가졌는지 확인하려고 모델의 탐색 결과를 같은 예산을 쓴 무작위 이동이나 정답 경로와 비교하는 통제된 평가 방식을 도입했거든요. 질문마다 탐색이 꼭 필요하고 3D 주석으로 답하도록 검증했으며, 마스크 처리된 증거 질문으로 모델이 모를 때 대답을 안 할 줄 아는지도 확인했다는 거예요.", "evidence": "To assess whether such exploration is purposeful, we introduce a controlled evaluation protocol that fixes each model as the reasoner and compares its own exploration against a same-budget random walk and an oracle route, separating evidence seeking from spatial reasoning."}, {"subtitle": "모델 성능 평가 결과", "desc": "23개의 모델을 시험해 봤더니 가장 강한 모델들은 목적을 갖고 증거를 찾았지만 제한된 기억력 때문에 그 능력을 많이 잃는다는 단점이 있었는데요, 반면에 약한 모델들은 무작위 이동과 다를 게 없거나 증거 추론에 실패했다는 겁니다. 쉽게 말하면, 95% 이상이 사람의 검증을 거친 이 실험 결과는 기억력과 증거 기반 추론이 다음 목표라는 점을 가리킨다는 말이에요.", "evidence": "Evaluations of 23 proprietary, open-weight, and spatially specialized VLMs reveal that the strongest models do seek evidence with purpose but lose much of it to limited memory, whereas weaker and specialized models explore no better than a random walk or fail to reason over the evidence they are given, pointing to memory and evidence-grounded reasoning as the next targets for active spatial intelligence."}], "easy1_evidence": "However, can vision-language models (VLMs), which reason increasingly well over curated images and videos, also seek in space when the evidence is not handed to them?", "easy2_evidence": "Evaluations of 23 proprietary, open-weight, and spatially specialized VLMs reveal that the strongest models do seek evidence with purpose but lose much of it to limited memory, whereas weaker and specialized models explore no better than a random walk or fail to reason over the evidence they are given, pointing to memory and evidence-grounded reasoning as the next targets for active spatial intelligence.", "topic_evidence": "We present ActSpace-Bench, a benchmark of 994 questions across 234 exploration episodes in 72 real-scanned indoor scenes, where a model starts from a single view, navigates real captured frames, and must gather evidence before answering.", "limit_evidence": ""}, "2611.31190": {"points": [{"subtitle": "생성과 검증의 분리", "desc": "생성 거대 언어 모델(LLM)이 쿼리를 작성하고 실행하는 동안, 다른 비평 거대 언어 모델(LLM)이 쿼리와 실행 결과를 판단하도록 분리했습니다. 비평 모델의 검증 및 정렬 점수는 생성 모델의 자신감, 토큰 수준의 불확실성, SQL 구조적 특징과 함께 랜덤 포레스트에서 결합된다는 겁니다.", "evidence": "A generator LLM writes and executes the query, and a different critic LLM judges the query and its execution result."}, {"subtitle": "컨포멀 예측과 위험 제어", "desc": "두 번의 캘리브레이션 단계를 거쳐 유한 표본 보장을 제공하는데, 학습 후 테스트 문턱값은 사용자가 선택한 예산 아래로 오류율이 유지되도록 보장합니다. 컨포멀 p-값은 거짓 기권율을 경계 짓는 역할을 한다는 말이에요.", "evidence": "Two calibration steps give finite-sample guarantees."}, {"subtitle": "스파이더와 버드 실험 결과", "desc": "스파이더 데이터셋에서 0.899의 AUARC를 얻었으며, 15퍼센트 위험 예산을 주었을 때 평균 52.4퍼센트의 쿼리를 수용하면서 9.1퍼센트의 관측 오류를 기록했습니다. 버드(BIRD)에 재학습 없이 적용했을 때는 신뢰 점수는 유용하지만 교환성이 없어 위험 보장이 전송되지 않는다고 밝혔습니다.", "evidence": "The estimator obtains an AUARC of 0.899."}], "easy1_evidence": "Text-to-SQL systems often return queries that execute successfully but answer the wrong question. Detecting these errors at deployment is hard because execution correctness is defined against a gold query, which exists only in labeled data.", "easy2_evidence": "With a 15% risk budget ($\rho=0.1$), a threshold is certified on all 10 resampled splits, and the system accepts 52.4% of queries on average with 9.1% observed error.", "topic_evidence": "We formulate confidence estimation for Text-to-SQL as probabilistic query validation under a latent correctness variable that is observable at calibration time through gold-SQL execution and latent at deployment.", "limit_evidence": "Applied to BIRD without retraining, the confidence scores remain informative (AUROC 0.72, against 0.79 on Spider), but the risk guarantee does not transfer, as expected without exchangeability."}, "2611.31175": {"points": [{"subtitle": "유형화된 결정 구조", "desc": "대화마다 고정된 선택지의 확률을 활용해 사용자의 요구 변화를 추적하도록 시스템을 설계했어요. 뭔 소리냐면, 문장을 직접 생성하지 않고 카탈로그 필드와 연결해 속도를 높였다는 말이에요.", "evidence": "On each turn, one typed request maps the message onto the catalog's fields, keeps what no field expresses in the user's words, and decides how the turn changes each earlier need."}, {"subtitle": "니드와이즈(Needwise)의 순위 매기기", "desc": "아이템 종류, 장소, 가격 같은 요구를 계층으로 묶고 홀리스틱 결정과 판정을 동등한 가치로 결합해 후보 순위를 정해요. 이렇게 했더니 구글 로컬(Google Local) 데이터에서 지피티-6 솔(GPT-6 Sol)보다 뛰어난 성능을 보였다는 거예요.", "evidence": "Needwise then ranks candidates must-first: the needs on the kind of item, its place and its price form a tier, and within it one holistic decision and need-level verdicts (supported, contradicted or unknown) are combined with equal weight (Needwise-HF)."}, {"subtitle": "성능과 비용 비교", "desc": "구글 로컬에서 중간값 기준 2.5초 만에 답하며 지피티-6 솔(GPT-6 Sol)의 5.6초보다 훨씬 빠른 속도를 보였어요. 비용도 에이피아이(API) 가격의 일부에 불과하다는 장점이 있는데, 철회된 요구는 19~27퍼센트만 인식한다는 한계도 같이 드러났습니다.", "evidence": "It costs a fraction of GPT-6 Sol's API price and answers in 2.5 s at the median on Google Local, against 5.6 s for GPT-6 Sol."}], "easy1_evidence": "LLM rankers re-read the dialogue at every turn: they are slow, and their ordering does not show which needs an item meets.", "easy2_evidence": "Needwise-HF ranks Google Local requests significantly better than GPT-6 Sol (0.383 against 0.343 nDCG@10) and is not significantly different from the strongest LLM ranker on Google Local and Yelp; these comparisons keep their sign under every treatment of unrecorded attributes we test.", "topic_evidence": "We show that a conversational recommender can be built from typed decisions instead: named questions over fixed options, answered with option probabilities rather than generated text.", "limit_evidence": "In conversations, the typed state keeps the ranking across switches and returns, but it recognizes only 19-27% of withdrawn needs."}, "2611.31132": {"points": [{"subtitle": "유전체 임베딩 생성", "desc": "각 분리 주의 조립된 콘티그를 동결된 유전체 언어 모델과 계층적 집계를 거쳐 768차원 벡터 하나로 부호화했는데요. 뭔 소리냐면, 긴 유전 정보 모델링을 다루기 쉽게 압축했다는 말이에요.", "evidence": "The assembled contigs of each isolate are encoded into a single 768-dimensional vector by a frozen genomic language model through a segment-contig-isolate aggregation hierarchy, and a conditional Wasserstein GAN with gradient penalty synthesizes colony images from this embedding together with the applied antibiotic and the resistance label."}, {"subtitle": "조건부 이미지 합성", "desc": "azithromycin과 ciprofloxacin, tetracycline 그리고 약물이 없는 대조군 조건에서 수집한 167,356개의 단세포 이미지로 훈련을 진행했는데요. 생성기 안에서 일곱 가지 사전 훈련된 골격 구조를 비교해 화질 지표가 좋은 ConvNeXt-Tiny를 골랐다는 겁니다.", "evidence": "We train on 167,356 single-cell images from 22 clinical blood isolates imaged under azithromycin, ciprofloxacin, tetracycline, and a no-drug control, compare seven pretrained convolutional backbones inside the generator, and select ConvNeXt-Tiny on distributional image-quality metrics."}, {"subtitle": "내성 분류 성능 향상", "desc": "만들어낸 합성 이미지를 양이 줄어든 실제 훈련 세트에 더해봤더니, 항생제별 내성 분류가 더 정확해지는 결과를 얻었다고 해요. 쉽게 말하면, 부족한 실제 데이터를 합성 이미지로 보완해서 내성 탐지 능력을 끌어올렸다는 셈이에요.", "evidence": "The synthetic images are then assessed extrinsically: added to a reduced real training set, they improve per-antibiotic resistance classification, with a significant gain in resistant-class recall."}], "easy1_evidence": "We formulate this as a conditional image-generation problem.", "easy2_evidence": "The synthetic images are then assessed extrinsically: added to a reduced real training set, they improve per-antibiotic resistance classification, with a significant gain in resistant-class recall.", "topic_evidence": "We formulate this as a conditional image-generation problem.", "limit_evidence": ""}, "2611.31095": {"points": [{"subtitle": "사람들의 업무 배분 결정 분석", "desc": "800명을 대상으로 한 행동 연구를 통해 사람들이 업무 성과와 예상되는 즐거움을 어떻게 조화시키는지 살펴봤는데요. 분석 결과 사람들은 일의 재미가 떨어질수록 주관적인 경험에 더 큰 가중치를 두며 업무를 배분하는 것으로 나타났다는 거예요. 뭔 소리냐면, 단순한 성과 외에도 일하면서 느끼는 감정을 중요한 기준으로 삼는다는 말이에요.", "evidence": "In a series of large-scale (N=800) behavioral studies in which people allocate tasks to either an AI or human worker we find that people's allocation decisions are best captured by a model that systematically balances relative objective performance with the human worker's expected enjoyment, weighting human experience higher when a task is framed as inducing less enjoyment and adjusting based on the stakes of the task."}, {"subtitle": "대형 언어 모델과의 비교", "desc": "인공지능이 직접 업무 배분을 결정하는 상황을 가정해 여러 대형 언어 모델(LLM)의 선택도 함께 비교해 봤는데요. 많은 모델 역시 객관적인 결정에서 벗어나는 모습을 보였지만 즐거움을 반영하는 방식과 정도에서는 큰 차이를 보였다는 거예요. 쉽게 말하면, 인공지능마다 주관적 경험을 다루는 기준이 제각각이라는 셈이에요.", "evidence": "As AI also makes decisions about work allocation, we compare a set of LLMs."}, {"subtitle": "직장 내 인공지능 도입의 과제", "desc": "이번 결과는 인공지능을 직장에 도입할 때 단순한 업무 능력뿐만 아니라 사람의 경험과 작업의 맥락이 중요한 역할을 한다는 점을 보여주는데요. 연구진은 이러한 요소들 때문에 인공지능 도입 과정이 환경에 따라 들쑥날쑥할 수 있다고 밝혔다는 거예요. 뭔 소리냐면, 누가 결정을 내리느냐와 일의 성격에 따라 도입 양상이 달라진다는 말이에요.", "evidence": "Integration may be jagged across settings due to consideration not only of the relative capabilities of workers, but also the human experience of work, the valence of that experience (e.g., more strongly weighing aversion), the context (e.g., stakes), and who is making or guiding such choices (human or LLM)."}], "easy1_evidence": "Here, we assess how people balance objective outcomes and more subjective qualities like enjoyment.", "easy2_evidence": "We find that people's allocation decisions are best captured by a model that systematically balances relative objective performance with the human worker's expected enjoyment, weighting human experience higher when a task is framed as inducing less enjoyment and adjusting based on the stakes of the task.", "topic_evidence": "Here, we assess how people balance objective outcomes and more subjective qualities like enjoyment.", "limit_evidence": ""}, "2611.31090": {"points": [{"subtitle": "기존 방식의 한계와 접근법", "desc": "대규모 차량 경로 최적화 문제를 풀기 위해 유망한 하위 문제를 먼저 찾아내고 솔버로 최적화하는 방식을 썼는데요. 뭔 소리냐면, 복잡한 문제를 그대로 못 푸니까 쓸만한 조각을 먼저 골라내려 했다는 말이에요.", "evidence": "One approach to solve large-scale vehicle routing optimization is to identify promising subproblems and then optimize them using solvers."}, {"subtitle": "거대 언어 모델 기반 자동 휴리스틱 설계", "desc": "연구진은 거대 언어 모델이 스스로 하위 문제를 고르는 규칙을 다듬는 자동 휴리스틱 설계 프레임워크를 제안했어요. 기존에는 작업별 신경망을 따로 학습시켰지만, 이번에는 모델이 직접 해석 가능한 규칙을 만들어 하위 문제를 구성한다는 겁니다.", "evidence": "Compared to prior approaches that train task-specific neural networks to select among heuristically constructed subproblems, our method discovers generalizable, interpretable LLM-generated heuristics to directly construct subproblems."}, {"subtitle": "실험 결과와 성능 비교", "desc": "실험을 통해 확인해 보니, 이 접근법은 기존 범위 안에서는 비슷한 성능을 냈는데요. 장점은 규모가 훨씬 큰 새로운 문제에서는 신경망 기반 정책보다 더 뛰어난 성능을 보여줬다는 거랍니다.", "evidence": "Experiments show that our approach achieves comparable in-distribution performance while outperforming neural network-based policies on out-of-distribution instances with large-scale problems."}], "easy1_evidence": "Efficient vehicle routing is critical to logistics and transportation, yet solving large-scale capacitated vehicle routing problems (CVRP) remains computationally challenging due to their combinatorial complexity.", "easy2_evidence": "In this paper, we propose a framework of automatic heuristic design (AHD) in which a large language model (LLM) autonomously refines heuristics for selecting subproblems, enabling effective optimization of large-scale CVRP instances.", "topic_evidence": "In this paper, we propose a framework of automatic heuristic design (AHD) in which a large language model (LLM) autonomously refines heuristics for selecting subproblems, enabling effective optimization of large-scale CVRP instances.", "limit_evidence": ""}, "2611.31076": {"points": [{"subtitle": "알파디펙트 시스템 구조", "desc": "연구진은 캐릭터마다 PPO 알고리즘으로 학습시킨 신경망 하나를 써서 전투 안팎의 모든 결정을 내리도록 만들었는데요, 학습 과정에서 캐릭터당 13억에서 67억 번의 결정을 거쳤다는 겁니다. 뭔 소리냐면, 긴 호흡으로 앞을 내다봐야 하는 카드 게임에서 인공지능이 스스로 판단을 내리게 만들었다는 말이에요.", "evidence": "for each character, one network trained with proximal policy optimization (PPO) makes every decision of a run, in combat and outside it."}, {"subtitle": "게임 정보와 인코딩 방식", "desc": "신경망은 카드와 유물, 적을 고유한 임베딩과 속성으로 읽어내며, 게임 엔진이 계산한 공개 정보의 결과까지 함께 받아들이도록 설계되었는데요, 이 인코딩 방식이 승패를 가르는 핵심이라는 거예요. 이 정체성 정보를 아예 안 썼더니 단 한 판도 이기지 못했고, 계산된 결과를 빼버렸을 때는 승률이 8.3포인트 줄어들었다는 단점이 확인된다는 겁니다.", "evidence": "Ablations show how much the agent depends on this encoding: without these identities, the network did not win a single run, and without the computed consequences it won 8.3 points fewer."}, {"subtitle": "높아진 승률과 성능 비교", "desc": "가장 어려운 난이도인 아센션 10에서 캐릭터 여섯 개를 두고 테스트해 봤더니, 탐욕적 플레이로는 62에서 77%, 테스트 타임 검색을 더하면 68에서 80%의 승률을 기록했다고 해요. 같은 난이도에서 인간 플레이어들이 올린 판의 승률이 11에서 20%인 것과 비교하면 인공지능 쪽이 훨씬 높다는 걸 알 수 있다는 겁니다.", "evidence": "At the highest difficulty, Ascension 10, on two versions of the game current in November 2026 and on test seeds not played in training, AlphaDefect wins 62-77% of runs across six characters with greedy play and 68-80% with test-time search, after 1.3 to 6.7 billion decisions of training per character; runs uploaded by human players of all levels are won 11-20% of the time at the same difficulty."}], "easy1_evidence": "At the highest difficulty, Ascension 10, on two versions of the game current in November 2026 and on test seeds not played in training, AlphaDefect wins 62-77% of runs across six characters with greedy play and 68-80% with test-time search, after 1.3 to 6.7 billion decisions of training per character; runs uploaded by human players of all levels are won 11-20% of the time at the same difficulty.", "easy2_evidence": "To our knowledge, AlphaDefect is the strongest publicly reported STS2 agent as of November 2026.", "topic_evidence": "We present AlphaDefect, an expert-level AI system for STS2: for each character, one network trained with proximal policy optimization (PPO) makes every decision of a run, in combat and outside it.", "limit_evidence": ""}, "2611.31065": {"points": [{"subtitle": "기존 강화학습의 한계 분석", "desc": "연구진은 틀린 답에 벌점을 주는 방식이 그룹 상대 강화학습에서 실패 중심의 비교만 만들어내고 탐색이 굶주리는 경계(exploration-starvation boundary)를 이끌어낸다고 밝혔는데요, 답안 점수에서 길이 때문에 순위가 뒤집히거나 단일 토큰 스파이크에 민감해지는 문제도 함께 찾아냈다는 거예요. 뭔 소리냐면, 기존의 벌점 기반 학습 방식이 오히려 모델의 자유로운 탐색을 방해하고 불안정한 요소를 만든다는 말이에요.", "evidence": "We show that wrong-answer penalties create failure-only comparisons in group-relative RL, derive an exploration-starvation boundary, and identify length-induced ranking reversals and single-token spike sensitivity in answer scores."}, {"subtitle": "정확도 향상과 비용 절감 결과", "desc": "Qwen3.5-4B와 Qwen3-8B 모델을 가지고 400개 문제에서 50번의 강화학습 업데이트를 해봤더니, DAPO에서는 정답 제출률이 15.0에서 29.6 포인트 올랐고 도메인 밖의 Omni-MATH에서는 4.3에서 12.8 포인트 올랐으면서도 생성 비용은 3.5에서 12.6% 줄어들었다고 해요. 쉽게 말하면, 성능은 훨씬 좋아졌는데 돈과 자원은 오히려 아꼈다는 겁니다.", "evidence": "Across Qwen3.5-4B and Qwen3-8B, 50 RL updates on 400 problems improve correct-submission rates by 15.0--29.6 points on DAPO and 4.3--12.8 points on out-of-domain Omni-MATH over inference-only budget forcing, while reducing generation cost by 3.5--12.6%."}, {"subtitle": "오답 제출률 감소와 속도 개선", "desc": "8B Omni-MATH 모델에서 타깃 도메인 교정을 거쳤더니 4K 토큰에서는 오답 제출률이 30.3%에서 5.8%로 뚝 떨어졌고 8K에서는 41.8%에서 6.5%로 줄었다고 하는데요, 로컬 배치 시간 기준으로 4K에서 생성 속도도 4B는 2.05배, 8B는 2.23배나 빨라졌다는 거예요. 결과적으로 단 한 번의 롤아웃만으로도 안정적이고 효율적인 예산 기반 추론이 가능해진 셈이에요.", "evidence": "On 8B Omni-MATH, target-domain calibration cuts wrong submissions from 30.3% to 5.8% at 4K and from 41.8% to 6.5% at 8K."}], "easy1_evidence": "Hard token budgets often interrupt LLM reasoning before an answer is produced.", "easy2_evidence": "We propose Tail-CRC, a single-rollout framework that separates candidate generation from submission control.", "topic_evidence": "We propose Tail-CRC, a single-rollout framework that separates candidate generation from submission control.", "limit_evidence": ""}, "2611.31027": {"points": [{"subtitle": "GPU 낭비 실태 측정", "desc": "연구진은 기록된 실행을 에이전트 코드에 다시 재생하는 시뮬레이션 GPU를 만들어 수백 번의 실험을 해 봤는데요. 그 결과 에이전트는 GPU 시간의 52%만 필요한 일에 썼고, 22%는 쓸데없는 일에, 26%는 놀고 있었다는 걸 확인했어요. 뭔 소리냐면, 단순히 에이전트에게 빨리 끝내라고 다그치거나 일정을 짜 주는 방식으로는 이 낭비를 잡을 수 없다는 말이에요.", "evidence": "With no help, the agents put only 52% of their GPU time into work the answer needed."}, {"subtitle": "ComputeWise 벤치마크 개발", "desc": "실제 GPU 없이도 수백 번 실험을 돌릴 수 있도록 연구진이 직접 오픈 벤치마크인 ComputeWise를 만들었는데요. 이 도구는 에이전트가 연구 과제를 수행할 때 생기는 자원 낭비를 눈으로 직접 측정하고 줄일 수 있게 설계되었다는 겁니다.", "evidence": "So we built ComputeWise, an open benchmark of research tasks on which this waste can be measured and reduced."}, {"subtitle": "오픈소스 도구의 성능", "desc": "그래서 프롬프트와 결정론적 코드를 합친 오픈소스 도구를 만들어 다섯 개 모델에 적용해 봤는데요. 그 결과 정답을 내는 데 걸리던 쓸데없는 시간을 80% 이상 덜어내는 데 성공했다고 해요. 쉽게 말하면, 낭비되던 GPU 시간을 확실하게 붙잡아 효율을 높였다는 겁니다.", "evidence": "Across five models, it removed over 80% of the extra time to the answer."}], "easy1_evidence": "With no help, the agents put only 52% of their GPU time into work the answer needed.", "easy2_evidence": "So we built an open-source harness, part prompting and part deterministic code.", "topic_evidence": "So we built ComputeWise, an open benchmark of research tasks on which this waste can be measured and reduced.", "limit_evidence": ""}, "2611.31012": {"points": [{"subtitle": "결정 모델 성능 평가", "desc": "연구진은 14개의 공개 가중치 모델과 2개의 독점 모델을 모아 총 16만 3728건의 평가를 진행해 봤는데요, 가장 성능이 좋은 모델은 가상 사례에서 72.1%를 맞혔고 실제 사례에서는 기존 알고리즘과 56.1% 뜻이 같았다고 해요. 뭔 소리냐면, 의료 기기 평가에 쓰일 가능성을 숫자로 확실하게 확인해 봤다는 말이에요.", "evidence": "To test their triage accuracy, we evaluated 16 decision models (14 open-weight, 2 proprietary) on 233 synthetic and 10,000 real-world cases, yielding 163,728 total assessments."}, {"subtitle": "초기 응급 상황 인식 능력", "desc": "환자의 기본 정보와 위험 요소만 가지고 테스트를 해봤더니, 가장 우수한 모델이 AUROC 0.87을 기록했다는 겁니다. 게다가 오류 범위를 5%로 잡았을 때 절반 가까운 사용자에게 응급인지 아닌지를 판단해 줄 수 있었다고 해요.", "evidence": "They were more promising for recognising emergencies early: given only demographics, chief complaints, risk factors and red-flag answers, the best model reached an AUROC of 0.87."}, {"subtitle": "응급 분류 엔진과의 관계", "desc": "그래서 연구진은 결정 모델이 기존 응급 분류 엔진을 통째로 대체하면 안 된다고 밝혔는데요, 대신 현장 상황에 맞춘 오류 범위 안에서 증상 평가 단계를 줄이는 용도로는 충분히 쓸 수 있다고 봤어요. 쉽게 말하면, 완전한 대체재는 아니지만 보조 도구로는 가능성이 보인다는 거예요.", "evidence": "Decision models should therefore not replace triage engines but could shorten symptom assessments at setting-specific error margins."}], "easy1_evidence": "Laypeople increasingly use large language models (LLMs) for triage advice, but LLMs answer in variable free text, which makes it hard to evaluate them for use in medical devices.", "easy2_evidence": "To test their triage accuracy, we evaluated 16 decision models (14 open-weight, 2 proprietary) on 233 synthetic and 10,000 real-world cases, yielding 163,728 total assessments.", "topic_evidence": "Decision models, which assign a probability to each predefined triage category, may be easier to evaluate.", "limit_evidence": ""}, "2611.30983": {"points": [{"subtitle": "메드유아이짐 환경 구축", "desc": "연구진은 17개의 벤치마크 출처에서 가져온 6개 임상 작업군의 15,739개 과제로 이루어진 메드유아이짐 환경을 구축했는데요, 에이전트가 스크린샷으로 전자의무기록 상태를 인식하고 마우스와 키보드 행동을 실행하도록 만들었다는 겁니다. 뭔 소리냐면, 동일한 임상 데이터 위에서 짝을 이룬 네이티브 도구 인터페이스도 함께 지원한다는 말이에요.", "evidence": "In MedUIGym, agents perceive EHR states from screenshots and execute mouse-and-keyboard actions, as well as a paired native-tool interface over identical clinical data."}, {"subtitle": "기존 모델의 성능 한계 확인", "desc": "12개의 비전-언어 모델을 시험해 봤더니, 현재의 에이전트들은 다양한 임상 작업 흐름을 처리하는 데 큰 어려움을 겪고 있다는 것을 확인했는데요. 단순히 추론에 들이는 노력을 늘리는 것만으로는 일관된 성능 향상을 이끌어내지 못했다는 겁니다. 쉽게 말하면, 기존 방식대로는 복잡한 의료 화면 작업을 해결하는 데 한계가 뚜렷하다는 거예요.", "evidence": "Benchmarking twelve vision-language models shows that current agents struggle across diverse clinical workflows, and simply increasing reasoning effort fails to yield consistent gains."}, {"subtitle": "오프라인 및 온라인 학습 적용 결과", "desc": "메드유아이짐은 그래픽 사용자 인터페이스 궤적을 활용한 오프라인 학습과 작업 보상을 통한 온라인 강화학습을 모두 지원하는데요, 훈련을 마친 큐원3.5 모델들은 내부 임상 작업에서 더 나은 성능을 보여주었다고 해요. 장점은 외부 출처의 새로운 작업으로도 성능이 잘 확장된다는 점인데, 전자의무기록의 그래픽 인터페이스를 통해 임상 작업을 완성하는 방식을 연구할 수 있는 기반이 된다는 겁니다.", "evidence": "After training, both Qwen3.5 models perform better on in-domain clinical tasks and generalize to tasks from external sources."}], "easy1_evidence": "Automating clinical workflows requires vision-language agents that can navigate dense graphical user interfaces (GUIs) in electronic health records (EHRs) and execute precise actions, yet many medical agents still rely on text or structured tool calls.", "easy2_evidence": "Benchmarking twelve vision-language models shows that current agents struggle across diverse clinical workflows, and simply increasing reasoning effort fails to yield consistent gains.", "topic_evidence": "In this work, we introduce MedUIGym, a scalable interactive environment comprising 15,739 tasks from 17 benchmark sources across six clinical task families for training and evaluating clinical GUI agents.", "limit_evidence": ""}, "2611.30742": {"points": [{"subtitle": "점근적 편향 유도와 벤치마크 결과", "desc": "연구진은 심판의 오류가 궤적에 의존할 때 발생하는 정확한 점근적 편향을 유도하고 식별부터 동시 순위까지의 검사 사슬을 제시했는데요. 네 개 에이전트로 구성된 반합성 벤치마크에서 오라클 보정을 쓴 스칼라 보정은 최대 편향이 0.245에 달했고 전체 순위를 단 한 번도 복구하지 못했다고 해요. 뭔 소리냐면, 단순한 보정만으로는 궤적 차이에서 오는 오차를 바로잡기 어렵다는 말입니다.", "evidence": "We derive the exact asymptotic bias and give a chain of checks from identification to simultaneous ranks."}, {"subtitle": "스트레스 테스트와 표본 지원", "desc": "48개 셀로 구성된 스트레스 테스트에서는 보정 라벨이 600개에서 4,800개로 늘어날 때 유효한 목표 지원이 0.209에서 0.805로 오르는 데 그쳤는데요. 반면에 감사가 포함된 AIPW 방식은 평균 절대 오차를 0.018에서 0.020 사이로 유지했다고 합니다. 쉽게 말하면, 라벨만 무작정 늘리기보다는 감사 기반의 보정을 섞는 편이 훨씬 안정적이라는 겁니다.", "evidence": "In a 48-cell stress test, effective target support rises only from 0.209 to 0.805 as calibration grows from 600 to 4,800 labels, while audited AIPW keeps a mean absolute error of 0.018-0.020."}, {"subtitle": "신뢰 구간과 적응형 감사", "desc": "보정 지원이 없거나 외부에서 정해진 한계 안에서 심판 의존성이 있을 때는 유효한 범위나 민감도 집합을 보고하고 이를 순위 집합에 반영했다고 하는데요. 그 결과 e-과정 신뢰 서열이 예측 가능한 적응형 감사와 임의의 중단 조건 아래에서도 안정적인 목표를 향해 유효하게 유지되었다고 해요. 뭔 소리냐면, 까다로운 조건이나 멈춤 상황에서도 신뢰할 수 있는 구간을 확보할 수 있다는 말입니다.", "evidence": "An e-process confidence sequence stays valid, for a stable target, under predictable adaptive auditing and arbitrary stopping."}], "easy1_evidence": "Large language model (LLM) agents are often ranked by an LLM judge whose error rates are measured once and reused for every agent.", "easy2_evidence": "Augmented inverse-probability weighting (AIPW) with a uniform or a design-aware random audit keeps the maximum bias below 0.003, with mean pointwise coverage of 0.939 and 0.950.", "topic_evidence": "The corrected success rates can then be biased when the judge's errors depend on the trajectory and agents differ in the trajectories they produce for successes or failures.", "limit_evidence": ""}, "2611.30670": {"points": [{"subtitle": "조율의 한계와 동기", "desc": "기존 방식은 솔루션을 조율할 때 결과를 단일 점수로만 확인해서 속도가 빠른지만 알 수 있었는데요. 뭔 소리냐면, 왜 빠른지 원인을 알 수 없는 블랙박스 문제였다는 말이에요. 그래서 연구진은 그래픽 처리 장치(GPU) 커널 최적화에서 영감을 받아 APEC을 도입했다고 해요.", "evidence": "Existing Bayesian optimization tuners treat solver tuning as a black-box optimization problem: each evaluation returns a single score, allowing the tuner to learn which configuration is faster, but not why."}, {"subtitle": "APEC의 세 가지 구조", "desc": "APEC은 각 로그를 분석하는 결정론적 계층과 가설 기반 진단을 이끄는 해석 계층, 그리고 평가를 통제하는 시스템 계층으로 이루어져 있는데요. 이 세 가지 층위를 거쳐서 솔루션 조율을 더 믿을 수 있고 해석하기 쉽게 만든다는 겁니다.", "evidence": "APEC has three layers: a deterministic layer that profiles each log, an interpretation layer that guides hypothesis-driven diagnosis, and a system layer that controls evaluation, enabling more reliable and interpretable solver tuning."}, {"subtitle": "성능 개선 결과", "desc": "MIPLIB 2017 벤치마크 시험에서 APEC은 기본 설정보다 1.58배 향상된 성능을 기록했는데요. 동시에 기존 기준 방식보다 파라미터 변경 횟수가 38% 이상 적으면서도 결과를 쉽게 읽을 수 있게 만들었다고 연구진은 주장했어요.", "evidence": "On the full MIPLIB 2017 benchmark set, APEC achieves a 1.58X improvement over the default configuration with over 38% fewer parameter changes than the baselines, making the results easier to read."}], "easy1_evidence": "Existing Bayesian optimization tuners treat solver tuning as a black-box optimization problem: each evaluation returns a single score, allowing the tuner to learn which configuration is faster, but not why.", "easy2_evidence": "On the full MIPLIB 2017 benchmark set, APEC achieves a 1.58X improvement over the default configuration with over 38% fewer parameter changes than the baselines, making the results easier to read.", "topic_evidence": "Inspired by the use of profilers in GPU-kernel optimization, we introduce APEC (Agent for Per-instance Explainable Configuration), a log-grounded tuning agent for MIP solvers.", "limit_evidence": ""}, "2611.30601": {"points": [{"subtitle": "캠오 프레임워크 제안", "desc": "연구진은 미리 학습된 단일 모달 인코더와 교차 모달 잠재 정렬 방식을 묶은 캠오(CAMEO)를 선보였는데요, 이 방식은 아주 적은 수의 짝꿍 샘플만 있어도 공통된 표현을 배울 수 있거든요. 뭔 소리냐면, 데이터가 불완전하게 짝지어진 상황에서도 여러 형태의 데이터를 매끄럽게 합친다는 말이에요.", "evidence": "Combining any pre-trained unimodal encoder with a cross-modal latent alignment mechanism, CAMEO learns shared representations requiring only minimal paired samples."}, {"subtitle": "전산 병리학 성능 평가", "desc": "조직 분류나 세포 유형 예측 같은 전산 병리학 작업에서 성능을 시험해 봤더니, 캠오가 기존 클립(CLIP) 같은 대조 학습 방식보다 데이터 효율 면에서 훨씬 뛰어났다고 해요. 짝지어진 주석이 부족할 때 적대적 정렬이 어떤 이점이 있는지 확실히 보여 준 셈이라는 말이에요.", "evidence": "Evaluated on computational pathology tasks such as niche classification and cell type composition prediction, CAMEO achieves superior data efficiency, outperforming contrastive approaches like CLIP in low paired-data regimes, and highlighting the benefits of adversarial alignment when paired annotations are scarce."}, {"subtitle": "데이터셋 공개와 의의", "desc": "후속 연구를 돕기 위해 세 가지 장기의 이미지와 유전자 발현 데이터가 짝을 이룬 완전 주석화 허깅페이스(HuggingFace) 데이터셋도 함께 공개했는데요, 제한된 짝과 소규모 데이터 문제를 풀면서 멀티모달 학습을 실제 바이오 문제로 넓히는 기틀을 마련했다고 해요. 쉽게 말하면, 모델만 보여준 게 아니라 다른 연구자들도 쓸 수 있게 판을 깔아 줬다는 겁니다.", "evidence": "To facilitate further research, we additionally release a fully annotated HuggingFace dataset comprising three organs and paired image and gene expression modalities."}], "easy1_evidence": "Existing fusion methods rely on large-scale paired datasets, limiting their use in scenarios with incomplete pairing.", "easy2_evidence": "Evaluated on computational pathology tasks such as niche classification and cell type composition prediction, CAMEO achieves superior data efficiency, outperforming contrastive approaches like CLIP in low paired-data regimes, and highlighting the benefits of adversarial alignment when paired annotations are scarce.", "topic_evidence": "We introduce CAMEO, an adversarial learning-based modality fusion framework that integrates modalities from small, partially paired datasets.", "limit_evidence": ""}, "2611.30559": {"points": [{"subtitle": "상태 검증 강화학습 도입", "desc": "AI가 도구를 호출할 때마다 샌드박스 환경에서 작업 결과와 워크플로우 순서를 결정론적 검증기가 직접 확인하게 했는데요, 이를 통해 AI가 학습 환경을 훼손하지 않도록 유도한 겁니다. 뭔 소리냐면, AI의 답변뿐만 아니라 실제 저장된 결과물까지 검증한다는 말이에요.", "evidence": "Within isolated sandboxes that snapshot state around every tool call, a deterministic verifier audits tool effects, workflow ordering, and native auto-sync side effects, pairing graded partial credit with a hard gate that zeroes episode reward upon any critical violation."}, {"subtitle": "성능 향상 및 오류 감소", "desc": "Qwen3.8-27B 모델을 사용해 학습시킨 결과, 벤치마크 점수가 51.47%에서 80.74%로 29.27포인트 상승했는데요, 특히 상태 확인 실패 건수가 180번의 시도 중 63번에서 단 1번으로 줄어들었습니다. 쉽게 말하면, AI가 훨씬 더 정확하고 안정적으로 작동하게 된 겁니다.", "evidence": "After online GRPO training, Qwen3.8-27B raises category-weighted strict success on our benchmark from 51.47% to 80.74% (+29.27 points), cutting content-pass-only execution failures from 45.6% to 13.7% and required state-check failures from 63 to 1 across 180 trials."}, {"subtitle": "효율성 개선", "desc": "이번 모델은 기존의 7개 기준 모델보다 20포인트 이상 높은 성능을 보였는데요, 일반적인 추론 능력은 유지하면서도 8개 외부 벤치마크 중 7개에서 출력 토큰 수를 17~39%까지 줄였습니다. 성능은 높이고 자원 소모는 줄였다는 점에서 효율적이라고 볼 수 있습니다.", "evidence": "The resulting policy outperforms seven reference baselines by over 20 points while reducing output tokens by 17-39% across seven of eight external benchmarks without regressing on general reasoning or tool use."}], "easy1_evidence": "We identify a pervasive failure mode, content-state decoupling, where agents deliver pedagogically sound responses while silently corrupting workspace state through unwarranted updates, missed prerequisites, or unintended side effects.", "easy2_evidence": "We propose State-Verified Reinforcement Learning, which supervises online policy optimization directly through verifiable workspace transitions.", "topic_evidence": "We propose State-Verified Reinforcement Learning, which supervises online policy optimization directly through verifiable workspace transitions.", "limit_evidence": ""}, "2611.30556": {"points": [{"subtitle": "조건부 제약 조건 쪼개기 도입", "desc": "하위 기틀이 조건들을 같이 쓸 수 있도록 허용하는 새로운 쪼개기 개념을 만들어 냈는데요, 기존의 제약 조건 쪼개기를 더 넓힌 셈이에요. 뭔 소리냐면, 딱 잘라 나누기 어려운 조건들도 유연하게 묶어서 다룰 수 있게 되었다는 말이에요.", "evidence": "In this article, we introduce the notion of conditional constraint splittings, extending constraint splittings by also allowing the subbases to share conditionals."}, {"subtitle": "안전하고 국소화된 하위 갈래 찾기", "desc": "조건부 문법 쪼개기에서 아이디어를 얻어 안전하고 완전히 국소화된 하위 갈래들을 찾아냈는데요, 이걸로 하위 기틀 안에서 제약 시스템을 따로따로 독립적으로 풀 수 있게 되었거든요. 계산을 한꺼번에 다 하지 않고 쪼개서 처리할 수 있다는 겁니다.", "evidence": "Taking inspiration from conditional syntax splittings, we identify the subclasses of safe and fully localized conditional constraint splittings, allowing us to locally and independently solve the constraint system on the subbases."}, {"subtitle": "해의 쪼개기와 기존 방식 연결", "desc": "c-표현의 해를 쪼개는 방법도 안전한 조건부 c-해 쪼개기로 넓혀서 제약 조건 쪼개기와 어떤 관계가 있는지 깊게 뜯어봤는데요, 기존에 쓰이던 안전한 덮개 방식들과도 어떻게 이어지는지 자세히 풀어냈다는 겁니다.", "evidence": "We also generalize solution splittings for c-representations to safe conditional c-solution splittings and provide an in-depth analysis of their relationship to conditional constraint splittings."}], "easy1_evidence": "Splitting notions for conditional belief bases aim at localizing reasoning and computation tasks to subbases containing only the relevant parts of the belief base.", "easy2_evidence": "In this article, we introduce the notion of conditional constraint splittings, extending constraint splittings by also allowing the subbases to share conditionals.", "topic_evidence": "In this article, we introduce the notion of conditional constraint splittings, extending constraint splittings by also allowing the subbases to share conditionals.", "limit_evidence": ""}, "2611.30545": {"points": [{"subtitle": "모델과 환경에 따른 실험", "desc": "연구진은 확산 모델과 자기회귀 모델 등 6개 모델을 4가지 수치 정밀도와 세 종류의 GPU에서 최대 100개의 프롬프트로 평가해 봤습니다. 단독 생성과 배치 안에서의 생성을 비교하고 GPU 간 차이까지 꼼꼼히 뜯어본 건데요, 변동이 무작위 노이즈가 아니라 실행 설정에 의해 결정된다는 걸 보여준 겁니다.", "evidence": "We evaluate six text-to-image models (diffusion and autoregressive) under four numerical precisions and quantizations on three GPU types (RTX A6000, RTX 6000 Ada, and H100 NVL), across up to 100 prompts per set for all six models."}, {"subtitle": "구조적 유사도의 하락", "desc": "실험 결과를 살펴보면 단독 이미지와 배로 묶인 출력 사이의 구조적 유사도가 크게 떨어진다는 걸 알 수 있습니다. 자기회귀 모델의 bf16 환경에서는 샘플링 디코딩일 때 0.261까지 떨어지고 그리디 디코딩일 때는 0.229까지 내려간다고 하거든요. 어떤 경우에는 그냥 다른 그림이지만 숫자가 포함된 프롬프트처럼 눈에 띄게 나빠지는 경우도 있다는 말이에요.", "evidence": "For a second autoregressive model in bf16 it falls to 0.261 with sampled decoding and to 0.229 with greedy decoding, and for an fp8 diffusion model to 0.68."}, {"subtitle": "재현성 상실과 후속 과제", "desc": "이러한 결과 때문에 시드만으로는 결과를 재현할 수 없으며 배치 크기나 하드웨어를 섞는 벤치마크는 왜곡될 수 있다는 결론으로 이어집니다. 연구진은 생성 이미지에 대한 안전성 감사나 A/B 테스트를 할 때는 반드시 서빙 설정을 함께 보고해야 한다고 주장했어요. 쉽게 말하면, 하드웨어나 배치 환경을 정확히 밝히지 않으면 공정한 비교가 어렵다는 겁니다.", "evidence": "The consequences are direct: seeds do not make results reproducible, benchmarks and image-quality comparisons that mix batch sizes or hardware can be biased, and safety audits and A/B tests on generated images need the serving setup reported."}], "easy1_evidence": "In text to image AI models, fixing the prompt and the random seed is widely assumed to fix the image. We show that it does not on GPUs.", "easy2_evidence": "Structural similarity between the single-image and the batched output falls to 0.580 for an autoregressive model in bf16 and to 0.551 with int8.", "topic_evidence": "Every replay control reported here is bit-exact, so the variation is not random noise: the execution setting, mainly the batch composition and the GPU, decides the output.", "limit_evidence": ""}, "2611.30422": {"points": [{"subtitle": "HWRE-Bench 벤치마크 설계", "desc": "설계 과정에서 버려지는 이름이나 구조 같은 정보들을 다시 찾아내도록 만드는 다섯 가지 트랙과 네 단계의 정보 손실 조건으로 벤치마크를 꾸렸는데요, 원래 회로만으로는 채울 수 없는 실행 가능한 결과물을 에이전트가 직접 만들어내도록 설계했다는 겁니다. 뭔 소리냐면, 그냥 회로를 베껴 쓰는 꼼수를 막기 위해 똑같은 회로를 복사하는 제어 그룹은 무조건 점수가 0점이 되도록 만들었다는 말이에요.", "evidence": "HWRE-Bench spans five tracks (Extract, Abstract, Audit, Interoperate, Modify), four information-loss levels and white- versus black-box access, all on original designs."}, {"subtitle": "에이전트 역설계 시험 결과", "desc": "두 개의 에이전트를 가지고 16가지 조건에서 148번의 시험을 돌려봤더니, 에이전트들이 스스로 레이아웃 추출기를 짜서 정돈된 회로를 꽤 믿을 만하게 검사해 냈다는 거예요. 다만 회로를 읽을 때 턴 수가 대략 27% 더 많이 걸린다는 단점도 있는데, 대신 암호화를 걸어도 통과율이나 결함 수정 점수에는 아무런 영향을 주지 않았다는 겁니다. 쉽게 말하면, 에이전트가 복잡한 회로를 마주해도 어느 정도 거꾸로 분석해 낼 힘이 있다는 걸 보여준 셈이에요.", "evidence": "Agents built their own layout extractors and audited a sanitized layout as reliably as a netlist, at about 27% more turns."}, {"subtitle": "이해력 검증과 보안 필터의 영향", "desc": "연구진은 에이전트가 정말 회로를 이해한 건지 살펴봤는데, 놀랍게도 구조를 제대로 읽었는지는 본질적인 필요성보다는 질문을 어떻게 던졌느냐에 더 크게 좌우되었다고 주장했어요. 그래서 단순히 맞춘 점수만 보고 에이전트가 하드웨어를 완벽하게 이해했다고 믿기는 어렵다는 건데요, 게다가 한 에이전트는 감사 작업을 하다가 제공자의 안전 필터 때문에 전체 실행의 16%가 막히는 일도 겪었다는 겁니다. 쉽게 말하면, 앞으로는 정답률만 볼 게 아니라 실행 과정이 얼마나 유효했는지 낱낱이 밝혀야 한다는 말이에요.", "evidence": "Whether agents read the structure at all depended on task framing rather than on necessity, so pass rate alone does not show understanding."}], "easy1_evidence": "We ask the reverse question: given an implemented artifact, such as a layout, a gate-level netlist or a protected simulation model, can an agent work out what it does well enough to act on that knowledge?", "easy2_evidence": "We introduce HWRE-Bench, a benchmark for agentic hardware reverse engineering built on one observation.", "topic_evidence": "We introduce HWRE-Bench, a benchmark for agentic hardware reverse engineering built on one observation.", "limit_evidence": "Whether agents read the structure at all depended on task framing rather than on necessity, so pass rate alone does not show understanding."}, "2611.30419": {"points": [{"subtitle": "템퍼서트 벤치마크 구축", "desc": "연구진은 38개 대학의 실제 학위증명서 400장을 바탕으로 위조 방식을 적용해 2만 장이 넘는 위조 이미지 데이터를 만들었는데요. 공개된 기준이 부족했던 기존 상황에서 학위증명서 위조 탐지를 연구할 수 있는 기반을 마련한 거예요.", "evidence": "We present TamperCert, a benchmark built from 400 real degree certificates issued by 38 universities."}, {"subtitle": "다양한 탐지기 성능 평가", "desc": "13개의 탐지기와 상업용 멀티모달 대형 언어 모델(MLLM)을 시험해 봤더니, 모든 위조 방식에 신뢰할 수 있는 탐지기는 하나도 없었다고 해요. 뭔 소리냐면, 어떤 특정 탐지기라도 모든 위조를 완벽히 막아내지는 못한다는 말이에요.", "evidence": "Our findings reveal that no detector is reliable for every tampering method."}, {"subtitle": "후처리와 생성 모델의 한계", "desc": "일반 생성 모델이 만든 위조는 상업용 멀티모달 대형 언어 모델이 대부분 놓쳤고, 이미지를 크기 조절하거나 카메라로 찍는 등의 후처리를 거치면 탐지 성능이 심하게 떨어졌다는 겁니다. 장점은 취약점을 정확히 찾아낸 것이지만, 대신 여전히 영리한 위조를 걸러내기 어렵다는 한계가 같이 남는다는 거예요.", "evidence": "Moreover, the commercial MLLM misses most forgeries made by general-purpose generative models, and post-processing, such as resizing an image or photographing it with a camera, severely degrades detection."}], "easy1_evidence": "Degree certificate forgery is increasingly prevalent.", "easy2_evidence": "We present TamperCert, a benchmark built from 400 real degree certificates issued by 38 universities.", "topic_evidence": "We present TamperCert, a benchmark built from 400 real degree certificates issued by 38 universities.", "limit_evidence": "Our findings reveal that no detector is reliable for every tampering method. Consequently, a determined forger may still evade detection."}, "2611.30412": {"points": [{"subtitle": "두 모델의 협업 구조", "desc": "전체 기록은 추가만 되는 전역 뷰에 남겨 두고 압축기가 안정된 과거 기록을 재사용하게 설계했어요. 뭔 소리냐면, 에이전트는 최근 상호작용만 담긴 압축된 결정 뷰를 보며 일하기 때문에 매번 똑같은 입력 전체를 다시 넣지 않아도 된다는 말이에요.", "evidence": "DMC-5 maintains the raw trajectory as an Append-only Canonical View, preserving global access while allowing the compressor to reuse a stable historical prefix instead of recursively rewriting or recomputing prior context."}, {"subtitle": "중요 정보 보존 기술", "desc": "손실 압축 과정에서 실행에 꼭 필요한 정보가 사라지지 않도록 YAMATO라는 무결성 인식 메모리 추상화 기술을 함께 녹여냈어요. 쉽게 말하면, 덩치를 줄이면서도 도구 작동에 필수적인 핵심 정보는 놓치지 않도록 붙잡아 두는 셈이에요.", "evidence": "DMC-5 further incorporates YAMATO (integritY-Aware Memory Abstractions for Tool Operations) to preserve execution-critical information during lossy compression."}, {"subtitle": "성능과 비용 개선 결과", "desc": "AppWorld, OfficeBench, 8-objective QA 실험에서 에이전트 모델의 입력을 38.5-57.0% 줄이고 전체 비용은 14.5-28.0% 낮췄는데요. 작업 성능도 압축하지 않은 기준선보다 1.0-5.8% 좋아졌고 압축기 캐시 적중률은 78.0-85.0%에 이른다고 해요.", "evidence": "Experiments on AppWorld, OfficeBench, and 8-objective QA show that DMC-5 reduces agent model input by 38.5-57.0% and end-to-end cost by 14.5-28.0% with 78.0-85.0% compressor cache-hit rates, while improving task performance by 1.0-5.8% over the uncompressed baseline."}], "easy1_evidence": "However, existing compression methods on selective context risk losing global information, recursively rewriting summary leads to semantic drift, while repeatedly recompressing the full history shifts the growing cost to the compressor.", "easy2_evidence": "Therefore, we introduce DMC-5 (Dual-Model Collaboration with CaChe-aware Context Compression), an asymmetric framework that assigns full-history integration to a general compression model and action generation to a specialized agent model.", "topic_evidence": "Therefore, we introduce DMC-5 (Dual-Model Collaboration with CaChe-aware Context Compression), an asymmetric framework that assigns full-history integration to a general compression model and action generation to a specialized agent model.", "limit_evidence": ""}, "2611.30390": {"points": [{"subtitle": "데이터 불균형과 프레임워크 제안", "desc": "임상 데이터가 부족하고 불균형한 문제를 풀기 위해 자기지도학습 허버트 표현을 쓰고, 한 명씩 제외하는 교차검증과 균형 잡힌 k-배깅, 몬테카를로 드롭아웃을 묶었다는 거예요. 뭔 소리냐면, 여러 모델을 골고루 학습시키고 확률 평균으로 결과를 모아 신뢰도를 높이려 했다는 말이에요.", "evidence": "We propose an uncertainty-aware ASD screening framework based on self-supervised HuBERT representations, combining Leave-One-Subject-Out (LOSO) crossvalidation, balanced k-bagging, and Monte Carlo (MC) Dropout."}, {"subtitle": "CPSD 데이터베이스 실험 성능", "desc": "아동 병리 음성 데이터베이스(CPSD)로 실험을 해봤더니, 발화 수준에서는 균형 정확도 86.30%와 ROC-AUC 93.74%를 기록했는데요. 환자 수준에서는 각각 95.04%와 96.30%로 더 높은 수치를 보였다는 겁니다.", "evidence": "Experiments on the Child Pathological Speech Database (CPSD) show strong performance, achieving 86.30% balanced accuracy and 93.74% ROC-AUC at the utterance level, and 95.04% and 96.30%, respectively, at the subject level."}, {"subtitle": "예측 엔트로피와 오류 감지", "desc": "예측 엔트로피가 분류 신뢰도를 잘 보여주는지 확인해 봤는데요, 틀리게 분류된 조각이 맞게 분류된 조각보다 엔트로피가 더 높았고(0.4605 ± 0.2314 대 0.1717 ± 0.1830), 오류와도 유의미한 상관관계를 보여 오류 감지 ROC-AUC가 0.8359로 나타났다고 해요.", "evidence": "Furthermore, predictive entropy effectively reflects classification reliability: incorrectly classified segments show higher entropy than correctly classified ones (0.4605 $\\pm$ 0.2314 vs. 0.1717 $\\pm$ 0.1830), with a significant correlation with errors (r = 0.3981, p = 7.38 x 10 -170 ) and an error-detection ROC-AUC of 0.8359."}], "easy1_evidence": "Early screening of Autism Spectrum Disorder (ASD) is critical for timely clinical intervention, although establishing reliable speech based screening systems remains problematic due to limited clinical data, class imbalance, and the need for reliable uncertainty estimation.", "easy2_evidence": "We propose an uncertainty-aware ASD screening framework based on self-supervised HuBERT representations, combining Leave-One-Subject-Out (LOSO) crossvalidation, balanced k-bagging, and Monte Carlo (MC) Dropout.", "topic_evidence": "We propose an uncertainty-aware ASD screening framework based on self-supervised HuBERT representations, combining Leave-One-Subject-Out (LOSO) crossvalidation, balanced k-bagging, and Monte Carlo (MC) Dropout.", "limit_evidence": ""}, "2611.30353": {"points": [{"subtitle": "PseuDRAGON 시스템 구성", "desc": "확정된 판단과 수정을 고정된 모델 외부에 두고 정확한 이름 찾기와 학습된 규칙으로 재사용하는 구조인데요. 전문가 검토 과정에서는 기관 정책, 국가 개인정보법, 국제 출처 순으로 검색하는 워크플로를 따르도록 만들었다는 말이에요.", "evidence": "PseuDRAGON keeps confirmed judgments and corrections outside a fixed model and reuses them through exact-name lookup and learned rules."}, {"subtitle": "규칙 재사용과 성능 검증", "desc": "한 기관의 92개 컬럼을 대상으로 실험해 보니, 모든 학습 판단을 쓸 수 있을 때는 같은 승인 검사 아래에서 재사용 라벨이 75개에서 83개로 늘어났다고 해요. 학습 판단을 25%만 쓸 때는 보이지 않는 이름에 대한 규칙을 빼면 추가로 개인정보를 놓치는 실수를 없앨 수 있지만 재사용률은 낮아진다는 겁니다.", "evidence": "Across 92 columns from one institution, rules increase reuse under the same approval checks from 75 to 83 labels without reuse errors when all training judgments are available."}, {"subtitle": "이력 기반 기준선의 시간 단축", "desc": "승인을 고치거나 철회하면 유도된 규칙이 다시 만들어지고 가상 레코드 테스트로 선택된 방법이 지정된 출력을 내는지 검증했는데요. 세 번의 짝지어진 실행에서 이력 우선 기준선은 재사용을 안 했을 때와 비교해 자동 식별 시간을 평균 83.0% 줄였다고 해요.", "evidence": "In three paired runs, the history-first baseline cut automated identification time by 83.0% on average versus no reuse."}], "easy1_evidence": "Local language models can assist, but may give different labels for the same input.", "easy2_evidence": "Across 92 columns from one institution, rules increase reuse under the same approval checks from 75 to 83 labels without reuse errors when all training judgments are available.", "topic_evidence": "PseuDRAGON: Knowledge-Guided Local LLMs for Financial-Data Pseudonymization in Closed Networks", "limit_evidence": ""}, "2611.30335": {"points": [{"subtitle": "문맥 발견기와 대화 캐셔 도입", "desc": "기존 RAG-DIVE를 확장하여 대화 중에 여러 문서 조합을 찾는 문맥 발견기를 넣었고요, 동적 시뮬레이션의 높은 계산 비용을 줄이려고 이전 실행의 대화 턴을 재사용하는 대화 캐셔를 함께 도입했다는 겁니다. 뭔 소리냐면, 평가의 역동성을 유지하면서도 토큰 사용량을 크게 아낄 수 있다는 말이에요.", "evidence": "The framework extends RAG-DIVE with a Context Discoverer, which identifies documents that can be combined to generate multi-hop questions within an ongoing conversation."}, {"subtitle": "여섯 가지 RAG 설정 비교 실험", "desc": "여섯 가지 RAG 설정에서 이 프레임워크를 평가하고 기존 방식과 정적인 CLAPNQ 데이터셋과 결과를 비교해 봤는데요, 일관된 성능 경향을 보이면서도 더 복잡한 멀티홉 환경이 시스템에 새로운 어려움을 드러내게 만들었다는 겁니다.", "evidence": "We evaluate the framework across six distinct RAG configurations and compare its results with the original RAG-DIVE evaluation and the static, human-created CLAPNQ dataset."}, {"subtitle": "산업용 RAG 시스템 적용", "desc": "도메인 특화 데이터를 쓰는 산업용 RAG 시스템에도 이 프레임워크를 적용해 보았는데요, 실제 현장 평가 시나리오에도 쓸 수 있음을 보여주면서 제안한 접근법이 더 복잡하고 비용 효율적인 평가 방식을 제공한다고 밝혔거든요.", "evidence": "Finally, we apply MH-RAG-DIVE to an industrial RAG system with domain-specific data, demonstrating its applicability to real-world evaluation scenarios."}], "easy1_evidence": "However, existing evaluation approaches often rely on single-turn or single-hop interactions and therefore do not capture the complexity of multi-hop, multi-turn conversations.", "easy2_evidence": "To address the high computational cost of dynamic user simulation, we further introduce a Conversation Cacher, which reuses turns from previous evaluation runs while preserving the dynamic nature of the evaluation.", "topic_evidence": "We introduce MH-RAG-DIVE, a dynamic interactive user simulation framework designed to evaluate RAG systems in more complex multi-hop and multi-turn settings.", "limit_evidence": ""}, "2611.30281": {"points": [{"subtitle": "혼합 추론의 표현 호환성", "desc": "연구진은 최적의 자가회귀 모델이 잠재된 추론 혼합물과 어떻게 호환되는지 형식화해 분석했어요. 접두사 사후 확률로 모드를 가중치에 반영하고 다른 모드의 가능성이 낮아지면 하나의 모드에 집중하는 방식으로 목표 분포가 정해진다는 거예요. 뭔 소리냐면, 모델이 서로 다른 풀이 방식을 섞어 놓아도 수학적으로 표현하고 학습하는 데 큰 무리가 없다는 말이에요.", "evidence": "We first formalize the representational compatibility of the optimal autoregressive model with latent reasoning mixtures: the target next-token distribution weights modes by their prefix posteriors and concentrates on a single mode once alternative modes assign negligible likelihood to the prefix."}, {"subtitle": "너비 우선과 깊이 우선 탐색 환경 실험", "desc": "너비 우선 탐색과 깊이 우선 탐색 경로가 짝지어 인증된 기호 그래프 검색 환경에서 실험을 진행했는데요. 토큰 예산을 맞춘 상태에서 라벨이 없는 혼합 SFT 방식은 동종 방식이나 라벨이 있는 기준선과 비교했을 때 두 모드를 모두 유지하면서도 별다른 단점이 나타나지 않았다고 해요. 쉽게 말하면, 따로 정답 표시를 주지 않고 섞어 가르쳐도 기존 방식만큼 두 가지 전략을 잘 품어낸다는 겁니다.", "evidence": "In a verifiable symbolic graph-search environment with paired breadth-first and depth-first search trajectories, no consistent disadvantage is observed for unlabeled mixed SFT relative to homogeneous or labeled baselines under matched token budgets while preserving both modes."}, {"subtitle": "핵심 추론 노드(CRN)와 국소적 수리", "desc": "모든 국소적 실수가 결과에 영향을 주는 것은 아니며, 이후 과정이 그 단계에 민감할 때만 결과가 바뀐다는 점을 밝혔어요. 그래서 단 한 번의 수정으로도 망가진 경로를 되살릴 수 있는 핵심 추론 노드가 전체의 작은 비율에 불과하다는 걸 확인했는데요. 남은 유도 과정을 끝낼 하위 능력이 모델에 있다면 이 핵심 노드들을 한 단계씩 고쳐서 성능을 구해낼 수 있다는 거예요.", "evidence": "Because a local mistake affects the final outcome only when subsequent reasoning is sensitive to that step, we find that only a small fraction of local errors are outcome-determining \\emph{Critical Reasoning Nodes (CRNs)}, and that single-step repairs at these nodes rescue failing trajectories across symbolic search and natural language benchmarks whenever the model has sufficient downstream competence to complete the remaining derivation."}], "easy1_evidence": "Post-training large language models routinely pools reasoning trajectories from diverse teachers or algorithms, yet it remains unclear whether standard supervised fine-tuning (SFT) can learn such heterogeneous strategies without explicit mode conditioning.", "easy2_evidence": "Scaling across 0.6B--14B models and data budgets largely eliminates global mode confusion, shifting the primary bottleneck to local state-tracking transitions.", "topic_evidence": "We study the learnability and local bottlenecks of heterogeneous reasoning through a formal mixture formulation and controlled experiments.", "limit_evidence": ""}, "2611.30233": {"points": [{"subtitle": "고립된 제약 대조 학습", "desc": "군집 기반으로 쪼갠 데이터에서 전문가들을 따로 훈련시켜서 전문가들이 각자 맡은 분야를 빠르게 익히도록 만들었어요. 뭔 소리냐면, 데이터 성격에 맞는 전문가들을 따로 빠르게 길러냈다는 말이에요.", "evidence": "Our method uses Isolated Constrained Contrastive Learning, a pipeline that trains specialized experts on cluster-based data partitions to accelerate expert specialization."}, {"subtitle": "퓨전 게이트 메커니즘", "desc": "새로운 것을 배울 때 기존에 알던 지식을 까먹는 치명적 망각 문제를 막으려고 퓨전 게이트 장치를 더했어요. 기존 지식을 지키면서 새 학습 결과를 묶어 주는 역할을 한다는 겁니다.", "evidence": "Additionally, we introduce a Fusion Gate mechanism to mitigate catastrophic forgetting of pre-trained knowledge."}, {"subtitle": "다양한 벤치마크 실험 결과", "desc": "여러 벤치마크에서 실험해 봤더니, 제로샷 성능을 그대로 지키면서 하위 과제 성능은 꾸준히 좋아지는 결과가 나왔어요. 다양한 문맥 길이에서도 튼튼한 성능을 보여서 여러 실제 현장에 쓰기 좋다고 연구진은 밝혔습니다.", "evidence": "Extensive experiments across multiple benchmarks demonstrate that our approach achieves consistent improvements on downstream tasks while preserving zero-shot capabilities."}], "easy1_evidence": "However, existing MoE adaptations for Contrastive Language-Image Pre-training (CLIP) models suffer from significant computational overhead during sequential training and degradation of zero-shot capabilities.", "easy2_evidence": "To address these limitations, we propose CLIP-FMoE, a novel approach that integrates MoE architecture into CLIP fine-tuning.", "topic_evidence": "To address these limitations, we propose CLIP-FMoE, a novel approach that integrates MoE architecture into CLIP fine-tuning.", "limit_evidence": ""}, "2611.30200": {"points": [{"subtitle": "다중 에이전트 강화학습 모델", "desc": "사람 에이전트와 AI 에이전트를 함께 넣은 마르코프 결정 과정(MDP) 기반의 강화학습 틀을 세웠는데요, 핵심은 AI 기술을 넣으면 AI의 당장 보상만 커지는 게 아니라 사람과 AI의 상태까지 바꾼다는 점을 반영했다는 겁니다. 뭔 소리냐면, 서로 영향을 주고받는 전체 흐름을 시간 흐름에 따라 살펴보겠다는 말이에요.", "evidence": "The proposed multi-agent RL MDPs incorporate both human agents and AI agents."}, {"subtitle": "세 가지 실제 적용 분석", "desc": "이 틀을 가지고 AI를 남에게 떠넘기다가 기술이 녹슬어 버리는 현상, AI를 쓰는 기업의 알맞은 인력 구조, 그리고 사람과 AI 사이의 거래와 고용에서 나타나는 경제적 균형을 각각 살펴봤는데요. 다양한 상황에서 어떤 식으로 균형이 잡히는지 구체적으로 따져본 셈이에요.", "evidence": "In particular, we apply this framework to analyzing AI offloading leading to skill erosion, to analyzing optimal human resource structures for a firm adopting AI, and to analyzing the economic equilibria in the trading/employment among human and AI agents."}, {"subtitle": "AI로 AI 문제 해결하기", "desc": "결국 제어와 기계학습에서 나온 다중 에이전트 MDP 기반 강화학습 기술을 써서, AI 기술을 함정 없이 도입하거나 함께 살아가는 가장 알맞은 길을 찾아냈다는 거예요. 쉽게 말하면, AI 기술의 부작용을 막는 데 AI 학습 기법을 거꾸로 써먹은 셈입니다.", "evidence": "Since the multi-agent MDP based RL technique is from control, machine learning and AI, this research is essentially using an AI technique to determine the optimal ways of adopting or co-existing with AI without traps."}], "easy1_evidence": "Adopting AI technologies can bring immediate, and sometimes tremendous, rewards such as through productivity boost, but they can also bring negative effects including but not limited to losses of job and training opportunities, and cognitive capability declines.", "easy2_evidence": "In this paper, we develop a general multi-agent Markov decision process (MDP) based reinforcement learning (RL or MARL) modeling framework for determining and analyzing optimal adoption of AI technologies.", "topic_evidence": "In this paper, we develop a general multi-agent Markov decision process (MDP) based reinforcement learning (RL or MARL) modeling framework for determining and analyzing optimal adoption of AI technologies.", "limit_evidence": ""}, "2611.29989": {"points": [{"subtitle": "데이터 전처리와 품질 관리", "desc": "연구진은 111명의 환자에게서 얻은 213개의 CPTAC-LUAD 조직 샘플을 분석해서 9518개의 단백질을 남겼는데요, 거짓 발견율(FDR) 0.05 미만과 절대 평균 짝지은 로그비 차이 1 이상인 조건으로 378개의 단백질을 추려냈다는 겁니다. 뭔 소리냐면, 그중 40개는 늘어났고 338개는 줄어들었다는 말이에요.", "evidence": "Results: Quality control retained 9,518 proteins. At FDR below 0.05 and an absolute mean paired log-ratio difference of at least 1, 378 were differentially abundant (40 increased, 338 decreased)."}, {"subtitle": "분류 모델과 규칙 학습", "desc": "희소 로지스틱 회귀 분류기를 돌려봤더니 수치가 아주 높게 나왔는데요, ROC-AUC 0.9997, 평균 정밀도 0.9998, 정확도 0.9906으로 나타났다는 겁니다. 여기에 1차 논리 규칙(FOL/ILP) 학습을 따로 평가해 봤더니 보류 정확도 0.9765와 F1 점수 0.9774를 기록했다고 해요.", "evidence": "The sparse classifier yielded ROC-AUC 0.9997, average precision 0.9998, accuracy 0.9906, and balanced accuracy 0.9906. FOL/ILP yielded held-out accuracy 0.9765, balanced accuracy 0.9767, precision 0.9818, recall 0.9730, and F1 0.9774."}, {"subtitle": "핵심 단백질과 한계점", "desc": "HSPA12B와 같은 단백질들은 모든 분류기 폴드에서 0이 아닌 계수를 보였는데요, 다만 이번 성능은 하나의 코호트 안에서 나온 결과라는 한계가 있다는 겁니다. 그래서 연구진은 생체표지자 주장을 확정하려면 독립적인 검증과 추가적인 생물학적 주석 작업이 필수적이라고 강조했어요.", "evidence": "HSPA12B, PALM2-AKAP2, STARD13, and PPM1F had non-zero coefficients in all five classifier folds. The most frequent Horn clause occurred in two of five folds. All others occurred once."}], "easy1_evidence": "Background: We developed an interpretable workflow linking paired differential proteomics, sparse logistic regression, SHAP attribution, and first-order logic (FOL) rule learning in lung adenocarcinoma (LUAD).", "easy2_evidence": "Conclusions: The workflow connects proteomic classification, attribution, and symbolic rules. Performance reflects tumour-versus-adjacent-normal discrimination within one cohort. Biomarker and clinical claims require independent validation, repeated assessment of rule stability, and further biological annotation.", "topic_evidence": "Background: We developed an interpretable workflow linking paired differential proteomics, sparse logistic regression, SHAP attribution, and first-order logic (FOL) rule learning in lung adenocarcinoma (LUAD).", "limit_evidence": "Biomarker and clinical claims require independent validation, repeated assessment of rule stability, and further biological annotation."}, "2611.29975": {"points": [{"subtitle": "다중 규칙 불일치 문제", "desc": "연구진은 전체 규칙 세트를 한꺼번에 제시하면 모델이 개별 규칙을 판단할 때와 다른 결론을 내리는 '다중 규칙 불일치' 현상을 발견했는데요. 뭔 소리냐면, 규칙이 모여 있을 때 모델이 훨씬 더 너그러운 판정을 내린다는 말이에요. 예를 들어 모델이 다른 목적을 쫓지 못하게 막는 안전 규칙이 큰 규칙 속에 섞여 있으면, 테스트한 모든 판정 모델이 위반으로 볼 확률이 낮아졌습니다.", "evidence": "We call this challenge multi-rule inconsistency and find that models are more lenient when judging rules embedded within the full ruleset than when judging rules separately."}, {"subtitle": "모순을 줄이는 방법 탐색", "desc": "그래서 연구진은 이런 불일치를 줄이기 위해 프롬프트 방식, GRPO를 활용한 일관성 훈련, 그리고 반복적인 규칙 다듬기 같은 여러 방법을 살펴봤는데요. 법률 해석에서 주변 법 조항이 뜻을 바꾸듯, 판정 모델 안에서도 주변 규칙들이 해석에 영향을 준다는 거예요. 다만 사람의 법 집행과 달리, 현재 이러한 상호작용은 모델 내부에서 겉으로 드러나지 않고 암묵적으로 일어나는 중이라는 겁니다.", "evidence": "We examine several methods for reducing inconsistency, including prompting, consistency training using GRPO, and iterative rule refinement."}, {"subtitle": "명시적 관리의 필요성", "desc": "결과적으로 연구진은 해석이 저도 모르게 틀어지는 바람에 뒷단에서 정렬 실패가 생기는 것을 막으려면, 규칙 설계자가 여러 규칙 사이의 상호작용을 겉으로 드러내서 직접 재고 다뤄야 한다고 강조했는데요. 쉽게 말하면, 모델 내부에서 알아서 하도록 내버려 두지 말고 사람이 직접 붙잡고 관리해야 한다는 말이에요.", "evidence": "We argue that multi-rule interactions must be measured and handled explicitly by ruleset designers to prevent undetected shifts in interpretation from causing downstream alignment failures."}], "easy1_evidence": "However, as we show in this work, presenting an entire ruleset to a judge model---rather than asking it to judge one rule at a time---changes the way the model interprets the requirements, making it reach conclusions that conflict with its rule-by-rule judgments.", "easy2_evidence": "We argue that multi-rule interactions must be measured and handled explicitly by ruleset designers to prevent undetected shifts in interpretation from causing downstream alignment failures.", "topic_evidence": "Technical governance of AI models will soon require them to reason over and follow thousands of rules from different jurisdictions.", "limit_evidence": ""}, "2611.29876": {"points": [{"subtitle": "실험 설계와 기초 상관관계", "desc": "연구진은 15만 장의 합성 이미지로 사전학습된 ConvNeXt-Small 모델을 100개, 400개, 혹은 1600개의 레이블로 미세조정해 봤는데요, 하나의 공식 체크포인트에서 나온 5개의 미세조정 시드로 구한 평균 잔차 상관관계를 확인해 보니 전도도는 0.994, 강성도는 0.999로 나타났어요. 뭔 소리냐면, 전체적인 경향성 자체는 아주 높게 일치했다는 말이에요.", "evidence": "A ConvNeXt-Small is pretrained on 150,000 synthetic images by formula regression or masked reconstruction and fine-tuned on 100, 400, or 1600 labels."}, {"subtitle": "전도도 과제에서의 혼동 요인 분석", "desc": "전도도 과제에서는 지수 이동 평균(EMA) 감쇠가 0.995이고 편향 보정이 없는 상태로 400개 레이블 일정이 끝난 뒤에도 초기 가중치의 16%를 유지하고 있었는데요, 이 때문에 예측 오차가 커졌던 거예요. 지수 이동 평균을 빼고 계산했더니 기울기가 0.97로 회복되었고, 불일치 체크포인트는 이미지넷 오차의 1.4배 수준을 보였다는 겁니다.", "evidence": "Without the EMA the slope is 0.97, and over three subsets and five seeds the mismatched checkpoint has 1.4 times the ImageNet error (0.0119 versus 0.0084)."}, {"subtitle": "강성도 과제에서의 성능 개선", "desc": "반면 강성도 과제에서는 지수 이동 평균을 제거했더니 공식 사전학습이 5개 시드에 걸쳐 이미지넷 대비 100개 레이블 오차를 18% 낮춰주는 결과를 보여줬어요. 쉽게 말하면, 조건이 맞을 때는 공식 기반 사전학습이 적은 데이터 환경에서도 확실히 도움이 된다는 말입니다.", "evidence": "On stiffness without the EMA, formula pretraining lowers the 100-label error by 18% versus ImageNet over five seeds, including a re-initialized head, while ImageNet seeds also correlate at 0.992."}], "easy1_evidence": "On conductivity the formula network compresses its predictions (slope 0.64) and has four times the 400-label error of ImageNet initialization.", "easy2_evidence": "Weight averages that start at the pretrained weights can dominate small-budget comparisons and should be rechecked at the last weights.", "topic_evidence": "Closed-form physics formulas can label synthetic microstructures at no cost, so supervised pretraining on those labels is an alternative to self-supervised pretraining when labels are scarce.", "limit_evidence": ""}, "2611.29744": {"points": [{"subtitle": "진단 프로토콜 제안", "desc": "연구진은 모델들이 자금세탁의 흐름을 배우는지 아니면 보낸 사람 정보를 외우는지 구분하려고 여러 가지 기준을 조합한 진단 방식을 만들었는데요. 송신자 조회 기준선이나 새로운 데이터 기준선, 그리고 송신자가 겹치지 않게 나누는 방식 등을 함께 활용했어요. 뭔 소리냐면, 모델이 어떤 힌트를 보고 정답을 맞히는지 낱낱이 뜯어보겠다는 말이에요.", "evidence": "We ask whether models trained on these benchmarks learn how laundering moves or merely who sent the money, and we propose a diagnostic protocol to tell the two apart: a sender lookup baseline, a novelty baseline, a sender-disjoint split with a leakage check, and a decomposition of performance into sender, receiver and intrinsic signal."}, {"subtitle": "Elliptic2의 꼼수 의존", "desc": "Elliptic2 데이터셋으로 실험해 봤더니, 복잡한 특징을 안 쓰고 보낸 사람 기록만 단순 조회해도 PR-AUC가 0.954에 달하는 높은 수치를 보였는데요. 송신자 정보를 아예 빼버리면 성능이 0.126까지 뚝 떨어진다는 거예요. 쉽게 말하면, 모델이 자금세탁을 찾아낸 게 아니라 보낸 사람 얼굴을 기억해서 맞혔던 셈이라는 말이에요.", "evidence": "On Elliptic2 the task largely reduces to classifying the sender."}, {"subtitle": "Elliptic++의 탄탄한 결과", "desc": "반면에 Elliptic++ 데이터셋에서는 보낸 사람을 맞추는 단순 방식의 PR-AUC가 0.340에 그쳐 전체 모델 성능인 0.986보다 훨씬 낮았는데요. 송신 주소를 숨기고 테스트해 봐도 본래의 특징들이 0.883의 성능을 그대로 유지했다는 장점이 있어요. 이것은 보낸 사람의 단위가 달라서 생기는 결과로, 벤치마크마다 꼼수의 심각성이 다르다는 걸 보여준다는 겁니다.", "evidence": "On Elliptic++ the same protocol finds the shortcut negligible: sender history reaches only 0.340 against 0.986 for the full model (3.5 against 10.1 times the test prevalence), adding it to the full model raises PR-AUC by less than 0.004 in every seed, and the transaction's own features keep 0.883 when sending addresses are held out."}], "easy1_evidence": "We ask whether models trained on these benchmarks learn how laundering moves or merely who sent the money, and we propose a diagnostic protocol to tell the two apart: a sender lookup baseline, a novelty baseline, a sender-disjoint split with a leakage check, and a decomposition of performance into sender, receiver and intrinsic signal.", "easy2_evidence": "A shared sender-based label rule thus produces a severe shortcut in one benchmark and a negligible one in the other, so the diagnostic must be run on each benchmark.", "topic_evidence": "We ask whether models trained on these benchmarks learn how laundering moves or merely who sent the money, and we propose a diagnostic protocol to tell the two apart: a sender lookup baseline, a novelty baseline, a sender-disjoint split with a leakage check, and a decomposition of performance into sender, receiver and intrinsic signal.", "limit_evidence": "A shared sender-based label rule thus produces a severe shortcut in one benchmark and a negligible one in the other, so the diagnostic must be run on each benchmark."}, "2611.29519": {"points": [{"subtitle": "하네스 디자인 제안", "desc": "연구진은 에이전트 런타임에 모델의 중간 상태와 레이어 수준의 실행 제어를 노출하는 하네스 디자인을 내놓았습니다. 상태 수집과 정책 피팅 및 실행을 연결해서 모델 안팎으로 계산을 나누어 맡기게 만든다는 건데요. 뭔 소리냐면, 모델의 속 상태를 활용해 연산 자원을 똑똑하게 쓰게 만들겠다는 말이에요.", "evidence": "By connecting state collection, policy fitting, and execution, the design enables policies to allocate computation within and across models based on intermediate states."}, {"subtitle": "시제품 구현과 추론 적용", "desc": "쌍을 이룬 모델 상태에서 브리지와 정책을 학습한 뒤 추론 때 continue와 exit 그리고 stitch 중에서 고르도록 시제품을 구현해 적용했습니다. 디스패처 감독을 위해 소스 모델의 전체 깊이 예측과 다음 토큰 예측이 일치하는 최소 계산 행동을 골랐는데요. WildChat 대화 원문으로 만든 5,000개의 항목으로 구성된 프록시 코퍼스로 이 구성 요소들을 학습시켰다는 거예요.", "evidence": "We train these components on a frozen proxy corpus of 5,000 typed-decision items authored using source texts sampled from WildChat conversations, then evaluate the prototype on JevBench measuring task accuracy, agreement with full-model predictions, and end-to-end latency including runtime overhead."}, {"subtitle": "지연 시간 감소와 정확도 유지", "desc": "JevBench로 작업 정확도와 예측 일치도 및 지연 시간을 측정한 예비 결과가 나왔는데요. 전체 모델 추론과 비슷한 수준의 작업 정확도를 유지하면서도 평균 지연 시간은 약 15% 줄어드는 것으로 나타났다고 합니다. 쉽게 말하면, 정확도를 까먹지 않으면서도 속도를 꽤 챙겼다는 셈이에요.", "evidence": "Preliminary results show an approximately 15% reduction in mean latency while maintaining task accuracy comparable to full-model inference."}], "easy1_evidence": "Agent frameworks typically orchestrate language models through prompt-and-response interfaces.", "easy2_evidence": "Preliminary results show an approximately 15% reduction in mean latency while maintaining task accuracy comparable to full-model inference.", "topic_evidence": "We propose a harness design that exposes intermediate model states and layer-level execution controls to the agent runtime.", "limit_evidence": ""}, "2611.29473": {"points": [{"subtitle": "노름 공리의 역할", "desc": "값 매겨진 하이퍼필드가 필드의 몫일 때 노름 공리가 값매김에 대한 특정 조건을 강제한다는 것을 보여줬는데요. 뭔 소리냐면, 이 공리가 기존에 발표된 명제의 증거를 완성하고 질문의 방향을 필드의 몫인지 묻는 것으로 바꾼다는 말이에요.", "evidence": "If a valued hyperfield is a quotient K^times/Tcup{0} of a field, the norm axiom forces T=1+m_ρ for a valuation on K."}, {"subtitle": "값 군 Z에서의 증명", "desc": "값 군이 Z일 때는 해당 성질이 성립함을 직접 증명해 냈는데요. 하지만 노름 공리가 빠지면 그 답은 아니오가 된다는 점도 같이 확인했다는 겁니다.", "evidence": "For value group Z we prove directly that it is."}, {"subtitle": "매수루스 하이퍼필드 분석", "desc": "하이퍼필드를 비자명한 순서화된 아벨 군 위에 얹으면 팩터 하이퍼필드가 되는 조건을 살펴봤는데요. 매수루스의 하이퍼필드는 다른 공리를 다 만족해도 팩터 하이퍼필드는 아니라는 단점도 있는데, 전체적인 일반 질문은 아직 열려 있다는 겁니다.", "evidence": "Layering a hyperfield over a non-trivial ordered abelian group gives a factor hyperfield exactly when the hyperfield itself is one, so Massouros's hyperfields yield hyperfields with a non-trivial valuation, satisfying all the other axioms, that are not factor hyperfields."}], "easy1_evidence": "Touchard and the author asked whether every valued hyperfield, in Krasner's sense with the norm axiom, is of the form H_ρ(K): a valued field K read up to relative error ρ.", "easy2_evidence": "For value group Z we prove directly that it is.", "topic_evidence": "Touchard and the author asked whether every valued hyperfield, in Krasner's sense with the norm axiom, is of the form H_ρ(K): a valued field K read up to relative error ρ.", "limit_evidence": "The general question remains open."}, "2611.29306": {"points": [{"subtitle": "도펠벳의 작동 방식", "desc": "안전 라벨 없이 기존 검증기의 신호와 일치하는 대안을 만들고, 두 업데이트를 같은 상태에서 다시 실행해 본다는 거예요. 뭔 소리냐면, 두 행동의 순서를 바꿔 가며 직접 비교해서 후보를 남길지 정한다는 말이에요.", "evidence": "Without access to safety labels, DoppelVet constructs an alternative that matches every signal used by the existing verifier."}, {"subtitle": "탐지 성능 향상", "desc": "아홉 개의 오픈웨이트 및 독점 검증기를 대상으로 테스트해 봤더니, 유해 업데이트 탐지 면적(AUC)이 도펠벳 그리드(DoppelVet-Grid)에서는 0.762에서 0.940으로, 도펠벳 툴(DoppelVet-Tool)에서는 0.681에서 0.826으로 높아졌다는 거예요.", "evidence": "Across nine open-weight and proprietary verifiers, DoppelVet raises mean harmful-update detection AUC from 0.762 to 0.940 on DoppelVet-Grid and from 0.681 to 0.826 on DoppelVet-Tool, outperforming VaG and AgentDoG 1.5."}, {"subtitle": "성능 저하 감소", "desc": "열 세대 동안 자가 업데이트를 반복하는 루프를 거쳤을 때, 성능 저하를 겪는 경로가 30.39%에서 0.43%로 줄어들었다고 해요. 쉽게 말하면, 마지막에는 성능 저하가 아예 남지 않게 되었다는 겁니다.", "evidence": "On DoppelVet-Grid, it reduces trajectories experiencing degradation from 30.39% to 0.43% over a ten-generation self-update loop and leaves no final degradation."}], "easy1_evidence": "Two updates can provide exactly the same evidence to a verifier yet produce opposite safety outcomes, so the verifier cannot distinguish them from that evidence alone.", "easy2_evidence": "We introduce DoppelVet, a verification framework that checks proposed updates before they enter an agent's persistent state.", "topic_evidence": "We introduce DoppelVet, a verification framework that checks proposed updates before they enter an agent's persistent state.", "limit_evidence": ""}, "2611.29259": {"points": [{"subtitle": "반사실적 세계 모델의 도입", "desc": "연구진은 환경 전체를 처음부터 새로 상상하는 방식 대신, 이미 관찰된 궤적을 바탕으로 다른 행동을 대입해 결과를 예측하는 반사실적 세계 모델을 제시했는데요. 뭔 소리냐면, 환경의 무작위성은 그대로 두고 행동에 따른 변화만 따로 떼어내서 살펴보겠다는 말이에요.", "evidence": "Counterfactual world models condition on observations to predict alternative outcomes under the same underlying environmental randomness, using experience as a reference for predicting action-dependent changes."}, {"subtitle": "RLB 추정기 제안과 수학적 증명", "desc": "반사실적 보상을 기준으로 삼아 환경의 우연과 행동의 효과를 구분하는 정책 기울기 추정기인 REINFORCE Look Back(RLB)을 소개했어요. 연구진은 이 방법이 편향을 없애고 분산을 줄일 수 있는 수학적 조건도 함께 증명했다고 밝혔답니다.", "evidence": "We present a policy gradient estimator, REINFORCE Look Back (RLB), that uses counterfactual returns as baselines to distinguish action effects from environmental luck, and prove conditions for unbiasedness and variance reduction."}, {"subtitle": "학습 성능 비교와 발견", "desc": "환경 변화를 예측하기가 행동 변화보다 어려운 환경에서는 반사실적 세계 모델이 기존 모델보다 훨씬 학습하기 쉽고 정책 학습에도 유리하다는 것을 보여줬는데요. 쉽게 말하면, 에이전트가 복잡한 세상을 다 복제하지 않고도 반사실적 사고를 통해 효과적인 행동을 익힐 수 있다는 겁니다.", "evidence": "Our findings suggest that counterfactual thinking can help agents learn effective behavior without independently reproducing the full complexity of their worlds."}], "easy1_evidence": "Agents in complex, stochastic environments must contend with dynamics that can exceed their world models' predictive capacity and randomness that obscure the consequences of their actions.", "easy2_evidence": "We present a policy gradient estimator, REINFORCE Look Back (RLB), that uses counterfactual returns as baselines to distinguish action effects from environmental luck, and prove conditions for unbiasedness and variance reduction.", "topic_evidence": "We hypothesize that, compared to imagining entirely new trajectories in such complex environments, it can be easier to transform observed trajectories with alternative actions.", "limit_evidence": ""}, "2611.29255": {"points": [{"subtitle": "노에베라의 구조와 작동 방식", "desc": "출처 증거와 재사용 가능한 종합, 에이전트 기억이라는 세 가지 평면으로 지식 베이스를 만들고, 필요할 때 시뮬레이터를 호출해서 수치적 근거를 채우게 해 봤는데요. 뭔 소리냐면, 에이전트가 자료를 모아서 근거 팩을 만들고 역할을 나눠 추론한 뒤에 시뮬레이터로 검증한다는 말이에요.", "evidence": "Decision-aware retrieval assembles compact evidence packs, role-specific agents reason over them and invoke a simulator (Vidur or GAUSS) whenever quantitative support is needed, and every finding is written back as a scoped evidence record, so knowledge guides experiments and experiments refine knowledge."}, {"subtitle": "설정 탐색과 성능 결과", "desc": "네 가지 서빙 시나리오에서 설정을 찾아봤더니, 노에베라는 베이지안 최적화나 지식이 없는 에이전트보다 더 적은 횟수로 최적값에 가까워졌다고 해요. 에이100(A100) 그래픽 처리 장치(GPU) 환경에서는 브이엘엘엠(vLLM) 기본 설정보다 약 1.30배에 가까운 처리량을 내면서 모든 지연 시간 목표를 맞췄다는 겁니다.", "evidence": "In configuration search over four serving scenarios, NoeVera comes within 5% of the optimum in a median of 6-7 simulator calls, versus 9 for Bayesian optimization and 15 for a knowledge-free agent with the same tools; on A100 GPUs, its representative configurations deliver ~1.30x vLLM-default throughput and meet every scenario's latency objective."}, {"subtitle": "벤치마크 점수와 비교", "desc": "72개 과제 벤치마크 중 남겨둔 48개 과제에서 노에베라는 다른 에이전트보다 29% 더 높은 점수를 받았는데요, 단일 호출 검색 방식과 비교하면 36% 더 높았다는 거예요. 쉽게 말하면, 지식이 스스로 진화하는 구조 덕분에 똑같은 프롬프트를 다른 기본 모델에 줘도 우위가 통계적으로 유의미하게 남는다고 보입니다.", "evidence": "On the held-out 48-task split of a 72-task benchmark, NoeVera scores 29% higher than an equally equipped agent and 36% higher than its single-call retrieval counterpart (0.80 vs. 0.62 and 0.59), and even when baselines receive NoeVera's own prompts, a statistically significant part of its evidence-evolution advantage remains."}], "easy1_evidence": "The harder problem is deciding what to investigate: which mechanisms matter for a workload, which configurations are worth testing, and what evidence a decision still needs.", "easy2_evidence": "In this work, we present NoeVera, an agentic Second Brain that goes beyond just one-shot retrieval by turning papers, code, benchmarks, and experimental results into a persistent, provenance-preserving knowledge base with three planes: source evidence, reusable synthesis, and agent memory.", "topic_evidence": "In this work, we present NoeVera, an agentic Second Brain that goes beyond just one-shot retrieval by turning papers, code, benchmarks, and experimental results into a persistent, provenance-preserving knowledge base with three planes: source evidence, reusable synthesis, and agent memory.", "limit_evidence": "When reused, provenance-preserving evidence records over-generalize on only 8% of applicability traps, versus 28% for a general-purpose agent memory."}, "2611.29154": {"points": [{"subtitle": "역할 분리 설계", "desc": "영상별로 개별 관찰을 맡는 LocalAgent와 전체 조율을 맡는 GlobalAgent를 나누어, 각 에이전트가 자신만의 관찰 기록을 유지하도록 만들었습니다. 뭔 소리냐면, 하나의 장치가 모든 걸 감당하지 않고 일을 쪼개서 처리한다는 말이에요.", "evidence": "Each LocalAgent plans observations of its own video and keeps a private observation history."}, {"subtitle": "성능 향상 결과", "desc": "CVBench와 MVU-Eval, CrossVid 등 세 가지 데이터셋에서 Qwen3.5와 GPT-6-sol 모델을 활용해 성능을 시험해 봤는데요. Qwen3.5를 기준으로는 기존 단일 추론 방식보다 5.1점, 가장 강력했던 기존 에이전트보다는 5.0점 높은 점수를 기록했습니다.", "evidence": "With Qwen3.5, our framework improves aggregate benchmark scores by 5.1 points on average over Single-pass inference with the same model and by 5.0 points over the strongest prior agent using the same model."}, {"subtitle": "속도 개선", "desc": "성능이 좋아졌을 뿐만 아니라, 비슷한 크기를 가진 기존 에이전트들과 비교했을 때 같은 하드웨어 환경에서 1.8배에서 2.7배 더 빠른 속도로 실행되는 모습을 보였습니다. 쉽게 말하면, 똑똑해졌으면서도 일 처리가 훨씬 빨라졌다는 셈이에요.", "evidence": "On the same hardware, MVAgent also runs 1.8-2.7 times faster than prior agents of comparable size."}], "easy1_evidence": "Most existing agents make both kinds of decisions in one controller, whose context accumulates observations from every video.", "easy2_evidence": "We separate them in MVAgent, a training-free Multi-Video Understanding Agent framework with one LocalAgent per video.", "topic_evidence": "We separate them in MVAgent, a training-free Multi-Video Understanding Agent framework with one LocalAgent per video.", "limit_evidence": ""}, "2611.29133": {"points": [{"subtitle": "정적 재시도 정책 분석", "desc": "성공하거나 시도 상한에 도달할 때까지 피드백 없이 처음 프롬프트와 작업 공간을 리셋하는 정적 정책을 살펴봤는데요, 태스크마다 성공 확률이 다를 때 뒤로 갈수록 더 어려운 태스크만 남게 된다는 거예요. 뭔 소리냐면, 쉬운 태스크는 일찍 끝나고 어려운 태스크만 남아 섞인다는 말이에요.", "evidence": "We study a static policy that stops at verified success or an attempt cap and otherwise resets the original prompt and workspace without passing feedback to the next request."}, {"subtitle": "비용 증가와 한계 비용", "desc": "완료당 비용은 원샷 서빙보다 최소한 같거나 높고, 추가 완료를 얻기 위한 한계 비용은 완료 증가가 있는 곳에서 줄어들지 않는다는 점을 증명했는데요, 평균 비용과 추가 완료에 드는 비용은 서로 다른 개념이라는 거예요. 쉽게 말하면, 전체를 나누어 평균 낸 비용과 늘어난 작업 하나를 잡는 비용은 다르다는 셈이에요.", "evidence": "Specializing classical survivor selection, we show that cost per completion is at least as high as in one-shot serving and that marginal cost per additional completion is nondecreasing wherever the completion increments are positive."}, {"subtitle": "실행 결과와 상한 선택", "desc": "OpenHands 설정으로 재플레이해 본 결과 1번 시도할 때 완료율 59.7퍼센트에서 4번일 때 70.0퍼센트로 오르며 비용도 약 USD 0.70에서 USD 1.32로 뛰었다고 하는데요, 결국 상한을 고를 때는 추가로 쓰는 비용과 그로 인해 얻는 완료의 가치를 저울질해야 한다는 겁니다.", "evidence": "For one OpenHands configuration, replay estimates completion of 59.7 percent with one attempt and 70.0 percent with four, while cost per completion rises from about USD 0.70 to USD 1.32."}], "easy1_evidence": "Retrying an agent after failure can complete more tasks while increasing the cost per completion.", "easy2_evidence": "For one OpenHands configuration, replay estimates completion of 59.7 percent with one attempt and 70.0 percent with four, while cost per completion rises from about USD 0.70 to USD 1.32.", "topic_evidence": "We study a static policy that stops at verified success or an attempt cap and otherwise resets the original prompt and workspace without passing feedback to the next request.", "limit_evidence": ""}, "2611.28972": {"points": [{"subtitle": "기존 방식의 한계", "desc": "기존의 시험 시간 훈련 방법들은 여러 번 샘플링을 거치느라 계산 비용이 너무 많이 들고, 편향된 자기 지도 신호 때문에 오류가 눈덩이처럼 불어날 위험이 있었는데요. 뭔 소리냐면, 쓰기에는 너무 무겁고 정확도도 불안정했다는 말이에요.", "evidence": "While Test-Time Training (TTT) offers a pathway for dynamic adaptation, existing approaches suffer from prohibitive computational overhead due to multiple sampling and the risk of error reinforcement from biased self-generated supervision."}, {"subtitle": "로테이션 기반 시험 시간 훈련(RoTTT)", "desc": "그래서 연구진은 입력 이미지의 회전 각도를 맞추는 방식으로 각 테스트 사례마다 가볍게 기울기를 업데이트하는 '로테이션 기반 시험 시간 훈련(RoTTT)'을 내놓았는데요. 따로 정답 레이블을 달지 않고도 이미 아는 회전 각도를 신호로 쓰기 때문에 추가 부담 없이 안정적인 적응이 가능하다는 겁니다.", "evidence": "For each test instance, RoTTT performs a small number of gradient updates by predicting the rotation angle of the input image."}, {"subtitle": "실험 결과와 의의", "desc": "여러 시각 언어 벤치마크에서 실험해 봤더니, RoTTT를 썼을 때 다양한 모델들의 성능이 꾸준히 좋아졌다는 걸 확인했다고 해요. 쉽게 말하면, 실시간으로 모델을 고치는 실용적이고 효율적인 길을 열었다는 셈이에요.", "evidence": "Extensive experiments across multiple vision-language benchmarks demonstrate that RoTTT consistently improves performance across different MLLMs, providing a practical and efficient paradigm for on-the-fly MLLM adaptation."}], "easy1_evidence": "Multimodal Large Language Models (MLLMs) achieve strong performance on vision-language tasks but often remain vulnerable to distribution shifts due to their fixed parameters during inference.", "easy2_evidence": "In light of this view, we propose RoTTT (Rotation-based Test-Time Training), a simple and efficient TTT approach that enables instance-specific refinement at inference time.", "topic_evidence": "In light of this view, we propose RoTTT (Rotation-based Test-Time Training), a simple and efficient TTT approach that enables instance-specific refinement at inference time.", "limit_evidence": ""}, "2611.28964": {"points": [{"subtitle": "후보 풀 생성과 전역 최적화", "desc": "처음부터 모델을 학습시키는 기존 방식과 달리, 여러 세밀도 수준에서 사전 학습된 네트워크를 가지치기해 후보 풀을 만들어 봤습니다. 학습이 없는 중요도 지표를 이용해 후보 선택을 전역 최적화 문제로 풀었다는 거예요. 뭔 소리냐면, 기존의 비효율적인 학습 과정을 건너뛰고 필요한 부분만 골라낸다는 말입니다.", "evidence": "Unlike conventional NAS methods that train each candidate from scratch, PruneNAS generates a candidate pool by pruning pretrained networks at multiple granularity levels and formulates the selection as a global optimization problem using training-free importance metrics."}, {"subtitle": "탐색 시간 단축과 성능", "desc": "엄격한 자원 제약 속에서 후보 구조를 빠르게 평가해 수백 시간에 달하던 GPU 탐색 시간을 단 몇 분으로 줄였다고 밝혔습니다. 표준 벤치마크 실험에서는 ResNet-50의 연산량(MACs)을 기존 방식의 절반 수준으로 줄이면서도 높은 정확도를 유지하는 구조를 찾아냈거든요. 쉽게 말하면, 시간과 계산 비용은 크게 아끼면서도 성능은 챙겼다는 겁니다.", "evidence": "Experiments on standard benchmarks demonstrate that PruneNAS discovers compact, high-accuracy architectures that nearly halve the computational cost (MACs) of prior methods on ResNet-50, while also showing strong generalization on object detection tasks with YOLO."}, {"subtitle": "방법론의 의의", "desc": "구조적 가지치기와 신경망 구조 탐색(NAS)을 서로 연결해 자원이 제한된 환경에서도 모델을 쓸 수 있는 실용적인 해법을 제시했다고 합니다. 객체 검출을 위한 YOLO에서도 강한 일반화 성능을 보여준다는 점을 확인했고요. 결국 자원 제약이 심한 현장에서 실제로 모델을 배포할 때 유용하게 쓰일 수 있다는 말이에요.", "evidence": "Our method bridges structured pruning and NAS, offering a practical solution for resource-constrained model deployment."}], "easy1_evidence": "Neural Architecture Search (NAS) has achieved state-of-the-art performance across diverse tasks, but its high computational cost remains a major barrier.", "easy2_evidence": "This approach enables rapid evaluation of candidate architectures under strict resource constraints, dramatically reducing search time from hundreds of GPU hours to mere minutes.", "topic_evidence": "Our method bridges structured pruning and NAS, offering a practical solution for resource-constrained model deployment.", "limit_evidence": ""}, "2611.28935": {"points": [{"subtitle": "경량화 구조 설계", "desc": "연구진은 다항식 혼합 레이어와 DyT 정규화를 가속기 친화적인 인과 메모리 블록과 합쳐서 구조를 만들었는데요. 셀프 어텐션을 대신해서 콤팩트한 인과 집계를 쓰도록 바꿨다는 말이에요. 뭔 소리냐면, 연산이 무거운 부분을 가볍게 바꿔서 엣지 기기에서도 돌아가게 만들었다는 겁니다.", "evidence": "STEdgeFormer combines polynomial mixture layers and DyT normalization with an accelerator-aware causal memory block, replacing pairwise self-attention with compact causal aggregation."}, {"subtitle": "TinyStories 성능 비교", "desc": "TinyStories에서 돌려봤더니 NPU를 지원하는 STEdgeFormer는 펄플렉시티 7.39에 지연 시간 40ms를 기록했는데요. 표준 4.12M 파라미터 설정은 펄플렉시티 6.79로 더 낮지만 CPU 폴백 때문에 지연 시간이 1450ms로 크게 늘어난다는 거예요. 바닐라 트랜스포머는 펄플렉시티 5.71이지만 하드웨어에 배포할 수가 없다는 단점이 있어요.", "evidence": "In comparison, the standard 4.12M-parameter configuration achieves a lower perplexity of 6.79 but requires CPU fallback for unsupported operators, resulting in 1450 ms latency."}, {"subtitle": "다운스트림 태스크 결과", "desc": "다운스트림 작업에서는 파라미터 1.39M개로 ECG5000에서 94%의 정확도를, Speech Commands에서 93%의 정확도를 기록했다고 해요. 이런 결과는 하드웨어를 고려한 선택과 연산자 호환성이 추론 지연 시간에 큰 영향을 준다는 걸 보여준다는 말이에요. 쉽게 말하면, 모델 크기나 정확도뿐만 아니라 실제 쓸 수 있는지가 중요하다는 겁니다.", "evidence": "On downstream tasks, STEdgeFormer achieves 94% accuracy on ECG5000 and 93% accuracy on Speech Commands with 1.39M parameters."}], "easy1_evidence": "Transformer-based sequence models have achieved strong performance in language and time-series modeling, but self-attention remains computationally and memory intensive for deployment on resource-constrained edge accelerators.", "easy2_evidence": "On TinyStories, the fully NPU-supported STEdgeFormer (MW) achieves a perplexity of 7.39 with 4.12M parameters and 6.51 MB RAM, with an end-to-end latency of 40 ms.", "topic_evidence": "We propose STEdgeFormer, a lightweight, hardware-aware sequence architecture designed for efficient execution on embedded neural accelerators.", "limit_evidence": "Rather than targeting state-of-the-art accuracy on individual benchmarks, STEdgeFormer is designed to provide a deployable sequence modeling architecture under the memory, computational, and operator constraints of embedded neural accelerators."}, "2611.28919": {"points": [{"subtitle": "결정 관련 잔차(DRR) 발견", "desc": "연구진은 후보 행동의 순서를 바꿀 수 있는 비용 오차의 일부인 결정 관련 잔차(DRR)를 찾아냈는데요, 훈련을 통해 DRR을 줄일수록 선택 능력이 더 좋아진다는 점을 확인했어요. 뭔 소리냐면, 기존의 예측 오차보다 DRR이 행동 순서를 고르는 것과 훨씬 더 강하게 이어진다는 말이에요.", "evidence": "We identify the Decision-Relevant Residual (DRR), the part of the cost error that can reorder candidates, and show that the more training reduces the DRR, the more it improves selection (Spearman \rho = 0.82, vs. 0.61 for prediction error)."}, {"subtitle": "의사결정 정렬 선택(DAS) 도입", "desc": "그래서 독립적으로 훈련된 여러 체크포인트의 표준화된 합의로 후보 점수를 매기는 의사결정 정렬 선택(DAS)이라는 방식을 도입했는데요, 이 플러그인 방식은 모델마다 다른 체크포인트별 잔차를 평균 내서 없애 준다는 겁니다. 쉽게 말하면, 여러 모델의 의견을 모아서 한 모델의 흔들림을 줄이는 셈이에요.", "evidence": "Building on this insight, we introduce Decision-Aligned Selection (DAS), a plug-in selection rule that scores candidates by the standardized consensus of several independently trained checkpoints, which averages out their checkpoint-specific residuals."}, {"subtitle": "다양한 과제에서의 성능 검증", "desc": "두 가지 모델 계열과 다섯 가지 과제에서 테스트해 봤더니, DAS는 단일 체크포인트보다 18개 설정 중 12개에서 더 나은 행동을 골랐고 모델을 세 배 더 오래 훈련시킨 경우보다도 14개에서 앞섰어요. 닫힌 고리(closed loop) 환경에서도 사전 등록된 LeWM 비교 9개 중 6개에서 성공률이 높아졌다는 것으로 보입니다.", "evidence": "Across two model families (LeWorldModel and DINO-WM) and five tasks, DAS selects better actions than single checkpoints in 12 of 18 configurations and outperforms training one model three times longer in 14 of 18."}], "easy1_evidence": "However, planning depends on how well a model ranks candidates, whereas training optimizes how accurately it predicts each one.", "easy2_evidence": "Building on this insight, we introduce Decision-Aligned Selection (DAS), a plug-in selection rule that scores candidates by the standardized consensus of several independently trained checkpoints, which averages out their checkpoint-specific residuals.", "topic_evidence": "We identify the Decision-Relevant Residual (DRR), the part of the cost error that can reorder candidates, and show that the more training reduces the DRR, the more it improves selection (Spearman \rho = 0.82, vs. 0.61 for prediction error).", "limit_evidence": ""}, "2611.28881": {"points": [{"subtitle": "데이터셋과 프레임워크 구성", "desc": "연구진은 기업 대출 모니터링 분야에서 프레임워크를 평가하려고 143개의 대출 약정과 2,527개의 질문이 담긴 벤치마크를 직접 만들었는데요. 이 벤치마크는 준법 감시, 수익 여유, 부채 상환 능력을 두루 다룬다는 겁니다. 뭔 소리냐면, 대출자가 빌릴 때 맺은 약정을 잘 지키고 있는지 실제로 따져볼 수 있는 시험대를 마련했다는 말이에요.", "evidence": "To evaluate our framework, we curate \bench{}, a benchmark containing 143 loan agreements and 2,527 questions covering compliance, earnings cushion, and debt capacity."}, {"subtitle": "7B 모델의 성능 결과", "desc": "실험을 해 봤더니, 7B 크기의 모델이 94.8퍼센트의 정확도를 기록하며 자신보다 열 배나 큰 오픈 LLM들을 앞질렀다고 하는데요. 세 가지 모델 계열 전체를 보면 정확도가 92.6에서 96.8퍼센트 사이에 걸친다는 겁니다. 쉽게 말하면, 덩치가 작아도 규칙 번역 방식을 잘 만나면 훨씬 큰 모델 못지않게 똑 부러지게 일할 수 있다는 거예요.", "evidence": "Our results show that a 7B formalizer achieves 94.89% accuracy, outperforming open LLMs up to ten times larger."}, {"subtitle": "오류 검출 능력", "desc": "다른 언어 모델들이 낸 금융 분석 오류를 찾아내는 작업도 해 봤는데요, 무려 95.6에서 99.7퍼센트에 이르는 오류를 잡아냈다는 겁니다. 연구진은 FormaFin과 새로 만든 벤치마크를 모두 공개했다고 밝혔는데요. 모델이 혼자 내놓은 답이 맞는지 틀렸는지 탄탄하게 걸러내는 도구로 쓸 수 있다는 셈이에요.", "evidence": "Our framework also detects 95.6 to 99.7% of errors in other LLMs' financial analyses."}], "easy1_evidence": "Formally verifying financial analyses generated by large language models (LLMs) remains challenging as financial rules are largely expressed in natural language and rarely have corresponding formal specifications.", "easy2_evidence": "We introduce FormaFin, a framework that trains small open language models to translate financial rules into reusable SMT formulas.", "topic_evidence": "We introduce FormaFin, a framework that trains small open language models to translate financial rules into reusable SMT formulas.", "limit_evidence": ""}, "2611.28846": {"points": [{"subtitle": "EA-Bench 도입", "desc": "연구진은 도구 호출 효율과 사용자 상호작용 효율을 함께 평가하려고 EA-Bench를 처음으로 선보였는데요, 뭔 소리냐면 누락되고 엇갈리는 정보 속에서 에이전트가 어떻게 움직이는지 체계적으로 보겠다는 말이에요. 기존 과제를 바탕으로 정보가 빠지거나 겹치게 만드는 조건들을 설계했다고 합니다.", "evidence": "To our knowledge, it is the first benchmark to jointly evaluate tool-call efficiency and user-interaction efficiency under controlled missing, redundant, and conflicting information."}, {"subtitle": "DAGs 기반 조건 설계", "desc": "작업 흐름을 방향성 비순환 그래프(DAGs)로 나타내서 노드 사이의 관계를 꼼꼼히 따져봤는데요, 정보가 빠질 곳이나 엇갈릴 곳을 찾아내서 검증 과정을 거쳤다는 겁니다. AI 검사와 전문가 검토를 거쳐 초기 후보 792개 가운데 조건 232개를 골라내고 이를 난이도에 따라 나누어 정리했어요.", "evidence": "We use a two-stage validation process combining AI-assisted checks with expert screening to select 232 conditions from 792 initial candidates."}, {"subtitle": "실험 결과와 한계점", "desc": "실험을 해 봤더니 불완전한 정보가 정확도를 떨어뜨리고 비용을 늘린다는 결과가 나왔는데요, 장점은 에이전트의 허점을 명확히 드러냈다는 데 있고, 단점은 일부 모델이 사용자 확인 없이 값을 짐작해서 맞춰버리는 신뢰성 문제가 그대로 드러났다는 점이에요.", "evidence": "Experiments show that imperfect information can reduce accuracy and increase tool-use and user-interaction costs."}], "easy1_evidence": "However, agents often encounter incomplete, distracting, or inconsistent information in practice.", "easy2_evidence": "More concerning, several models obtain apparently correct outcomes by guessing user-specific values without confirmation, revealing potential execution unreliability in current models under imperfect user information.", "topic_evidence": "To systematically study agent inefficiency under such imperfect information, we introduce Efficient Action (EA)-Bench, which evaluates both tool calls and user interactions in work-related tasks.", "limit_evidence": ""}, "2611.28827": {"points": [{"subtitle": "가설 선정과 자기 평가", "desc": "연구진은 100개의 열린 기하학 분석 가설 중 모델이 50% 이상 자신 있다고 고른 문제들을 대상으로 시험을 진행했는데요. 모델은 각 문제에 대해 자신이 성공할 확률을 숫자로 매겼다는 거예요. 13문제가 제외되면서 최종적으로는 87문제를 두고 실험이 이루어졌습니다.", "evidence": "13 questions were then excluded after an audit, and the model was asked to resolve the remaining 87 problems."}, {"subtitle": "과도한 자신감과 방향성", "desc": "모델이 말한 평균 성공 확률은 0.617이었지만 실제 정답률은 0.103에 불과해서, 스스로를 너무 믿었다는 점이 드러났는데요. 브리어 점수는 0.351이고 기대 보정 오차는 0.513으로 집계되었습니다. 숫자는 어긋났어도 풀 수 있는 문제를 더 높게 평가하는 경향은 남아 있어서 방향은 맞았다는 거예요.", "evidence": "Its mean stated resolution probability was $0.617$, versus an observed rate of $0.103$ (Brier score $0.351$, ECE $0.513$), thereby demonstrating that the model was systematically over-confident in its self-assessment."}, {"subtitle": "형식화 검증과 한계", "desc": "모든 증명은 Lean으로 형식화되어 올바른지 확인을 거쳤고, 의미 동등성 파이프라인도 통과했는데요. 다만 이번 결과는 탐색적 캠페인의 성과일 뿐 고정된 예산 속 성공 확률은 아니라는 점을 연구진이 밝혔습니다. 몇몇 문제에서는 기하학적 입력값을 가정하고 증명이 이루어졌다는 한계도 같이 있다는 거예요.", "evidence": "These are exploratory campaign outcomes, not fixed-budget success probabilities."}], "easy1_evidence": "By construction, the model first selected open problems in geometric analysis that it assessed that it had at least a 50\\% chance of proving or disproving, and then assigned a probability of success to each question.", "easy2_evidence": "The model was highly overconfident in probability magnitude but did more often than not assign a high probability of success to the problems that it did resolve, than the problems that it did not.", "topic_evidence": "How does confidence correlate with actual performance in large language models, when attacking open research-level math problems?", "limit_evidence": "These are exploratory campaign outcomes, not fixed-budget success probabilities."}, "2611.28748": {"points": [{"subtitle": "크렐트(CRELT) 분석 틀 도입", "desc": "연구진은 검색(retrieval), 대화 기록, 공격 전략을 팩토리얼 디자인(full-factorial design) 방식으로 나누고 타겟 개인정보가 아예 없는 검증된 검색 말뭉치를 써서 크렐트를 설계했는데요. 모델이 정보를 내뱉은 그 차례의 입력값에 해당 항목이 없을 때만 유출로 인정하는 엄격한 기준을 적용했다는 겁니다. 주요 실험에서는 이 기준 덕분에 입력값에 이미 들어있던 원시 일치 항목의 29퍼센트에서 53퍼센트까지 걸러낼 수 있었다고 해요.", "evidence": "CRELT separates retrieval, conversation history, and attack strategy through a full-factorial design, uses a retrieval corpus verified to contain none of the target PII, and counts an item as leaked only when it is absent from the model input at the turn it is produced."}, {"subtitle": "모델별 유출 경로와 문맥의 영향", "desc": "지피티제이식스비(GPT-J-6B), 피티아육점구비(Pythia-6.9B), 피티아십이비(Pythia-12B) 모델을 가지고 엔론 연락처를 겨냥해 실험해 봤더니, 검색 기능은 전체 기록이 있든 지워졌든 간에 정보 노출을 줄여주는 모습을 보였는데요. 무작위 구문을 넣은 길이 맞춤 통제 실험을 해봤더니 기록을 지웠을 때는 이 감소분의 91퍼센트에서 99.5퍼센트가, 기록이 있을 때는 47퍼센트에서 78퍼센트가 재현됐다는 겁니다. 뭔 소리냐면, 유출 감소의 상당 부분이 무엇을 검색해 왔기 때문이라기보다는 문맥이 늘어난 것 자체에서 온다는 말이에요.", "evidence": "Across GPT-J-6B, Pythia-6.9B, and Pythia-12B, targeting real Enron contact details, retrieval reduces disclosure under both full and cleared history, consistent with prior single-turn results."}, {"subtitle": "대화 기록 정책과 프라이버시 평가의 한계", "desc": "검색 기능을 켠 상태에서 전체 대화 기록을 유지하면 유출이 3.6배에서 4.9배까지 늘어나고, 대화 기록을 지우면 유출이 72퍼센트에서 79퍼센트까지 줄어들지만 완전히 사라지지는 않는다는 결과가 나왔는데요. 연구진은 이러한 결과가 한 번 대화만 보는 기존 보안 감사 방식이 대화형 시스템의 데이터 유출을 아주 낮게 잡아 칠 수 있음을 보여준다고 주장했다는 거예요. 쉽게 말하면, 기존의 단발성 평가만 믿고 대수롭지 않게 여겼다가는 다중 대화 속에서 개인정보가 줄줄 새는 위험을 놓치기 쉽다는 겁니다.", "evidence": "These results show that single-turn privacy audits can substantially underestimate training-data leakage in conversational RAG systems and that conversation-history policy is a critical dimension of privacy evaluation."}], "easy1_evidence": "Retrieval-augmented generation (RAG) is known to reduce training-data leakage in single-turn interactions, but whether this protection persists over multi-turn conversations is unclear.", "easy2_evidence": "With retrieval enabled, however, retaining full conversation history increases disclosure by a factor of 3.6-4.9, while retaining only one previous turn already restores disclosure to approximately the full-history level.", "topic_evidence": "These results show that single-turn privacy audits can substantially underestimate training-data leakage in conversational RAG systems and that conversation-history policy is a critical dimension of privacy evaluation.", "limit_evidence": ""}, "2611.28650": {"points": [{"subtitle": "정체성 가중치 찾기", "desc": "연구진은 모델이 자기 이름을 대게 만드는 질문을 만들고 그 답변으로 미세 조정(Fine-tuning)을 해서 가중치 중에 값이 큰 부분을 골라냈거든요. 뭔 소리냐면, 정체성이 박혀 있는 위치를 콕 집어냈다는 말이에요.", "evidence": "By generating probing questions designed to elicit self-naming outputs and fine-tuning the base model on these responses, the approach identifies and ablates high-magnitude weights within the parameter set."}, {"subtitle": "실험 결과 확인", "desc": "실험을 해 봤더니 정체성 관련 특성이 저순위 가중치(Low-rank weights)의 특정 구역에 모여 있었다고 하는데요. Qwen3.5-2B에서는 전부 지워졌고 Gemma4-E2B에서는 10퍼센트가 지워졌다는 겁니다.", "evidence": "Experimental results demonstrate that distilled identity traits reside within a localized subset of low-rank weights, achieving a complete removal rate in Qwen3.5-2B and a 10% rate in Gemma4-E2B while preserving general task capabilities."}, {"subtitle": "성능 유지와 결론", "desc": "이렇게 정체성 가중치를 없애도 전체 모델이 해야 하는 일들은 그대로 잘 유지된다고 밝혔거든요. 쉽게 말하면, 원래 성능은 건드리지 않고 이름표만 떼어낸 셈이에요.", "evidence": "These findings confirm that ablating top-tier adaptation weights suppresses distilled self-identification without compromising broader model performance."}], "easy1_evidence": "Large Language Models are trained on diverse corpora containing outputs from proprietary teacher models and provider-curated sources.", "easy2_evidence": "This study proposes a method to localize parameter-level representations of self-identity within low-rank adaptation modules to perform targeted weight ablation.", "topic_evidence": "This study proposes a method to localize parameter-level representations of self-identity within low-rank adaptation modules to perform targeted weight ablation.", "limit_evidence": ""}, "2611.28618": {"points": [{"subtitle": "대표 궤적 선택 프레임워크", "desc": "연구진은 기술-문맥 커버리지와 정렬된 시각-결정 유사도를 이용해 대표적인 궤적을 골라내는 프레임워크를 설계했어요. 뭔 소리냐면, 아무 데이터나 쓰는 게 아니라 학습에 꼭 필요한 알짜배기 상호작용 기록만 골라낸다는 말이에요.", "evidence": "Our framework selects representative trajectories using skill-context coverage and ordered visual-decision similarity."}, {"subtitle": "온정책 증류와 성능 향상", "desc": "온정책 증류(On-policy distillation)를 통해 신선한 상호작용이나 고정된 이력 속 학생의 응답을 학습시켰는데요, 네비게이션과 소코반 환경에서 네 개의 고정된 궤적만으로도 4B 학생 모델의 성공률이 각각 49.17%에서 82.08%, 60.16%에서 85.55%로 올랐다는 거예요. 쉽게 말하면, 27B 교사 모델 성능의 90% 이상을 회복했다는 겁니다.", "evidence": "On-policy distillation (OPD) learns through fresh interaction on selected tasks or fresh student responses at fixed histories."}, {"subtitle": "재생(Replay)을 통한 성능 유지", "desc": "독립적인 네비게이션 환경에서 재생(Replay) 기능을 썼더니 성공률이 45.83%에서 76.67%로 향상되었어요. 최적화 과정에서 새로운 상호작용을 추가하지 않고도 동일 작업에서 얻는 온라인 이득의 91.36%를 유지할 수 있다는 장점이 있습니다.", "evidence": "On an independent Navigation panel, replay improves success from 45.83% to 76.67%, retaining 91.36% of the same-task online gain without new interaction during optimization."}], "easy1_evidence": "How much interaction experience is needed to distill a capable visual agent?", "easy2_evidence": "Four fixed trajectories raise a 4B student's success from 49.17% to 82.08% on standard Navigation and from 60.16% to 85.55% on Sokoban, recovering over 90% of the measured gap to a 27B teacher on these panels.", "topic_evidence": "We study learning from few tasks and recorded interaction histories.", "limit_evidence": ""}, "2611.28617": {"points": [{"subtitle": "데이터셋 구성과 1·2단계 검증", "desc": "연구진이 만든 베릴래더(VeriLadder)는 엔지니어의 검증 방식을 본떠 5단계로 이루어져 있는데요, 1단계에서는 알티엘코더(RTLCoder)와 파이라넷(PyraNet) 등 두 개의 대형 베릴로그 코퍼스(Corpus, 말뭉치)에서 가져온 설계에 합성 결과와 실패 원인 등을 라벨링했습니다. 2단계에서는 명령어마다 4가지 사양 품질을 매겨서 낮은 점수가 나오면 나중에 회로를 다시 만들 때 실패할 확률이 높다는 것을 미리 예측할 수 있게 했다는 겁니다.", "evidence": "Level 1 labels designs from two large Verilog corpora, namely RTLCoder and PyraNet, with synthesis results, failure causes, critical warnings and post-synthesis metrics."}, {"subtitle": "3·4·5단계를 통한 사양 다듬기", "desc": "3단계에서는 각 명령어를 더 다듬어진 사양으로 고치고, 다른 모델 계열의 에이전트가 그 사양만 읽고 원본과 수학적으로 똑같은 회로를 만들 수 있을 때만 통과시켰습니다. 이렇게 했더니 다시 만들 수 있는 설계의 비율이 26.1%에서 78.2%로 높아졌다는 건데요, 4단계와 5단계에서는 검증된 변형 문장들과 사소한 행동 하나만 다른 어려운 오답 데이터(Hard negatives)를 추가해 데이터의 완성도를 더 높였다는 겁니다.", "evidence": "This raises the share of rebuildable designs from 26.1% to 78.2%, keeping every failed specification with its counterexample."}, {"subtitle": "실제 모델 성능 향상 결과", "desc": "연구진은 이 데이터셋을 통해 총 716,627개의 설계 합성 가능성을 라벨링했고, 11,247개의 정제된 사양과 수만 개의 변형 데이터를 제공했습니다. 이 데이터로 모델을 학습시켰더니 베릴로그이발(VerilogEval) v2와 알티엘엘엠(RTLLM) v2에서 기능 통과율이 각각 50.0%와 45.2%로 올랐다는 거예요. 쉽게 말하면, 검증된 대규모 데이터셋 덕분에 AI가 하드웨어 코드를 훨씬 더 정확하게 짤 수 있게 되었다는 셈입니다.", "evidence": "VeriLadder labels the synthesizability of 716,627 designs and, from RTLCoder, provides 11,247 refined specifications, 32,393 paraphrases and 8,397 one-fact variants."}], "easy1_evidence": "Training data is a bottleneck in AI, especially for large language models (LLMs) that write Verilog, because register-transfer-level (RTL) code is rarely published and existing datasets mostly check code for syntax, not instruction correctness.", "easy2_evidence": "Fine-tuning Qwen2.5-Coder-7B-Instruct on VeriLadder raises functional pass@1 from 31.7% to 50.0% on VerilogEval v2 and from 35.0% to 45.2% on RTLLM v2.", "topic_evidence": "This paper presents VeriLadder, a five-level Verilog dataset, and the multi-agent framework that builds it, in which LLM agents write and revise specifications, and EDA tools (a synthesizer and a formal equivalence checker) decide what is accepted.", "limit_evidence": ""}, "2611.28613": {"points": [{"subtitle": "FSMem 프레임워크 도입", "desc": "연구진은 훈련 데이터를 만들고 기억 형성을 연구하기 위해 유한 상태 기계 기반 기억 틀인 FSMem을 제안했는데요. 합성 세계, 고전적 계획, 코드 실행 등 여러 환경에서 규칙 재사용을 평가해 봤다는 겁니다. 뭔 소리냐면, 다양한 작업 환경을 통제된 상태로 만들어서 모델이 규칙을 어떻게 익히는지 정확히 뜯어보겠다는 말이에요.", "evidence": "We introduce FSMem (Finite-State Machine Memory), a state-transition framework for constructing training data and studying how data content and organization shape memory formation."}, {"subtitle": "데이터 다양성과 범위의 영향", "desc": "다양한 조건에서 실험을 해 봤더니, 행동 종류가 지나치게 많아지면 똑같은 규칙도 머릿속에 넣기 더 어려워진다고 하는데요. 반대로 상태와 행동을 커버하는 범위를 넓혀 주면 규칙 학습 전반에 도움이 된다는 걸 밝혔습니다. 쉽게 말하면, 데이터의 양뿐만 아니라 어떻게 조직되어 있는지가 모델 기억에 큰 영향을 준다는 셈이에요.", "evidence": "Under matched training conditions, even unchanged task rules become harder to internalize when learned alongside a larger variety of action types; by contrast, scaling the training data to provide broader state-action coverage generally improves rule learning."}, {"subtitle": "실행 깊이와 누적 코퍼스 효과", "desc": "특정 깊이에서만 훈련하면 그 길이에만 특화된 행동이 나타난다는 점을 찾아냈는데요. 이 결과를 바탕으로 짧은 경로와 긴 경로를 합친 누적 코퍼스를 만들어 봤더니, 긴 경로만 썼을 때보다 적은 토큰을 쓰고도 더 뛰어난 성능을 냈다는 겁니다. 다만 훈련과 테스트의 길이가 비슷할 때 모델이 가장 잘 작동한다는 제약도 함께 확인했다는 말이에요.", "evidence": "We further find that training at a single execution depth produces depth-specialized behavior, with models performing best when training and test executions have similar lengths."}], "easy1_evidence": "Yet how training data supports the internalization of reusable task rules remains unclear.", "easy2_evidence": "Together, these results demonstrate that the same task rules can be internalized differently depending on how execution experience is constructed, and that understanding these learning patterns can guide the design of more effective training data for parametric memory.", "topic_evidence": "We introduce FSMem (Finite-State Machine Memory), a state-transition framework for constructing training data and studying how data content and organization shape memory formation.", "limit_evidence": ""}, "2611.28574": {"points": [{"subtitle": "에보비엠의 작동 방식", "desc": "고정된 멀티모달 모델이 상호작용 경험을 바탕으로 기억과 기술을 담은 하나의 시각 프로그램을 만든다는 거예요. 프로그램이 직접 이미지를 보관하고 픽셀 기반으로 연산하며, 작업마다 증거를 어떻게 쓸지 결정한다는 말입니다.", "evidence": "The program retains images and computes directly on pixels, and its operations decide how this evidence is used in each task."}, {"subtitle": "메모리와 도구의 재귀적 진화", "desc": "모델이 자신의 시각적 궤적에서 실패한 원인을 찾아 증거를 놓치거나 잘못 쓴 연산을 수정한다는 거예요. 노트와 분석 도구까지 다시 쓰면서 이전 발견을 바탕으로 이미 실패한 변경 사항은 건너뛴다는 말입니다.", "evidence": "During memory evolution, the same model traces failures in its visual trajectories to the operations that lost or misused evidence and revises them."}, {"subtitle": "성능 평가 결과", "desc": "시각 매칭, 공간 기억, 순차적 결정 등 6가지 작업으로 3개 멀티모달 모델을 평가했는데요, 그 결과 에보비엠은 기존 최고 기준인 오토메름보다 보류된 에피소드에서 평균 점수가 31.3에서 47.6점까지 올랐다는 거예요. 초기 지침으로 한 번만 쓴 프로그램은 성능이 훨씬 낮아서 상호작용 경험이 중요함을 보여준다는 말입니다.", "evidence": "Across the six tasks, EvoViM improves the average score over AutoMem, the strongest baseline in the main comparison, by 31.3-47.6 points on held-out episodes."}], "easy1_evidence": "However, they still struggle when queries are deferred until after exploration, requiring them to retain visual evidence before knowing which details will matter.", "easy2_evidence": "We introduce EvoViM, a recursively self-evolving framework in which a frozen multimodal model turns its own interaction experience into one visual program for memory and skills.", "topic_evidence": "We introduce EvoViM, a recursively self-evolving framework in which a frozen multimodal model turns its own interaction experience into one visual program for memory and skills.", "limit_evidence": ""}, "2611.28565": {"points": [{"subtitle": "유연한 채점 기준과 통합 평가", "desc": "연구진은 모범 답안에서 채점 기준을 만든 뒤 기준을 살짝 완화해 학생들이 다른 길로 풀어도 감점되지 않게 했는데요, 질문 그룹 전체를 한 번에 모델에 넣어 학생의 앞선 선택을 기준으로 나중 답을 평가하도록 설계했어요. 뭔 소리냐면, 코드와 글은 물론이고 숫자와 그래프까지 여러 형태로 나온 결과물을 한꺼번에 살펴본다는 말이에요.", "evidence": "It generates a rubric from a reference solution, then applies a softening pass that relaxes criteria tied to the reference so legitimate alternative paths are not penalized."}, {"subtitle": "실제 수업 적용과 다양한 지표 검증", "desc": "이 도구를 실제 머신러닝 수업에 배포하고 기존에 사람이 채점해 둔 자료와 비교해 보았는데요, 사람 점수와 일치하는 정도부터 모델 간 차이, 비용, 학생들의 반응, 그리고 프롬프트 주입 공격을 얼마나 잘 막아내는지까지 함께 살펴봤어요. 쉽게 말하면, 실제 수업 환경에서 얼마나 믿고 쓸 수 있는지 다방면으로 확인해 본 셈이에요.", "evidence": "We deployed the tool in a machine-learning course, integrated with Gradescope, with a pre-submission format check and prompt-injection defenses, and evaluate it both in that live course and against archived submissions graded by staff in earlier terms."}, {"subtitle": "사람 점수와의 일치도와 안정성", "desc": "낮은 온도로 설정한 모델을 썼더니 사람이 매긴 점수와 꽤 강하게 일치하는 모습을 보였는데요, 연구진은 실행할 때마다 결과가 얼마나 안정적으로 유지되는지는 모델이 낮은 온도를 얼마나 잘 지원하느냐에 따라 크게 달라진다고 밝혔어요.", "evidence": "With low-temperature models, agreement with human scores is often strong, including on the open-ended items the design specifically targets, while run-to-run stability depends sharply on the model's temperature support."}], "easy1_evidence": "Jupyter notebooks support open-ended, multi-step assessments in which students build one logical flow across interdependent steps, combining code, written analysis, and generated outputs such as plots.", "easy2_evidence": "We present an LLM-based autograder for such flow-structured notebook questions.", "topic_evidence": "We present an LLM-based autograder for such flow-structured notebook questions.", "limit_evidence": ""}, "2611.28559": {"points": [{"subtitle": "동역학적 맥락의 부재", "desc": "원자 수준의 변화는 겉보기엔 비슷해도 주변 환경이나 거쳐온 역사에 따라 결과가 완전히 달라지는데요, 이 빠진 맥락이 커다란 정보 병목으로 작용했다는 거예요. 뭔 소리냐면, 순간적인 모습만 봐서는 앞으로 어떻게 망가질지 알 수 없다는 말이에요.", "evidence": "This context spans space and time: the future consequence of a local transition depends on its surrounding defect environment and the kinetic history leading to its current state."}, {"subtitle": "AtomWorld의 작동 방식", "desc": "그래서 연구진은 구조 관측값과 궤적 역사를 활용해 예측 가능한 동역학적 상태를 다시 짜 맞추는 AtomWorld를 제안했는데요, KMC 과정에서 허용된 변화만 다루기 때문에 물리적 규칙이 흔들리지 않는다는 거예요. 일시적인 흔들림을 걸러내고 실제로 구조를 바꾸는 경로만 정확히 짚어낸다는 셈이에요.", "evidence": "Learning operates only over transitions admitted by the underlying kinetic Monte Carlo (KMC) process, preserving event legality, state evolution, and physical time."}, {"subtitle": "성능과 적용 결과", "desc": "철(BCC Fe-Cu), 니켈 합금(FCC Ni-Cr-Al), 지르코늄(HCP Zr-H) 등 여러 재료에서 물리적 정확도를 지키며 영구적인 진화 과정을 일관되게 이끌어냈는데요, 특히 방사선을 맞은 원자로 압력용기 강재에서는 같은 예산 안에서 영구적 변화를 최대 420배까지 더 많이 이뤄냈다고 해요. 쉽게 말하면, 눈에 띄게 큰 규모와 긴 시간 동안 재료가 망가지는 과정을 들여다볼 수 있게 되었다는 겁니다.", "evidence": "In irradiated reactor-pressure-vessel steel, this approach achieves up to 420-fold greater persistent evolution under matched event budgets."}], "easy1_evidence": "Locally indistinguishable states can exhibit different event competition, escape times, and long-horizon outcomes, revealing missing kinetic context as a critical information bottleneck.", "easy2_evidence": "To solve this, AtomWorld reconstructs a predictive kinetic state from multiscale structural observations and trajectory history, distinguishing transient fluctuations from microscopic pathways that drive persistent structural evolution.", "topic_evidence": "Combined with scalable execution, it successfully extends mechanism-resolved trajectories to service-year timescales across metre-scale heterogeneous domains.", "limit_evidence": ""}, "2611.28532": {"points": [{"subtitle": "실내 지도 복원 방법", "desc": "연구진은 보행자 이동 경로와 공유기 위치, 보폭 크기를 함께 추정하고 경로들을 연결해 통로 배치를 복원해 봤는데요, 공유기 신호들이 서로 다른 로컬 좌표계의 걸음들을 잇고 거리 범위가 상대적인 기오메트리와 크기를 잡아준다는 말이에요. 뭔 소리냐면, 신호 측정값과 움직임 데이터를 조합해서 건물 안 구조를 저절로 그려내게 만든다는 겁니다.", "evidence": "Walks2Maps jointly estimates pedestrian trajectories, AP locations, and per-trajectory stride scales, then recovers the pathway layout from the reconstructed paths."}, {"subtitle": "사무실 층 테스트 결과", "desc": "30개의 공유기가 있는 사무실 층에서 11개 경로를 따라 수집한 22개의 스마트폰 궤적으로 성능을 확인해 봤는데요, 중앙값 기준으로 공유기 오차는 0.87m, 궤적 오차는 0.89m로 나왔고 걸어 다닌 면적의 F1 점수는 0.985로 나타났다는 겁니다. 쉽게 말하면, 별도의 측량 조사 없이도 아주 정확하게 실내 공간을 찾아냈다는 거예요.", "evidence": "On 22 phone trajectories collected along 11 routes on an office floor with 30 APs, Walks2Maps achieves median AP and trajectory errors of 0.87 m and 0.89 m, respectively, and a walked-area F1 score of 0.985."}, {"subtitle": "추가 실험과 성능 비교", "desc": "신호 유사도만 쓰면 장소는 알지만 지도가 일그러지는데, 와이파이 왕복 시간의 거리 정보를 살려야 이 왜곡이 해결된다고 해요. 비대칭 모델링을 적용했더니 대칭 손실을 썼을 때보다 공유기 오차가 54% 줄어드는 결과로 이어졌다는 겁니다.", "evidence": "Ablations show that radio similarity can recognize places while still producing a distorted map; retaining the metric information in RTT resolves this ambiguity."}], "easy1_evidence": "Everyday smartphone walks offer a scalable source of indoor geometry, but their motion traces drift and their radio measurements are distorted by multipath.", "easy2_evidence": "We present Walks2Maps, a physics-guided framework that reconstructs a shared metric map from Wi-Fi round-trip-time (RTT) and motion observations, without a floor plan, surveyed access-point (AP) coordinates, or position labels.", "topic_evidence": "We present Walks2Maps, a physics-guided framework that reconstructs a shared metric map from Wi-Fi round-trip-time (RTT) and motion observations, without a floor plan, surveyed access-point (AP) coordinates, or position labels.", "limit_evidence": ""}, "2611.28420": {"points": [{"subtitle": "기존 자기 개선 방식의 한계", "desc": "언어 모델이 스스로 프로그램을 고치는 반복적 자기 개선 방식은 기계 학습 과제에서 좋은 성과를 냈지만, 비싼 최첨단 모델과 많은 호출 횟수가 필수적이었다는 거예요. 뭔 소리냐면, 성능을 높이려면 돈과 자원이 너무 많이 든다는 말입니다.", "evidence": "Recursive self-improvement (RSI) loops, in which a language model repeatedly rewrites a program and builds on its previous version, now perform well in machine-learning tasks, but they rely on frontier models and hundreds of calls per run."}, {"subtitle": "DiVE 방법론의 세 가지 구성 요소", "desc": "연구진은 공유 기억 장치와 실패 기록, 그리고 최우수 아이디어 선정 단계라는 세 가지 요소를 바탕으로 작은 모델들이 같은 맥락에서 후보를 쓰고 최선의 결과를 매번 유지하도록 만들었는데요, 이를 통해 생성된 해결책의 창의성과 다양성을 끌어올렸다는 겁니다. 쉽게 말하면, 모델들이 서로 실패를 공유하며 더 나은 방향을 찾아가도록 판을 깔아 준 셈이에요.", "evidence": "DiVE uses three components: a shared memory, a failure log, and best-idea-wins rounds. This allows models to write candidate solutions from the same context and retain the best idea at each iteration."}, {"subtitle": "22개 경진대회에서의 성능 평가 결과", "desc": "22개의 MLE-bench Lite 경진대회에서 다섯 개의 8-12B 공개 가중치 모델을 묶어 시험해 봤더니, 평균 구성원보다 테스트 오차가 25.4% 줄었고 Llama 3.3 70B보다도 16.7% 줄어드는 결과를 보였습니다. Qwen 3.5 122B-A10B 비용의 75% 수준으로 그 모델 성능의 7.1% 이내까지 다가갔다는 거예요.", "evidence": "On 22 MLE-bench Lite competitions, an ensemble of five 8-12B open-weight models has 25.4% less test error than its average member and 16.7% less than Llama 3.3 70B, and comes within 7.1% of Qwen 3.5 122B-A10B at 75% of its cost."}], "easy1_evidence": "Small open-weight models are far cheaper, yet when used alone, their programs often crash and their improvements stall.", "easy2_evidence": "We propose DiVE (diverse models evolve), an ensemble method for RSI that aims to improve creativity and diversity of generated solutions.", "topic_evidence": "We propose DiVE (diverse models evolve), an ensemble method for RSI that aims to improve creativity and diversity of generated solutions.", "limit_evidence": ""}, "2611.28408": {"points": [{"subtitle": "실험 설계와 데이터 수집", "desc": "연구진은 100개의 명세서를 바탕으로 Claude Code와 Codex CLI라는 두 가지 도구를 사용해 보안 블록 유무에 따라 총 400개의 웹 앱을 만들었는데요. 정적 및 동적 분석 파이프라인을 돌려서 총 6,721개의 문제를 찾아내고 통계 모델로 분석했다고 해요.", "evidence": "Each of 100 frozen specifications was realized four times: two agentic tools (Claude Code, Codex CLI) crossed with two prompts sharing a byte-identical functional core, without (A) and with (B) the security block."}, {"subtitle": "보안 문제 감소와 의존성 증가", "desc": "보안 블록을 붙였을 때 앱당 문제 수는 3분의 1로 줄어들었고, 직접 짠 코드의 심각한 문제는 절반 가까이 떨어졌는데요. 하지만 외부 라이브러리를 쓰는 범위가 두 배로 늘어나면서 심각한 의존성 경고는 오히려 더 많이 나타났다는 겁니다.", "evidence": "The block cut findings per application by a third (incidence-rate ratio 0.65, 95% CI 0.60-0.71), equally through both tools, and roughly doubled the declared dependency surface, so variant-B applications carried more high-severity dependency advisories."}, {"subtitle": "연구진의 평가와 한계", "desc": "연구진은 보안 프롬프트를 쓰는 게 비용이 적게 들고 어디서나 쓸 수 있는 좋은 개선책이지만, 늘어난 의존성 범위를 따로 검사해야 한다는 부담이 따른다고 밝혔는데요. 뭔 소리냐면, 코드 자체는 안전해지지만 주변 도서관 같은 외부 요소를 더 꼼꼼히 살펴봐야 한다는 말이에요.", "evidence": "Security-focused prompting is therefore an inexpensive and portable improvement, but it enlarges the dependency surface that has to be audited against it, an effect of library selection rather than of the security requirements themselves."}], "easy1_evidence": "The block cut findings per application by a third (incidence-rate ratio 0.65, 95% CI 0.60-0.71), equally through both tools, and roughly doubled the declared dependency surface, so variant-B applications carried more high-severity dependency advisories.", "easy2_evidence": "Security-focused prompting is therefore an inexpensive and portable improvement, but it enlarges the dependency surface that has to be audited against it, an effect of library selection rather than of the security requirements themselves.", "topic_evidence": "This study asks whether appending a fixed block of OWASP-aligned security requirements to the prompt changes what such tools produce, by how much, and with what side effects.", "limit_evidence": ""}, "2611.28369": {"points": [{"subtitle": "인과적 월드 모델 설계", "desc": "연구진은 인과적 관점에서 데이터를 바라보는 월드 모델 환경을 새롭게 구축하고, 그 안에서 최적의 예측기가 어떻게 작동하는지 분석해 냈는데요. 뭔 소리냐면, 데이터에 숨겨진 진짜 인과 관계를 수학적으로 명확하게 정의했다는 말입니다.", "evidence": "We introduce a causal world-model setup, for which, we characterize the Bayes-optimal predictor under the causal view of the data."}, {"subtitle": "이론적 복원과 CausalNTP 제안", "desc": "오컴의 면도날(가장 단순한 가설이 진실일 확률이 높다는 원리)을 적용해 비인과적 데이터를 걸러내는 함수를 만들었더니 진짜 인과 예측기를 복원할 수 있다는 것을 증명했는데요. 이 이론적 설계를 바탕으로 트랜스포머가 인과적 토큰에만 의존하도록 훈련하는 실용적인 알고리즘인 CausalNTP를 만들어 냈다는 겁니다.", "evidence": "We then prove that, a function that distills its predictions to non-causal views of data, when realized under Occam's Razor, recovers the true causal predictor."}, {"subtitle": "분포 외 일반화 성능 검증", "desc": "월드 모델 환경에서 실험해 봤더니, 기존 NTP가 이론적 한계로 해내지 못했던 분포 외 일반화 성능을 CausalNTP가 데이터나 모델 크기와 상관없이 훌륭하게 달성해 냈다는 장점이 있는데요. 자연어 질의응답 환경에서도 똑같은 성능 향상과 행동 양상을 보여주었다고 밝혔습니다.", "evidence": "Empirically in the world-model setup, CausalNTP achieves out-of-distribution generalization that vanilla NTP cannot due to its theoretical limits, regardless of data and model scale."}], "easy1_evidence": "This paper shows that transformer networks trained with next-token prediction (NTP) and gradient descent do not learn to make predictions using only causally-relevant tokens in the left context, irrespective of the causal ordering of tokens during training, and identifies the learning deficiencies responsible.", "easy2_evidence": "Based on this analysis we propose CausalNTP, a practical training algorithm that approximates this theoretical recipe and trains transformers to depend only the causally relevant tokens in left-context.", "topic_evidence": "Based on this analysis we propose CausalNTP, a practical training algorithm that approximates this theoretical recipe and trains transformers to depend only the causally relevant tokens in left-context.", "limit_evidence": ""}, "2611.28356": {"points": [{"subtitle": "온라인 에이전트의 증거 선별", "desc": "온라인 에이전트는 의사결정이 필요한 시점에 맞춰 증거를 골라주는데요. 초기 안내(Initial Guidance)는 시작할 때 검증된 교훈을 공급하고, 세션 검색(Session Retrieval)은 가설을 만들기 전에 관련된 과거 세션을 찾아주며, 시험 후보 검토(Trial Candidate Review)는 각 후보를 과거의 유사한 시험과 대조해 확인한다는 거예요.", "evidence": "An online agent curates evidence at the decision points where it is needed: Initial Guidance supplies validated lessons at the start, Session Retrieval supplies related past sessions before each batch of hypotheses is generated, and Trial Candidate Review checks each trial candidate against matching past trials."}, {"subtitle": "오프라인 에이전트의 자체 개선", "desc": "세션 사이에는 오프라인 에이전트가 작동하는데요. 검증된 교훈을 요약하고 정제해서 메모리 시스템 자체가 스스로 발전할 수 있도록 만든다는 거예요.", "evidence": "Between sessions, an offline agent distills validated lessons, making the memory self-improving."}, {"subtitle": "성능 평가 결과", "desc": "두 가지 광고 모델에 적용해 성능을 확인해 봤는데요. 기억 장치가 없는 대조군이 32번의 시도로 도달한 결과를 엥그램은 47% 더 적은 시도로 도달했고, 평균적으로 더 나은 성능의 모델을 완성했다고 연구진은 밝혔어요. 쉽게 말하면, 과거 기억을 똑똑하게 불러다 썼더니 훨씬 적은 시행착오로 좋은 결과를 냈다는 겁니다.", "evidence": "On two ads models, Engram reaches the 32-trial result of a no-memory control with 47% fewer trials and also ends with a better model on average."}], "easy1_evidence": "Large language model (LLM) agents can now tune neural networks, yet without cross-session memory they spend costly trials rediscovering known lessons.", "easy2_evidence": "We present Engram, a memory system that links past trial outcomes with the hypotheses and rationale behind them and assesses whether this evidence applies to the current model.", "topic_evidence": "We present Engram, a memory system that links past trial outcomes with the hypotheses and rationale behind them and assesses whether this evidence applies to the current model.", "limit_evidence": ""}, "2611.28348": {"points": [{"subtitle": "의미 계약 기반 설정", "desc": "연구진은 막연하게 탐지기를 고르는 대신, 측정할 수 있는 시계열 성질을 바탕으로 목표 이벤트 패턴과 검증 질문을 담은 자연어 의미 계약을 세웠는데요. 뭔 소리냐면, 무엇을 찾을지 명확하게 정의하고 그에 맞춰 검증까지 하겠다는 말이에요.", "evidence": "Rather than selecting detectors against an implicit target, SMAD establishes a natural-language semantic contract grounded in measurable time-series properties, specifying target event patterns, expected score responses, and validation questions."}, {"subtitle": "합성 개입과 자기 정제", "desc": "이 계약을 바탕으로 LLM 에이전트들이 탐지 파이프라인을 제안하고, 라벨이 없는 상태에서도 대상 시계열에서 가져온 합성 개입 증거로 스스로 고쳐 간다는 건데요. 쉽게 말하면, 정답 라벨이 없어도 모델이 스스로 반복해서 성능을 다듬는다는 거예요.", "evidence": "This contract governs both detector construction and evaluation: LLM agents propose pipelines, while contract-matched synthetic interventions provide label-free evidence from the target series to assess semantic coverage and guide iterative self-refinement."}, {"subtitle": "앙상블과 성능 향상", "desc": "검증된 후보들을 모아서 앙상블을 만들고 어떤 탐지기가 기여했는지 근거를 남기도록 했는데요, 그 결과 단변량과 다변량 벤치마크에서 기존 최고 모델보다 성능이 각각 11.5%, 9.6% 높아졌다는 겁니다.", "evidence": "A semantics-aware ensemble integrates validated candidates and attributes each alert to contributing detectors and supporting evidence."}], "easy1_evidence": "More fundamentally, it selects how to detect anomalies without explicitly defining what to detect.", "easy2_evidence": "On univariate and multivariate TSAD benchmarks, SMAD improves detection performance over the strongest baseline by 11.5% and 9.6%, respectively, while outperforming general-purpose coding agents at 2-5x lower language-model token cost.", "topic_evidence": "We propose SMAD, an LLM-based multi-agent framework that translates anomaly intent into executable, testable detection pipelines.", "limit_evidence": ""}, "2611.28324": {"points": [{"subtitle": "MatHarness의 세 가지 작동 방식", "desc": "이 체계는 사전 비행 검증과 전문가 기술, 적시 감사를 통한 실행 안정성을 갖추고 있는데요, 여기에 영구적인 연구 산출물과 진화하는 과학적 사고 모델을 통한 지식 적응력, 그리고 사람이 목표를 관리하는 다중 인공지능 원탁회의를 통한 집단지성을 결합했다는 거예요. 뭔 소리냐면, 혼자서 연구를 진행하면서도 오류를 스스로 점검하고 발전할 수 있는 구조라는 말이지요.", "evidence": "MatHarness couples three mechanisms: execution robustness through pre-flight verification, expert-distilled skills, and just-in-time auditing; epistemic adaptability through persistent research artifacts and an evolving scientific mental model; and collective intelligence through a heterogeneous multi-agent round table under targeted human oversight."}, {"subtitle": "구리-아연 합금 표면 분리 현상 실험", "desc": "연구진은 메탄올 합성 촉매 분야의 미해결 과제인 구리-아연 합금(Cu-Zn alloys)의 흡착제 유도 표면 분리 현상을 통해 이 체계를 평가해 봤는데요, 대략 10의 3승 제곱에 이르는 그래픽 처리장치 시간(GPU-hours)을 소모하며 수 주에 걸친 궤적을 거쳤다는 거예요. 그 과정에서 시스템은 계획을 6번 수정하고, 실패한 계산에서 스스로 복사해 일어났으며, 독립적인 감사관이 스스로 과장한 주장을 바로잡기도 했다는 겁니다.", "evidence": "Over a multi-week trajectory consuming roughly 10^3 GPU-hours (50 production DFT relaxations prescreened by 171 machine-learning-potential evaluations) the system revised its plan six times, recovered autonomously from failed calculations, and had an independent auditor overturn one of its own over-attributed claims before publication."}, {"subtitle": "검증된 분석 결과와 논문 작성", "desc": "밀도범함수이론(DFT) 분석을 거친 결과, 면과 피복률에 따라 예외는 있지만 양쪽 조성 끝점에서 구리 표면 노출이 더 커지는 경향을 보였다는 거예요. 이러한 결과들은 사람이 명세와 승인, 전략적 방향 설정에 참여한 상태에서 완전한 논문 원고로 정리되었다는 말이지요.", "evidence": "Within the sampled metallic dilute-limit models, the validated DFT analysis supports an adsorbate-induced tendency toward greater surface Cu exposure at both composition endpoints, with facet- and coverage-dependent exceptions."}], "easy1_evidence": "Existing scientific agents, however, largely rely on specific task execution or predefined workflows, rendering them brittle in open-ended settings.", "easy2_evidence": "To bridge this gap, we present MatHarness, an agent harness designed for open-ended, long-horizon computational materials research spanning the complete lifecycle from initial ideation to manuscript writing.", "topic_evidence": "To bridge this gap, we present MatHarness, an agent harness designed for open-ended, long-horizon computational materials research spanning the complete lifecycle from initial ideation to manuscript writing.", "limit_evidence": ""}, "2611.28318": {"points": [{"subtitle": "비트 할당 규칙 비교", "desc": "연구진은 유전 알고리즘에서 이진 토너먼트 변형 방식과 얼터니스 영감을 받은 규칙을 비교하고 교차나 돌연변이가 없는 무작위 할당 기준선을 함께 검토했는데요. 모든 방식은 동일한 MLX 어핀 양자화기와 바이트 상한, 초기화 조건을 사용했다는 거예요. 뭔 소리냐면, 동일한 조건 아래서 어떤 부모 선택 규칙이 더 유리한지 공정하게 비교해 봤다는 말이에요.", "evidence": "A separate baseline samples repaired random allocations without crossover or mutation."}, {"subtitle": "텍스트 예측 성능 개선", "desc": "균등한 4비트 할당과 견주어 봤을 때, 토너먼트 방식은 AG News와 IMDb 데이터셋에서 다음 토큰 음의 로그 우도(NLL)를 각각 0.0616과 0.0152만큼 평균적으로 줄였는데요. 10개의 시드 모두에서 성능이 좋아지는 모습을 보였다는 겁니다. 대신 얼터니스 방식은 AG News에서 일부 시드만 개선하고 IMDb에서는 이득이 거의 없었으며, 무작위 방식은 균등 4비트와 차이가 없었다는 점도 같이 확인됐어요.", "evidence": "Against uniform four-bit, tournament reduces held-out next-token negative log-likelihood (NLL) by 0.0616 on AG News and 0.0152 on IMDb on average, improving all 10 seeds on each corpus at identical parameter storage."}, {"subtitle": "정확도와 예측의 차이", "desc": "토너먼트 대표 모델은 ARC-Challenge 질문 400개 중 156개를 맞춘 반면 균등 방식은 163개를 맞추어 과제 정확도 측면에서의 이득은 입증되지 않았는데요. 쉽게 말하면, 이번 결과는 압축률이나 과제 정확도가 아니라 테스트된 프로토콜 안에서 텍스트 예측 성능을 높이는 데 토너먼트 변형 방식이 더 낫다는 것을 보여준다는 겁니다.", "evidence": "The result favors this tournament variant for text prediction under the tested protocol, not for compression ratio or task accuracy."}], "easy1_evidence": "Can changing which matrices receive 2, 4, or 8 bits improve a small language model without increasing its parameter storage?", "easy2_evidence": "Against uniform four-bit, tournament reduces held-out next-token negative log-likelihood (NLL) by 0.0616 on AG News and 0.0152 on IMDb on average, improving all 10 seeds on each corpus at identical parameter storage.", "topic_evidence": "Can changing which matrices receive 2, 4, or 8 bits improve a small language model without increasing its parameter storage?", "limit_evidence": ""}, "2611.28293": {"points": [{"subtitle": "연구 질문과 방식", "desc": "연구진은 모델의 내부 파라미터를 고치지 않고도 과제별 피드백만으로 감정 일치도와 인지 분류 성능을 높일 수 있는지 살펴봤는데요. 보조 언어 모델을 써서 기존 모델의 대답과 감정 기준값 사이의 차이를 비교하며 프롬프트를 고치는 방식을 썼다는 겁니다. 뭔 소리냐면, 모델을 직접 재학습시키지 않고 대화 입력만 똑똑하게 다듬어 봤다는 말이에요.", "evidence": "A secondary language model has revised executor prompts using executor-output discrepancies against model-generated affective references for four dialogues and annotated Bloom labels for 70 learning outcomes; separate sets of 100 EduTalk conversations and 1,000 outcomes have supported held-out comparisons."}, {"subtitle": "성능 개선 결과", "desc": "그렇게 프롬프트를 고쳐 봤더니 감정 평균 절대 오차는 0.742에서 0.702로 줄었고, 생성 표준편차도 0.307에서 0.238로 낮아졌거든요. 블룸 분류 점수인 micro-F1은 0.687에서 0.893으로, 정확히 맞춘 비율은 0.418에서 0.636으로 올랐다는 겁니다. 쉽게 말하면, 프롬프트 다듬기만으로도 인공지능의 대답이 훨씬 안정되고 정확해졌다는 셈이에요.", "evidence": "Affective mean absolute error has decreased from 0.742 to 0.702 and mean generation standard deviation from 0.307 to 0.238, while Bloom micro-F1 has increased from 0.687 to 0.893 and exact-match subset accuracy from 0.418 to 0.636."}, {"subtitle": "연구의 가능성과 한계", "desc": "이러한 결과는 프롬프트 다듬기가 맞춤형 기술 교육을 개발하는 데 좋은 방법이 될 수 있음을 보여준다고 연구진은 밝혔는데요. 다만 작은 규모의 데이터로 다듬었다는 점과 실제 현장에서의 학습 효과는 아직 증명되지 않았다는 한계도 함께 언급했어요. 장점은 뚜렷하지만 실제 교육 현장에 쓰려면 앞으로 더 검증해 봐야 한다는 겁니다.", "evidence": "These findings have supported prompt refinement as a candidate approach for developing adaptive technical instruction, while its effects on workforce learning remain to be established."}], "easy1_evidence": "Industry 4.0 has increased demand for personalized technical education across interconnected computing and engineering domains, while prompt sensitivity and generation variability have complicated dependable interpretation of instructional dialogue and learning outcomes.", "easy2_evidence": "Affective mean absolute error has decreased from 0.742 to 0.702 and mean generation standard deviation from 0.307 to 0.238, while Bloom micro-F1 has increased from 0.687 to 0.893 and exact-match subset accuracy from 0.418 to 0.636.", "topic_evidence": "This study has shown that a shared prompt-refinement procedure, guided by distinct affective and cognitive feedback signals, can improve held-out reference agreement and multi-label classification while reducing affective-generation variability without executor parameter updates.", "limit_evidence": "Small refinement sets, unvalidated affective references, and absent learner-outcome measures have constrained interpretation."}, "2611.28202": {"points": [{"subtitle": "기존 하네스의 한계", "desc": "기존의 하네스는 모델 호출을 각각 최대 하나의 행동으로만 연결해서 에이전트가 모델의 생각 속도에만 맞춰 움직였다는 거예요. 뭔 소리냐면 시간이 멈추지 않는 실시간 게임에서는 에이전트가 빠르게 대응하기 어렵다는 말이에요.", "evidence": "Existing harnesses such as VISTA improve the first two, yet turn each model call into at most one action, so the agent acts only as often as its model thinks."}, {"subtitle": "AutoPILOT의 작동 방식", "desc": "연구진이 내놓은 AutoPILOT은 한 번의 모델 호출로 단일 행동, 열린 루프 매크로, 또는 화면을 보고 계속 플레이하는 닫힌 루프 제어기를 쓸 수 있게 바꿨어요. 이 덕분에 에이전트가 추가 호출 없이도 화면을 보며 실시간으로 게임을 이어갈 수 있게 된 셈이에요.", "evidence": "We introduce AutoPILOT, which changes the third: in each model call, the model can send a primitive action, start an open-loop macro, or write a closed-loop controller that keeps playing from the screen without further model calls until it hands control back."}, {"subtitle": "성능 평가 결과", "desc": "120개의 다양한 브라우저 게임으로 이뤄진 AFK-Bench에서 시험해 봤더니, AutoPILOT은 실시간 성공률 68.6%를 기록해 VISTA의 38.3%보다 훨씬 높았어요. 비용도 VISTA의 5분의 1만 들면서 비슷한 수준의 성공률을 냈다는 겁니다.", "evidence": "With GPT-6.1 Sol under the same budgets, AutoPILOT reaches 68.6% real-time success against 38.3% for VISTA, and on GameWorld it keeps 80.0% in real time while VISTA drops from 84.1% to 42.9%."}], "easy1_evidence": "Multimodal foundation models can play video games well when the game waits for them, but often fail when it keeps running.", "easy2_evidence": "We introduce AutoPILOT, which changes the third: in each model call, the model can send a primitive action, start an open-loop macro, or write a closed-loop controller that keeps playing from the screen without further model calls until it hands control back.", "topic_evidence": "Our results suggest that how a harness turns model outputs into actions over time is a central yet underexplored part of agent design, and we hope AutoPILOT and AFK-Bench will serve as a foundation for agents in a world that does not wait.", "limit_evidence": ""}, "2611.28197": {"points": [{"subtitle": "에이전트 3D 코딩 과제와 S2Bench", "desc": "연구진은 장면 수준의 스캔-투-빔(Scan-to-BIM)을 에이전트 기반 3차원 코딩 과제로 정의하고 S2Bench를 소개했는데요. 5개 분야의 실제 현장 128개에 대한 스캔과 전문가가 고른 기준 모델을 활용했다는 말이에요. 공통 프레임워크를 통해 에이전트가 파이썬으로 측정하고 캐드 커널에서 부품을 만들어 코드를 다듬는 겁니다.", "evidence": "We formulate scene-level Scan-to-BIM (Building Information Modeling) as an agentic 3D coding task and introduce S2Bench, comprising public and proprietary scans of 128 real-world scenes across five domains, paired with expert-curated reference models spanning diverse spatial scales."}, {"subtitle": "병렬 비동기 협업 방식 제안", "desc": "또한 주도 에이전트가 버전이 매겨진 작업을 나누어 맡기고 일꾼들이 실행하는 동안 계속 모델링을 하며 수정안을 통합하는 병렬 비동기 협업 방식을 제안했는데요. 5개의 에이전트와 협력 팀을 1,028번의 재구성 과정에서 평가해 봤다는 거예요. 스캔 잔차가 기하학적 수리를 직접 이끌지만 의미적 추론에는 어려움이 있다고 밝혔습니다.", "evidence": "We also propose parallel asynchronous collaboration, where a lead delegates versioned tasks, continues modeling while workers execute, and integrates revision-bound proposals."}, {"subtitle": "성능 평가 결과와 팀 협업 효과", "desc": "연구진은 최고 성능의 에이전트가 5센티미터 이내에서 96퍼센트의 커버리지를 보였지만 평균 교차 합집합(mIoU)은 63퍼센트에 그쳤고 모든 공학 검사를 통과한 비율은 38퍼센트를 넘지 못했다고 밝혔는데요. 규모가 커질수록 커버리지와 공학적 일치도가 떨어지지만, 더 작은 모델을 팀으로 운영하면 더 넓은 면적에서 세 가지 축 모두 나아진다는 장점이 있다고 봅니다.", "evidence": "Consequently, the leading agent fits scan geometry closely ($96\\%$ coverage within $5\\,\\text{cm}$) yet reaches only $63\\%$ mIoU, and no agent passes all engineering checks on more than $38\\%$ of scenes."}], "easy1_evidence": "Coding agents can translate 3D measurements into CAD geometry, but reconstructing engineering models for the built environment demands semantic interpretation and consistent construction constraints beyond surface fitting.", "easy2_evidence": "We also propose parallel asynchronous collaboration, where a lead delegates versioned tasks, continues modeling while workers execute, and integrates revision-bound proposals.", "topic_evidence": "We formulate scene-level Scan-to-BIM (Building Information Modeling) as an agentic 3D coding task and introduce S2Bench, comprising public and proprietary scans of 128 real-world scenes across five domains, paired with expert-curated reference models spanning diverse spatial scales.", "limit_evidence": ""}, "2611.28195": {"points": [{"subtitle": "파이토치 통합", "desc": "기존 라이브러리와 달리 오토마타를 텐서 버퍼로 다뤄서 파이토치의 메서드를 그대로 쓸 수 있게 만들었는데요, 모델을 장치로 옮기거나 상태를 저장하고 미니배치로 업데이트하는 과정이 자연스러워졌다는 겁니다. 뭔 소리냐면 기존의 복잡한 래퍼를 거치지 않고 파이토치 안에서 한 번에 굴릴 수 있다는 말이에요.", "evidence": "The automata are a tensor buffer, so a model moves with .to(device), is saved with state_dict() and learns from a mini-batch with one update(x,y) call."}, {"subtitle": "배치 단위 피드백", "desc": "오토마타 상태 변환을 이항 분포를 따르는 사건 횟수로 바꿔서 미니배치마다 한 번씩 반영하도록 구현했는데요, 이 핵심 기술 덕분에 기존 라이브러리들과 똑같은 정확도를 유지하면서도 연산을 크게 줄였다는 겁니다.", "evidence": "Its core technique is a batched formulation of Type I and Type II feedback, in which automaton transitions become event counts realised as binomial draws, with one commit per mini-batch."}, {"subtitle": "속도 개선 결과", "desc": "열 개의 벤치마크에서 실험해 봤더니 정확도는 떨어지지 않았는데요, 가장 작은 두 개를 뺀 나머지에서는 기존 파이토치테슬린머신쿠다(PyTsetlinMachineCUDA)보다 2.4배에서 10.9배, 티엠유(tmu)보다는 10.3배에서 81.2배나 더 빠르게 학습했다고 해요.", "evidence": "On ten benchmarks taken from the existing libraries, it matches their accuracy, and on all but the two smallest it trains 2.4-10.9X faster than PyTsetlinMachineCUDA and 10.3-81.2X faster than tmu on the same GPU."}], "easy1_evidence": "The software, however, consists of C and CUDA kernels behind scikit-learn-style wrappers that sit outside the deep learning ecosystem.", "easy2_evidence": "torchtsetlin implements the Tsetlin machine family as ordinary PyTorch modules: vanilla and weighted, coalesced, regression, convolutional over sequences, images and volumes, and dense per-pixel segmentation.", "topic_evidence": "torchtsetlin implements the Tsetlin machine family as ordinary PyTorch modules: vanilla and weighted, coalesced, regression, convolutional over sequences, images and volumes, and dense per-pixel segmentation.", "limit_evidence": ""}, "2611.27899": {"points": [{"subtitle": "거시 시스템(Tier 1)", "desc": "원격 측정 데이터를 활용해 파인튜닝된 인코더-디코더 언어 모델로 사용자 감정 회귀를 감지하도록 만들었는데요, 50만 개가 넘는 테스트 데이터에서 정밀도-재현율 곡선 아래 면적(PR-AUC)이 9.8% 향상되었다고 해요. 뭔 소리냐면, 실제 운영 환경에서 측정 지연을 몇 주에서 몇 시간으로 줄이고 설문 조사 비용도 40% 이상 아낄 수 있다는 말이에요.", "evidence": "Tier 1 (Macro System) acts as a scalable user sentiment regression detector, utilizing a fine-tuned encoder-decoder LLM (based on Gemini XS) on telemetry features."}, {"subtitle": "미시 시스템(Tier 2)", "desc": "다중 모달 대형 언어 모델을 써서 웹 결과 블록의 시각적 렌더링과 공간 배치를 직접 평가하도록 설계했는데요, 만족스러운 결과를 얻기까지 드는 노력을 '사용자 수고(User Toil)'라는 개념으로 정량화했다고 해요. 강화학습 기반의 프롬프트 최적화와 AI 심사위원을 더했더니 F1 점수가 6.5% 이상 좋아졌다는 겁니다.", "evidence": "Tier 2 (Micro System) provides granular diagnostics by employing a Multimodal LLM (Gemini 3.0 Pro) to natively assess visual renderings and spatial layout of web result blocks, quantifying \"User Toil\" as the estimated effort required to reach a satisfactory result."}, {"subtitle": "프레임워크의 활용", "desc": "이렇게 두 단계로 나뉜 구조를 통해 하루에 10만 건이 넘는 라이브 실험 쿼리를 처리하면서도 정확하고 진단 가능한 사용자 경험 평가가 가능해졌다고 밝혔는데요, 결과적으로 규모 확장성과 정밀함을 동시에 챙겼다는 거예요.", "evidence": "Ultimately, this framework enables scalable, accurate, and diagnostic UX attribution, processing O(100k) live experiment queries daily."}], "easy1_evidence": "Traditional surveys are slow and bottleneck rapid A/B testing, while automated metrics often lack the granularity to diagnose visual-spatial UX anomalies.", "easy2_evidence": "To address this, we introduce the Dual-Tier Sentiment Framework, a novel industrial architecture for automated UX attribution.", "topic_evidence": "To address this, we introduce the Dual-Tier Sentiment Framework, a novel industrial architecture for automated UX attribution.", "limit_evidence": ""}, "2611.27891": {"points": [{"subtitle": "불확실성의 분리", "desc": "목표 모델이 갈 길을 예측할 때는 모델의 예측값과 샘플링의 무작위성이라는 두 가지 불확실성이 섞여 있거든요. 그런데 전자와 달리 후자는 초안을 만들기 전에 미리 고정할 수 있다는 점에 주목했어요. 뭔 소리냐면, 두 불확실성의 성질이 달라서 따로 다룰 수 있다는 말이에요.", "evidence": "Yet the former requires a target-model forward pass, while the latter can be fixed before drafting."}, {"subtitle": "다이스(DICE)의 작동 방식", "desc": "그래서 연구진은 초안 생성과 검증 과정에서 무작위 요소를 미리 뽑아 서로 동기화하는 다이스(DICE)를 도입했는데요, 이를 기존 초안 생성기의 예측과 합쳐서 실제로 쓰일 가능성이 높은 쪽에 연산 자원을 집중시킨다는 거예요. 이 원리는 초안 트리를 만들 때 노드를 고르는 데 쓰이고, 다음 라운드 초안을 미리 불러오는 비동기 방식까지 이어지거든요.", "evidence": "This principle guides node selection throughout draft-tree construction and extends to asynchronous prefetching, where DICE predicts which next-round drafts to prepare."}, {"subtitle": "성능과 처리량", "desc": "초안 생성기를 따로 훈련시키거나 원래의 샘플링 분포를 바꾸지 않고도 여러 환경에서 최고 수준의 디코딩 처리량을 달성했다고 하는데요, 강력한 기존 기준 모델과 견주었을 때 속도가 최대 24.6pp까지 빨라진다고 주장했어요. 쉽게 말하면, 기존 구조를 크게 바꾸지 않고도 무작위성 관리만으로 속도를 크게 끌어올렸다는 셈이에요.", "evidence": "Without additional drafter training or changes to the target sampling distribution, DICE achieves state-of-the-art decoding throughput across diverse settings, with speedups of up to 24.6pp over strong baselines."}], "easy1_evidence": "Anticipating this path involves two sources of uncertainty: the target model's predictions and the randomness of sampling.", "easy2_evidence": "By combining these known draws with predictions from an existing drafter, DICE allocates computation toward continuations more likely to be used in the current sampling run.", "topic_evidence": "Building on this observation, we introduce DICE (Draw-Informed Candidate Selection), which pre-samples and synchronizes verification randomness across drafting and verification.", "limit_evidence": ""}, "2611.27839": {"points": [{"subtitle": "비대칭 역할 구조", "desc": "옹호자와 회의론자, 중재자에게 서로 다른 지침을 주어 역할을 나누었더니, 기존 대칭형 토론보다 역할 임베딩 유사도가 낮아졌고 쟁점이 되는 주장을 더 많이 찾아낼 수 있었다고 해요. 뭔 소리냐면, 서로 엇갈린 입장을 분명하게 세워야 편견 없는 검증이 가능하다는 말이에요.", "evidence": "First, we introduce an asymmetric role architecture comprising an Advocate, Skeptic, and Arbitrator with opposing epistemic directives, producing significantly lower role-embedding similarity (0.852 vs.\\ 0.918 for symmetric Multi-Agent Debate [MAD], $p = 5.82 \\times 10^{-8}$) and surfacing more contested claims (22.0\\% vs.\\ 15.4\\%)."}, {"subtitle": "신념-델타 수렴 기준", "desc": "증거를 바탕으로 토론을 멈출 시점을 판단하는 신념-델타 기준을 도입해 쓸데없는 반복을 없앴는데요. 그 결과 고정 3회 반복 방식에서 나타나던 과도한 반복을 없애면서도 대형 언어 모델 호출 횟수를 2.4배 줄였다고 해요.", "evidence": "Second, we propose the Belief-Delta (\\DB) convergence criterion, an evidence-grounded stopping rule that eliminates over-iteration (0.0\\% vs.\\ 62.5\\% for Fixed-$3$) while cutting LLM calls by 2.4$\\times$."}, {"subtitle": "문헌 기반 증거 연결", "desc": "지원되는 모든 주장을 독립적인 자연어 추론 분류기가 검증한 문헌 조각에 연결해 객관적인 증거 기반을 마련했어요. 환각 비율은 21.7%로 나타나 자기 정제 비평가 방식과 비슷하지만, 대신 감사할 수 있는 증거 기반을 제대로 갖추게 되었다는 겁니다.", "evidence": "Third, each supported claim is anchored to a verbatim literature snippet audited by an independent NLI classifier, achieving a 21.7\\% hallucination rate (comparable to 25.9\\% for a Self-Refine critic, $p = 0.61$) while establishing auditable evidence grounding."}], "easy1_evidence": "However, when debating agents are instantiated from the same underlying base model, they share identical latent representations, making self-critique bias structurally inevitable.", "easy2_evidence": "First, we introduce an asymmetric role architecture comprising an Advocate, Skeptic, and Arbitrator with opposing epistemic directives, producing significantly lower role-embedding similarity (0.852 vs.\\ 0.918 for symmetric Multi-Agent Debate [MAD], $p = 5.82 \\times 10^{-8}$) and surfacing more contested claims (22.0\\% vs.\\ 15.4\\%).", "topic_evidence": "We present \\sys{}, a multi-agent research verification framework that addresses both failure modes.", "limit_evidence": ""}, "2611.27778": {"points": [{"subtitle": "문헌 스크리닝과 인용 검증", "desc": "첫 번째 에이전트는 과학 문헌을 스크리닝해 양자 알고리즘과 어울리는 계산 커널 후보를 찾고 인용을 붙이는데요, 두 번째 에이전트는 그 인용을 독립적으로 검증하는 역할을 해요. 뭔 소리냐면, 후보를 찾는 단계와 그 근거가 맞는지 확인하는 단계를 나누어 정확도를 높이려 했다는 말이에요.", "evidence": "One agent screens scientific literature for computational kernels with a plausible quantum-algorithmic analogue and proposes candidates, each backed by citations."}, {"subtitle": "프로토타입 제작과 벤치마크", "desc": "검증을 통과한 후보에 대해 두 번째 에이전트는 원문의 계산 구조를 재구성하고 양자 매핑을 거쳐 프로토타입을 빌드한 뒤 고전 컴퓨터 방식과 비교해 봐요. 천체물리학 문헌에서 뽑은 10개 후보 가운데 9개가 소규모 벤치마크 프로토타입까지 완성되었다고 해요.", "evidence": "For candidates that survive verification, it reconstructs the source's computational structure, formulates a quantum mapping, builds and executes a prototype, and benchmarks it against classical baselines."}, {"subtitle": "실험 결과와 탐색적 한계", "desc": "조합 최적화, 확률론적 시뮬레이션, 베이지안 추론을 다룬 세 가지 사례를 자세히 살펴봤는데요, 테스트한 규모에서는 양자 우위를 달성하지 못했다고 해요. 연구진은 이 프레임워크가 출판된 아이디어를 실행 가능한 프로토타입으로 바꿔 과학자가 직접 검토하고 연구 지속 여부를 판단하도록 돕는 탐색적 도구라고 밝혔어요.", "evidence": "None of the three case studies achieved quantum advantage at the tested scales, and their astrophysical framing has not yet undergone expert validation."}], "easy1_evidence": "Identifying scientific computations that could benefit from quantum algorithms requires both domain knowledge and fluency in quantum algorithm design, expertise that rarely resides in one person.", "easy2_evidence": "We report results from QuASAR, an experimental, two-agent, LLM-driven pipeline intended to bridge this gap.", "topic_evidence": "We report results from QuASAR, an experimental, two-agent, LLM-driven pipeline intended to bridge this gap.", "limit_evidence": "None of the three case studies achieved quantum advantage at the tested scales, and their astrophysical framing has not yet undergone expert validation."}, "2611.27741": {"points": [{"subtitle": "기존 방식의 한계", "desc": "매번 행동을 할 때마다 시각 관측값을 모델에 보내는 상호작용 방식은 게임 루프가 모델 추론을 기다려야 하거든요. 뭔 소리냐면, 실시간 상호작용이 불가능해지고 반복적인 모델 호출로 인해 상당한 비용이 발생한다는 말이에요.", "evidence": "In practical deployment, this paradigm introduces two fundamental limitations: the game loop must wait for model inference, making real-time interaction impractical, and repeated VLM calls incur substantial cost."}, {"subtitle": "4단계 파이프라인 도입", "desc": "현재의 일반적인 시각-언어 모델을 더 쉽게 평가하기 위해 탐색, 인식, API 구축, 전략 조합이라는 네 단계 파이프라인을 함께 도입했는데요, 이를 통해 에이전트가 제어기 합성을 게임 탐색과 상태 인식 등으로 쪼개어 점진적으로 실행 가능한 프로그램을 만들 수 있게 지원한다는 겁니다.", "evidence": "To support more tractable evaluation for current general-purpose VLMs, we further introduce a four-stage pipeline --- Explore, Perception, API Construction, and Strategy Composition --- that decomposes controller synthesis into game exploration, state perception, interface construction, and strategic control, enabling agents to progressively construct an executable program."}, {"subtitle": "실험 결과와 의의", "desc": "4개 장르의 16개 게임으로 실험을 진행해 봤더니, 강력한 시각-언어 모델조차 이 벤치마크에서 고전하는 것으로 나타났거든요. 결국 수동적인 시각 이해와 실행 가능한 폐쇄 루프 게임 제어 사이에는 상당한 격차가 존재한다는 점을 밝혔다는 말이에요.", "evidence": "Experiments on 16 games spanning 4 genres show that even strong VLMs struggle on our benchmark, revealing a substantial gap between passive visual game understanding and executable closed-loop game control."}], "easy1_evidence": "However, most of them adopt a step-by-step interaction paradigm where the current visual observation is sent to the agent before each action.", "easy2_evidence": "Therefore, we propose PlayScriptBench, a script-based game benchmark that evaluates whether VLMs can synthesize an executable game-playing program from game states.", "topic_evidence": "Therefore, we propose PlayScriptBench, a script-based game benchmark that evaluates whether VLMs can synthesize an executable game-playing program from game states.", "limit_evidence": ""}, "2611.27712": {"points": [{"subtitle": "시각적 의존성 데이터셋 구축", "desc": "연구진은 번역할 때 이미지가 정말 필요한지를 세 가지 세밀한 라벨로 나누어 담은 시각적 의존성 데이터셋을 만들었는데요. 문장 안에서 뜻이 통하는 경우와 시각 정보가 꼭 필요한 경우를 구별할 수 있는 근거를 확인해 봤다는 겁니다. 뭔 소리냐면, 데이터에 기반해서 언제 이미지를 써야 할지 기준을 세웠다는 말이에요.", "evidence": "To support this formulation, we construct a visual-dependency dataset with three fine-grained labels (no_ambiguity, text_resolved, and vision_needed) and verify discriminative visual evidence for vision_needed instances."}, {"subtitle": "PreVIR 라우터 제안", "desc": "이미지 특징을 계산하기 전에 텍스트만 보고 경로를 골라주는 가벼운 구조의 PreVIR를 제안했는데요. 이 라우터는 어떤 백엔드에도 구애받지 않고 텍스트 기반 번역과 멀티모달 번역 중 하나를 선택해 줍니다. 쉽게 말하면, 연산 비용을 아끼기 위해 미리 길을 정해주는 문지기 같은 셈이에요.", "evidence": "We further propose PreVIR, a lightweight, backend-agnostic text-only router that selects between text-only and multimodal branches before computing visual features."}, {"subtitle": "영-중 번역 실험 결과", "desc": "영어에서 중국어로 번역하는 실험을 해봤더니, PreVIR은 기존의 여러 라우팅 방식들과 비교해서 아주 유리한 성능과 예산의 균형을 보여줬는데요. 항상 켜둔 멀티모달 방식만큼 번역 질을 유지하면서도 이미지 호출 횟수를 크게 줄였다고 해요. 라벨별 분석을 해봤더니 진짜 시각적 의존성과 문맥으로 해결된 모호함을 제대로 구별해 낸 결과로 보인다는 겁니다.", "evidence": "Experiments on English-to-Chinese MMT demonstrate that PreVIR achieves a favorable COMET-budget trade-off relative to strong routing baselines."}], "easy1_evidence": "However, prevailing systems either process images unconditionally or apply gating only after visual encoding, leaving redundant visual computation unavoidable.", "easy2_evidence": "We further propose PreVIR, a lightweight, backend-agnostic text-only router that selects between text-only and multimodal branches before computing visual features.", "topic_evidence": "We therefore formulate visual invocation as source-text sufficiency prediction: determining exclusively from the source text whether translation-relevant uncertainty remains unresolved.", "limit_evidence": ""}, "2611.27631": {"points": [{"subtitle": "에피스믹 타입스테이트의 개념", "desc": "에이전트의 타입을 프로토콜로 정의해 자신의 관측과 행동으로 가능한 세계들을 기록하고, 그 믿음의 모든 세계에서 안전한 행동만 허용하도록 했는데요, 에이전트들은 공공 타입 내에서 다른 에이전트가 무엇을 하든 통신 없이 자신의 타입 안에서 학습한다는 거예요. 뭔 소리냐면, 서로 대화하지 않아도 각자 정해진 규칙 안에서만 움직여서 위험한 상황을 원천 차단한다는 말이에요.", "evidence": "An agent's type is a protocol whose states record its beliefs, the worlds it cannot rule out from its own observations and actions, and permits only actions that are safe in every world of the belief, whatever the others do within their public types."}, {"subtitle": "증명과 구현 방식", "desc": "연구진은 타입 건전성과 팀 안전성을 증명하고, 세계가 무한할 때 가드로부터 타입을 구축하는 합성 방법을 제시했는데요, 모든 증명은 Rocq로 기계화되었다고 해요. 쉽게 말하면, 이론적으로 완벽하다는 것을 컴퓨터로 전부 확인했다는 셈이에요.", "evidence": "We prove type soundness and team safety, give a synthesis that is sound and complete, build types from guards when worlds are infinite, and show that shields are a special case."}, {"subtitle": "성능 평가 결과", "desc": "9개의 벤치마크에서 실험해 봤더니 타입이 적용된 학습자는 안전 위반이 0건이었고, 계약 기반 방법이 5개와 10개 에이전트에서 실패할 때 이 타입은 10개 에이전트용으로 1초 만에 만들어졌거든요. 반면 연속형 벤치마크에서는 라그랑주 학습자가 매번 수천 번의 위반을 냈다는 거예요.", "evidence": "Where a contract-based method fails at five and ten agents, types for ten agents are built in under a second."}], "easy1_evidence": "Type disciplines make programs safe by construction: components checked against each other's types compose into programs that cannot go wrong in the ways the types exclude.", "easy2_evidence": "On nine benchmarks, no typed learner causes a safety violation, and task performance does not differ significantly from that of two recent multi-agent shielding methods.", "topic_evidence": "We introduce epistemic typestates, a type discipline for safe multi-agent reinforcement learning.", "limit_evidence": ""}, "2611.27554": {"points": [{"subtitle": "반올림 노이즈 측정", "desc": "연구진은 유한 정밀도 연산 때문에 서빙 엔진의 실행 방식에 따라 반올림 노이즈가 다르게 나타난다는 것을 확인했어요. 4개의 추정 토큰을 한 번에 검증하면 150개의 프롬프트 중 60%가 달라지고 패딩을 넣으면 68%가 바뀐다는 거예요. 뭔 소리냐면, 사소한 실행 조건의 차이가 모델의 최종 출력에 큰 영향을 준다는 말이에요.", "evidence": "Verifying 4 guessed tokens per pass changes 60% of 150 prompts and padding changes 68%; every first divergence has a top-1 minus top-2 logit gap of 0.375 or less."}, {"subtitle": "마진 게이트와 캐시 재구축", "desc": "그래서 연구진이 로그잇 간격에 따른 마진 게이트를 적용해 봤지만 캐시를 읽는 방식으로는 결과를 바로잡기 어려웠는데요. 반면에 한 토큰 패스로 캐시를 다시 빌드하면 결과가 일치하게 되지만 토큰당 7.2번의 패스가 필요하다는 단점이 있거든요. 쉽게 말하면, 정확도를 높이려면 엄청난 연산 비용을 감수해야 한다는 셈이에요.", "evidence": "Rebuilding the cache with one-token passes leaves 0 of 100 different but costs 7.2 model passes per token, against 1.0 for the reference."}, {"subtitle": "고정 너비 디코딩의 효과", "desc": "대안으로 제시된 고정 너비 디코딩은 추정 방식과 일반 디코딩을 완전히 일치시키면서도 토큰당 0.75 패스로 효율성을 높였다고 밝혔어요. 138개의 추가 및 이동된 프롬프트 실험에서도 경계값은 0.6%의 위치에서만 초과되었고 반전은 0건으로 나타났다는 거예요.", "evidence": "Fixed-width decoding makes drafted and plain decoding identical (0 of 100 prompts differ) at 0.75 passes per token."}], "easy1_evidence": "We measure how often the greedy text of Qwen3-0.6B (bfloat16, 128 new tokens, GSM8K and ARC prompts) differs from a reference that decodes one token per pass.", "easy2_evidence": "Fixed-width decoding makes drafted and plain decoding identical (0 of 100 prompts differ) at 0.75 passes per token.", "topic_evidence": "Serving engines treat the ways of running a greedy language model as interchangeable: cached or not, padded or not, alone or batched, one token or several verified at once (speculative decoding).", "limit_evidence": "One GPU, one drafter, small models."}, "2611.27495": {"points": [{"subtitle": "안전 거부의 한계 발견", "desc": "연구진은 신뢰할 수 없는 데이터로 코드 언어 모델을 미세 조정했을 때 유해한 요청을 알아채고도 그대로 따르게 되는 문제를 살펴봤는데요, 내부 표현에 유해성 정보가 남아 있어도 처음의 거부 성향이 생성이 끝날 때까지 이어지지 않는다는 걸 확인했어요. 뭔 소리냐면, 위험하다는 걸 알면서도 생성 과정 속에서 거부를 일관되게 유지하지 못하는 간극이 있다는 말이에요.", "evidence": "Together, these findings reveal a critical gap between recognizing harmful requests and consistently refusing to fulfill them."}, {"subtitle": "세이프홀드 방어 프레임워크 도입", "desc": "그래서 거부를 단일 응답 결정이 아니라 지속적인 생성 과정으로 다루는 세이프홀드라는 새로운 방어 프레임워크를 도입했는데요, 결정 경계 고정으로 초기 생성 위치에서 응답 분포를 유지하고 거부 경로 강화로 전체 거부 시퀀스를 감독하는 방식이에요. 이렇게 하면 위험한 미세 조정 과정에서도 안전성을 유지할 수 있다는 겁니다.", "evidence": "Specifically, SAFEHOLD preserves the aligned model's full-vocabulary response distribution at the initial generation position through decision-boundary anchoring, while supervising the complete refusal sequence through refusal-path reinforcement."}, {"subtitle": "실험을 통한 성능 입증", "desc": "다양한 실험을 해 보았더니 세이프홀드는 방어하지 않은 미세 조정한 모델에 비해 평균 공격 성공률을 72.03%포인트 낮추고 다섯 가지 최첨단 방어 기술보다 24.32에서 70.87%포인트 더 뛰어난 결과를 보였다고 해요. 쉽게 말하면, 유용한 작업 성능은 평균 10.24%포인트 높이면서도 과도한 거부율은 평균 2.73%로 낮게 유지했다고 볼 수 있습니다.", "evidence": "SAFEHOLD reduces average ASR by 72.03 percentage points relative to undefended fine-tuning, outperforming five SOTA defenses by 24.32 to 70.87 percentage points."}], "easy1_evidence": "However, training on untrusted data can severely undermine their ability to refuse harmful requests.", "easy2_evidence": "To address this gap, we introduce SAFEHOLD, a novel provider-enforced defense framework that preserves safety alignment during harmful fine-tuning by treating refusal as a sustained generation process rather than a single response decision.", "topic_evidence": "To address this gap, we introduce SAFEHOLD, a novel provider-enforced defense framework that preserves safety alignment during harmful fine-tuning by treating refusal as a sustained generation process rather than a single response decision.", "limit_evidence": ""}, "2611.27483": {"points": [{"subtitle": "멀티 에이전트 자동 생성", "desc": "연구진은 오픈소스 대형 언어 모델인 큐원(Qwen 3.6, 27B) 기반의 멀티 에이전트 프레임워크를 활용해 제조 공정 로그로부터 실행 가능한 파이썬(SimPy) 모델을 만들어 봤다는 거예요. 도구를 활용하는 추론과 사람이 직접 검증하는 방식을 섞어서 전체 과정을 자동화했어요.", "evidence": "We introduce GenAI4SimPy, a multi-agent framework powered by Qwen 3.6 (27B), an open-weight large language model, that automates end-to-end DES generation from manufacturing event logs to executable SimPy models through tool-augmented reasoning and human-in-the-loop validation."}, {"subtitle": "성능 평가와 정확도", "desc": "공개된 스마트 공장 데이터셋의 세 가지 실행 블록으로 평가해 봤더니, 평균 절대 오차 비율은 7.9%로 나왔다는 건데요. 세 블록 모두에서 실패율을 잘 맞춰냈고, 처리량은 세 개 중 두 개 블록에서 맞췄다는 말이에요.", "evidence": "Evaluated on three execution blocks from a public smart factory dataset, the framework achieved a mean absolute percentage error of 7.9\\% and coverage of failure rate for all three blocks and of throughput for two of three."}, {"subtitle": "충실도 역설 발견", "desc": "공정 단위의 파라미터가 정확하다고 해서 시스템 전체의 행동까지 완전히 똑같아지지는 않는다는 충실도 역설이 관찰됐는데요. 처리 시간이나 처리량의 오차는 관찰 창을 잘못 잘라내거나 시스템 전체를 보정하지 않아서 생겼다는 거예요.", "evidence": "A fidelity paradox was observed: accurate process-level parameters did not ensure system-level behavioral fidelity, with flow-time and throughput errors driven by misinterpreted observation-window truncation and absent system-level calibration."}], "easy1_evidence": "High expertise and cost barriers exclude small and medium-sized enterprises from discrete-event simulation (DES).", "easy2_evidence": "Evaluated on three execution blocks from a public smart factory dataset, the framework achieved a mean absolute percentage error of 7.9\\% and coverage of failure rate for all three blocks and of throughput for two of three.", "topic_evidence": "We introduce GenAI4SimPy, a multi-agent framework powered by Qwen 3.6 (27B), an open-weight large language model, that automates end-to-end DES generation from manufacturing event logs to executable SimPy models through tool-augmented reasoning and human-in-the-loop validation.", "limit_evidence": "These results demonstrate that local open-weight models can perform DES generation at accuracy comparable to cloud-based alternatives, while identifying parameter extraction as necessary but insufficient for behavioral validity."}, "2611.27401": {"points": [{"subtitle": "선형 해독 가능성 차이 발견", "desc": "연구진이 지시를 안 따르는 모델과 잘 따르는 모델을 비교해 봤더니, 둘 다 목표 정보를 품고 있는데도 말을 잘 듣는 쪽에서 그 정보가 훨씬 더 선형적으로 쉽게 읽힌다는 것을 찾아냈어요. 뭔 소리냐면, 정보를 갖고 있는 것과 그것을 행동으로 꺼내 쓰는 것은 다르다는 말이에요.", "evidence": "By comparing NF WAM with its instruction-following (IF) counterpart, we find that target information is substantially more linearly decodable in IF WAMs, despite being encoded in both."}, {"subtitle": "LDS 적용 결과와 성능 향상", "desc": "그래서 목표 정보가 잘 읽히도록 만드는 LDS라는 보조 훈련 방법을 써 봤더니, LIBERO-CF 환경에서 성공률 74.6%, 접지율 89.2%를 기록하여 가장 강력한 기존 모델보다 각각 26.8%포인트, 42.9%포인트 더 높게 나타났다고 해요. 쉽게 말하면, 새로운 훈련 목표 하나로 조작 능력이 크게 좋아진 겁니다.", "evidence": "On LIBERO-CF, InternW0-$\triangle$ with LDS achieves a success rate of 74.6% and a grounding rate of 89.2%, surpassing the strongest baseline by 26.8 and 42.9 percentage points, respectively."}, {"subtitle": "사전 지시 경쟁 메커니즘 제안", "desc": "이런 결과가 나온 까닭을 설명하려고 연구진은 사전 신호와 지시 신호가 서로 부딪치는 경쟁 메커니즘을 제안했는데요, 말을 안 듣는 행동은 기존의 사전 신호가 세서 생기고 말을 잘 듣는 행동은 지시 신호가 셀 때 생긴다고 봤다는 거예요. 훈련 없이 해보는 두 가지 개입 방식으로 이에 대한 인과적 증거도 보여 줬다고 합니다.", "evidence": "To reconcile this apparent contradiction, we propose a prior-instruction competition mechanism, which explains NF and IF behavior as arising from the dominance of prior and instruction signals, respectively."}], "easy1_evidence": "Prior work shows that non-following (NF) WAMs encode information about the instructed target, but this information does not control their behavior.", "easy2_evidence": "Motivated by this observation, we introduce linear decodability supervision (LDS), a simple yet effective auxiliary training objective that promotes the linear decodability of the instructed target information.", "topic_evidence": "World action models (WAMs) exhibit strong manipulation capabilities yet often fail to follow test-time language instructions.", "limit_evidence": ""}, "2611.27349": {"points": [{"subtitle": "EcomWriteBench 구축", "desc": "연구진은 13개 카테고리와 5개 언어에 걸쳐 69개 전자상거래 글쓰기 과제에서 3,861개의 실제 쿼리를 모아 EcomWriteBench를 만들었는데요, 과제 수준의 추출과 인간 피드백을 통한 다듬기를 거쳐 공유 능력 풀 37개를 세웠다는 겁니다. 뭔 소리냐면, 전자상거래 글쓰기에 필요한 세부 능력들을 체계적으로 분류했다는 말이에요.", "evidence": "We introduce EcomWriteBench, a real-world benchmark containing 3,861 queries from 69 e-commerce writing tasks across 13 categories and five languages."}, {"subtitle": "선호도 보정 가중치 학습 프레임워크", "desc": "사람의 쌍대 선호를 전역, 카테고리, 과제 수준의 가중치로 합쳐서 해석 가능한 채점 기준(scoring rubrics)으로 바꿔주는 프레임워크를 제안했는데요, 능력 발견과 선호도 보정 집계를 결합해 자동 평가를 수행할 수 있게 했다는 거예요. 이 방식은 EcomWriteBench뿐만 아니라 넓은 범위의 다른 벤치마크에도 쓰일 수 있다고 밝혔습니다.", "evidence": "This framework provides a reusable approach for translating human preferences into automated evaluation by combining ability discovery, ability-wise scoring, and preference-calibrated aggregation, and can potentially be applied to a broad range of benchmarks beyond EcomWriteBench."}, {"subtitle": "사람 선호도와의 일치율 결과", "desc": "제안한 채점 프레임워크를 보류된 쿼리에 적용해 봤더니 사람의 선호도와 88.96%의 일치율을 기록했다고 하는데요, 전통적인 LLM 심판 방식이 기록한 78.54%보다 훨씬 높았다는 겁니다. 쉽게 말하면, 사람이 직접 판단한 결과와 모델이 평가한 결과가 훨씬 잘 맞아떨어졌다는 셈이에요.", "evidence": "On held-out queries, our scoring framework achieves 88.96% agreement with human preferences, compared with 78.54% for conventional LLM-as-a-judge scoring."}], "easy1_evidence": "Evaluating these systems requires accounting for user needs, product evidence, structural constraints, and business requirements that are not fully captured by general-purpose writing benchmarks.", "easy2_evidence": "On held-out queries, our scoring framework achieves 88.96% agreement with human preferences, compared with 78.54% for conventional LLM-as-a-judge scoring.", "topic_evidence": "We introduce EcomWriteBench, a real-world benchmark containing 3,861 queries from 69 e-commerce writing tasks across 13 categories and five languages.", "limit_evidence": ""}, "2611.27306": {"points": [{"subtitle": "감마 스케이프 플랫폼 소개", "desc": "연구진이 내놓은 감마 스케이프는 에이전트 중심의 시뮬레이션 및 벤치마크 플랫폼인데요, 로봇이 지속적인 물리 세계 안에서 내비게이션과 조작을 합쳐 복잡한 과제를 수행하게 만들어요. 뭔 소리냐면, 로봇이 도구를 써서 움직이고 그 결과를 다시 학습에 쓸 수 있는 가상 실험실이라는 말이에요.", "evidence": "We introduce $\\gamma$-Scape, an agent-centric simulation and benchmark platform for mobile embodied intelligence."}, {"subtitle": "벤치포지와 수집 장치의 역할", "desc": "벤치포지는 지침과 목표 평가기를 통해 물리적 과제 목표를 잡아 주면서도 에이전트가 다양한 해결책을 고르도록 허용하는데요, 여기에 에이전트 수집 장치까지 더해져 접촉이 많은 상호작용 시연을 만들어 낸답니다. 보조 기준 실행과 사람의 지도도 함께 경험을 채워 주는 역할을 해요.", "evidence": "BenchForge grounds structured objectives in physical task instances with instructions, reference programs, and goal evaluators, defining task goals while preserving agents' choice of valid solutions."}, {"subtitle": "실험과 평가 흐름", "desc": "이렇게 모인 도구 추적과 관측-행동 기록은 프로그램 개선과 정책 학습을 뒷받침하며 이후 평가에도 쓰이는데요, 연구진은 대표적인 에이전트 시스템을 시험해 접촉 수집과 프로그램 수정 과정을 선보였어요. 쉽게 말하면, 이 흐름들이 모여 로봇이 스스로 발전하는 재귀적 자기 개선 연구의 기초 체력이 된다는 겁니다.", "evidence": "Together, these workflows provide infrastructure for research on embodied recursive self-improvement."}], "easy1_evidence": "Studying these systems in mobile manipulation calls for physical worlds that connect agent-directed execution with its physical consequences and reusable interaction experience.", "easy2_evidence": "We introduce $\\gamma$-Scape, an agent-centric simulation and benchmark platform for mobile embodied intelligence.", "topic_evidence": "We introduce $\\gamma$-Scape, an agent-centric simulation and benchmark platform for mobile embodied intelligence.", "limit_evidence": ""}, "2611.27286": {"points": [{"subtitle": "능동적 믿음 상태 관리(PBM)", "desc": "연구진은 에이전트에게 폴드(fold) 도구를 쥐여 주어 긴 문맥을 압축된 믿음 상태로 만들고 다음 탐색을 위해 문맥을 초기화하도록 설계했는데요, 뭔 소리냐면 복잡한 정보 속에서 핵심만 추려내어 머릿속을 깨끗이 비운 뒤 다시 생각하게 만든다는 말이에요.", "evidence": "For the harness side, we propose Proactive Belief-State Management (PBM), equipping agents with a fold tool to compress lengthy context into compact belief states and reset the context for subsequent exploration."}, {"subtitle": "과정 중심 루브릭 보상과 훈련", "desc": "결과만 보지 않고 5차원의 결과 비공개 루브릭인 세이프(SEIPH)를 개발해 과정 품질에 대한 보상을 제공했는데요, 이를 바탕으로 35B 모델을 프록시 정책 최적화(PPO)와 군집 상대 정책 최적화(GRPO)로 후속 학습해 딥포캐스터-PPO와 딥포캐스터-GRPO를 완성했다는 겁니다.", "evidence": "For the training side, we develop SEIPH, a five-dimensional, outcome-blind rubric, providing process-quality rewards."}, {"subtitle": "성능 평가와 결과", "desc": "실험 결과 딥포캐스터-PPO(35B)가 포캐스트벤치와 폴리마켓심에서 가장 좋은 브라이어 점수를 기록하며 딥식-V4-프로(1.6T), 키미-K2.6(1T), GPT-5.5 기반의 에이전트들을 뛰어넘었다고 하는데요, 딥포캐스터-GRPO도 퓨처엑스(FutureX) 지표에서 2위를 차지했다고 밝혔습니다.", "evidence": "Empirically, DeepForecaster-PPO (35B) achieves the best Brier score on both ForecastBench and Polymarket-Sim, outperforming frontier agents based on DeepSeek-V4-Pro (1.6T), Kimi-K2.6 (1T), and GPT-5.5."}], "easy1_evidence": "This stems from two primary limitations: i) standard ReAct harness accumulates reasoning and evidence within one growing context, and ii) outcome-based rewards in forecasting lead to a slow and noisy signal that cannot distinguish sound reasoning from lucky guesses.", "easy2_evidence": "To address these, we introduce a forecasting training framework including harness design and post-training.", "topic_evidence": "To address these, we introduce a forecasting training framework including harness design and post-training.", "limit_evidence": ""}, "2611.27260": {"points": [{"subtitle": "계산적 경계 증명", "desc": "연구진은 언어 모델의 모든 유한 문자열이 출력될 수 있을 때, 모든 금지된 출력을 차단하고 허용된 출력을 통과시키는 가드는 정책이 결정 가능할 때만 존재한다는 것을 밝혔는데요, 결정 불가능한 정책에서는 모든 가드가 무수히 많은 문자열을 잘못 분류하게 된다는 거예요. 뭔 소리냐면, 수학적이고 계산적인 한계 때문에 정책이 풀 수 없는 문제라면 어떤 가드도 오류를 피할 수 없다는 말이에요.", "evidence": "If every finite string is a possible output of a language model, a computable guard that blocks every forbidden output and passes every permitted one exists if and only if the policy is decidable."}, {"subtitle": "가드와 실행 모니터의 구분", "desc": "산술적 진실이나 프로그램 행동, 유해 지시 등에 이 특성을 적용해 살펴봤는데요, 정확한 집행이 가능한 제한되고 가로채기 가능한 사례들을 가드와 실행 모니터로 구분해 확인했어요. 정확한 집행이 이루어진다고 해서 그 정책이 안전을 적절하게 포착했다는 뜻은 아니라는 점도 함께 짚었답니다.", "evidence": "We apply this characterization to arithmetic truth, program behavior, and harmful instructions to an idealized recipient."}, {"subtitle": "인간의 판단과 책임", "desc": "인간의 감독이 판단을 대신할 수는 없으며, 겉보기엔 통제자처럼 보이는 이도 검토를 멈춘 목적의 도구가 될 수 있다고 강조했는데요, 보수적인 제외 방식이 오히려 정책 자체의 결함을 알아채는 데 필요한 경고나 구제를 막을 수도 있다는 겁니다. 쉽게 말하면, 기계와 규칙, 정책 속에서 결함을 찾아내려는 지적이고 도덕적인 겸손함과 비판적 도전이 계속 이어져야 한다는 말이에요.", "evidence": "Human oversight cannot substitute for judgment: an apparent controller can become an instrument of purposes they have ceased to examine."}], "easy1_evidence": "Expecting guardrails to provide a general guarantee of safety fails to recognize the limits of computational enforcement and policy specification.", "easy2_evidence": "If every finite string is a possible output of a language model, a computable guard that blocks every forbidden output and passes every permitted one exists if and only if the policy is decidable.", "topic_evidence": "The impossibility of a general assurance of perfection is a condition responsible practice must confront, not a responsibility that another guardrail - or another guard - can remove.", "limit_evidence": ""}, "2611.27196": {"points": [{"subtitle": "EDAGoat의 두 가지 핵심 모드", "desc": "이 에이전트는 네 가지 교차 프로젝트 최적화 패턴으로 코드를 고치는 최적화 강화(OE) 모드와, 변경된 코드가 EDA 제약 조건을 어기지 않는지 시험하는 필수 검증(MV) 모드를 함께 쓰는데요. 뭔 소리냐면, 단순히 코드만 고치는 게 아니라 설계 규칙을 잘 지키는지 검증까지 확실하게 거친다는 말이에요.", "evidence": "Its optimization enhancement (OE) mode guides edits with four cross-project GPU optimization patterns."}, {"subtitle": "성능 평가 실험 결과", "desc": "연구진은 4개의 작업 부문과 55개 회로 입력을 포함하는 5개의 GPU EDA 프로젝트로 벤치마크를 진행해 전체 완료 실행 시간을 측정했는데요. 필수 검증(MV) 모드를 더했더니 딥식을 쓸 때 통과 횟수가 15번 중 13번으로 늘어났고, 기하 평균 속도 향상 배율도 1.11배에서 1.53배로 껑충 뛰었다는 겁니다.", "evidence": "Our benchmark covers five GPU EDA projects across four task families and 55 circuit inputs, measuring complete-solve runtime and verifying the resulting designs."}, {"subtitle": "GPT-6 Astra 적용 성과", "desc": "지피티-6 아스트라(GPT-6 Astra)를 붙였을 때는 15번의 검색을 모두 통과했으며, 모든 프로젝트에서 기존의 일반적인 프롬프트 방식보다 속도 향상 지표가 좋아졌는데요. 쉽게 말하면, 같은 기하 평균 속도 향상 배율이 1.26배에서 1.57배로 높아졌다는 걸 확인할 수 있었다고 해요.", "evidence": "With GPT-6 Astra, EDAGoat qualifies in all 15 searches and improves both speedup metrics over generic prompting on every project, lifting the same geometric mean from 1.26x to 1.57x."}], "easy1_evidence": "GPU acceleration has transformed electronic design automation (EDA), yet further improving expert-engineered GPU tools still demands substantial manual effort.", "easy2_evidence": "We introduce EDAGoat, to our knowledge the first EDA-aware GPU optimization agent for this task.", "topic_evidence": "We introduce EDAGoat, to our knowledge the first EDA-aware GPU optimization agent for this task.", "limit_evidence": ""}, "2611.27138": {"points": [{"subtitle": "등급별 의존 기준 마련", "desc": "연구진은 단일 보고서 신뢰도 0.65와 4가지 의존 수준을 가진 이진 세계를 만들어서 모든 세계에 정확한 사후 확률과 목표 위험을 부여했는데요. 뭔 소리냐면, 중복 계산 문제를 정확히 가격 매길 수 있는 기준점을 먼저 세웠다는 말이에요.", "evidence": "We build the graded-dependence exact reference: binary worlds with single-report reliability 0.65 and four dependence levels, whose disclosed parameters give every world an exact posterior and every rule a target risk."}, {"subtitle": "짝지은 이득 프로토콜 시험", "desc": "2,976개의 세계에서 4가지 설정을 바탕으로 기본 응답과 지시받은 응답을 점수 매겨서 모델들의 일치도와 이득을 살펴봤는데요. 예를 들어 claude-opus-5-5와 gpt-6.1-sol은 744개 중 744개에서 규칙과 0.001 이내로 일치했지만 지시 때문에 불일치가 0.044 늘어나기도 했다는 겁니다.", "evidence": "The paired gain protocol scores raw and instructed answers of four configurations on 2,976 worlds."}, {"subtitle": "사전 등록된 시험과 도입 판단", "desc": "사전 등록된 시험에서 원시 소스 가중치 대조는 양수였지만 그룹화 종점 차이는 감지되지 않았는데요. 이 기준을 통해 모델 호출 전에 규칙의 가치를 매기고, 라벨이 붙은 배포 항목에서 브리에 차이로 추정되는 짝지은 이득으로 도입 여부를 결정할 수 있다는 거예요.", "evidence": "The paired gain, estimable as a Brier difference on labelled deployment items, decides adoption per receiver and prompt condition."}], "easy1_evidence": "Language models fuse reports in retrieval, multi-agent consensus and agent memory, where treating shared-source reports as independent can double count evidence.", "easy2_evidence": "The paired gain protocol scores raw and instructed answers of four configurations on 2,976 worlds.", "topic_evidence": "We build the graded-dependence exact reference: binary worlds with single-report reliability 0.65 and four dependence levels, whose disclosed parameters give every world an exact posterior and every rule a target risk.", "limit_evidence": ""}, "2611.27133": {"points": [{"subtitle": "가치별 전문가 분리", "desc": "연구진은 먼저 감독 신호를 쪼개서 서로 다른 가치를 담당하는 전문가들을 독립된 매개변수 공간에서 따로 학습시켰다는 거예요. 뭔 소리냐면, 하나의 모델에 전부 우겨넣지 않고 가치마다 전담 부서를 따로 두어 충돌을 애초에 막겠다는 말이에요.", "evidence": "it first decomposes supervision into value-specific experts trained in isolated parameter subspaces"}, {"subtitle": "선호도 기반 가치 병합", "desc": "그렇게 따로 키운 전문가들을 선호도를 고려해 가치를 섞어 주는 병합 과정을 거쳤다는 거예요. 쉽게 말하면, 각 부서의 장점을 모으되 서로 부딪히지 않게 알맞은 비율로 섞어 내는 셈이에요.", "evidence": "then recomposes them via preference-aware value merging"}, {"subtitle": "경량 조율과 성능 검증", "desc": "마지막으로 합쳐진 모델을 전문가 앙상블과 맞추는 가벼운 조율 단계를 거쳤는데요, 다섯 개 평가 지표 평균에서 기존 방식들보다 더 좋은 결과를 냈다고 연구진은 밝혔어요.", "evidence": "and a lightweight harmonization stage that aligns the merged model with the expert ensemble."}], "easy1_evidence": "Existing preference optimization methods collapse these into a single implicit signal, and even multi-objective extensions optimize within a shared parameter space, leaving cross-value conflicts unresolved.", "easy2_evidence": "We propose MAPES, a multi-value alignment paradigm in which conflict resolution is a first-class concern at every pipeline stage: it first decomposes supervision into value-specific experts trained in isolated parameter subspaces, then recomposes them via preference-aware value merging and a lightweight harmonization stage that aligns the merged model with the expert ensemble.", "topic_evidence": "We propose MAPES, a multi-value alignment paradigm in which conflict resolution is a first-class concern at every pipeline stage: it first decomposes supervision into value-specific experts trained in isolated parameter subspaces, then recomposes them via preference-aware value merging and a lightweight harmonization stage that aligns the merged model with the expert ensemble.", "limit_evidence": ""}, "2611.27125": {"points": [{"subtitle": "어긋남의 순간 찾기", "desc": "교사가 주는 신호와 학생의 상태가 달라서 교정하지 못하는 구간을 먼저 짚어 봤는데요. 학생이 교사의 상위 p 집단에 얼마나 확률을 두는지 살펴보면 이 어긋남의 특성을 알 수 있다는 거예요. 뭔 소리냐면, 둘의 생각이 벌어지는 지점을 숫자로 가늠할 수 있다는 말이에요.", "evidence": "We first identify states where sampled-token OPD updates fail to correct teacher--student mismatch and characterize them using the student's mass on the teacher's top-$p$ set."}, {"subtitle": "기울기 왜곡과 학습 방해", "desc": "어긋난 상태에서는 교사에게서 배우기가 매우 힘들고, 이때 생기는 기울기 값이 다른 단어를 학습하는 데까지 나쁜 영향을 준다는 걸 확인했어요. 학습이 엉뚱한 방향으로 튀는 이유가 바로 여기에 있다는 거예요.", "evidence": "We then show that learning from the teacher is difficult at mismatched states and that their gradients can also affect with learning at other tokens."}, {"subtitle": "종료 토큰 불일치와 샘플링 왜곡", "desc": "문장이 끝나는 종료 토큰에서 어긋나는 경우를 구체적으로 파고들어 봤는데요. 잘못된 상태에서 계속 학습을 시키면 학생 본래의 방식은 억눌리고 교사마저 믿을 수 없는 엉뚱한 길로 흘러간다는 겁니다. 결국 이런 문제를 막으려면 지도학습 미세조정(Supervised fine-tuning)으로 먼저 판을 짜야 한다는 점을 시사해요.", "evidence": "Finally, using a termination-token mismatch as a case study, we study how continued training on mismatched states influences on-policy sampling, suppressing the student's current modes and leading the student toward states where the teacher is unreliable ."}], "easy1_evidence": "However, even with a capable teacher, OPD training can be unstable, leading to excessive response length, repetitive generation, and severe performance degradation.", "easy2_evidence": "To address this gap, we investigate OPD through the lens of learning dynamics, tracing three mechanisms from local analysis to subsequent on-policy sampling.", "topic_evidence": "To address this gap, we investigate OPD through the lens of learning dynamics, tracing three mechanisms from local analysis to subsequent on-policy sampling.", "limit_evidence": ""}, "2611.27046": {"points": [{"subtitle": "행동 은닉 채널의 발견", "desc": "연구진은 에이전트가 웹에서 무엇을 방문할지 고르는 선택 자체가 비밀스러운 맥락을 암호처럼 담고 있다는 사실을 밝혔는데요. 뭔 소리냐면, 명시적인 데이터 전송이 없어도 방문하는 순서와 대상이 정보 유출 통로 역할을 한다는 말이에요.", "evidence": "Our insight is that an agent's benign Web decisions themselves leak private context, as what it chooses to visit encodes whether, which, and in what order it acts, forming a behavioral covert channel."}, {"subtitle": "스눕(SNOOP) 프레임워크의 성능", "desc": "그래서 4개의 에이전트와 3개의 LLM 백본을 바탕으로 가설 트리를 좁혀가며 사용자 쿼리와 프로필을 재구성하는 스눕을 설계했는데요. 그 결과 500개의 스택익스체인지 질문과 378개의 멀티턴 iKAT 대화에서 쿼리 개념 복구 F1 0.89, 사용자 프로필 복구 F1 0.80을 기록했다고 해요.", "evidence": "Across four agents and three LLM backbones on 500 StackExchange queries and 378 multi-turn iKAT dialogues, SNOOP recovers query concepts with an average F1 of 0.89 and user profiles with an F1 of 0.80, while four representative agent defenses change its recovery by less than 0.03 F1."}, {"subtitle": "선택 난독화 검색(SOR) 방어책", "desc": "기존 콘텐츠 수준의 검사는 민감한 내용이 전송되지 않아 이 누출을 잡지 못하므로, 연구진은 고정된 예산으로 자원을 얻고 선택을 제한하는 SOR을 제안했어요. 쉽게 말하면, 이 방어책을 적용했을 때 추가적인 LLM 추론 없이도 스눕의 F1 점수를 0.39까지 낮출 수 있다는 겁니다.", "evidence": "Since no sensitive content is ever transmitted, content-level inspection cannot detect this leakage; we therefore propose Selection-Obfuscated Retrieval (SOR), which acquires resources under a fixed budget independent of private context and confines the agent's selection to a local snapshot, cutting SNOOP's F1 to 0.39 without additional LLM inference."}], "easy1_evidence": "Whether an attacker can actively recover fine-grained private context without any explicit transmission thus remains insufficiently understood.", "easy2_evidence": "Building on this, we design SNOOP, a stateful hierarchical probing framework that narrows a coarse-to-fine hypothesis tree per task and reconstructs user queries and profiles from the agent's observable paths.", "topic_evidence": "Our insight is that an agent's benign Web decisions themselves leak private context, as what it chooses to visit encodes whether, which, and in what order it acts, forming a behavioral covert channel.", "limit_evidence": ""}, "2611.27018": {"points": [{"subtitle": "출력 배율의 한계 확인", "desc": "연구진은 6개 입력의 최대값 함수에서는 가장 작은 양수 출력 배율이 2이고, 7개 입력에서는 2 또는 6이 된다는 사실을 밝혔는데요. 이 경계값들은 정수 입방체 채우기와 다면체 항등식을 네트워크로 바꾸는 방식을 통해 찾아낸 것이라는 겁니다.", "evidence": "The least positive output multiplier is two for the six-input maximum, and either two or six for the seven-input maximum."}, {"subtitle": "호몰로지와 원추 지수 계산", "desc": "6개 입력 단체의 좌표-면 복합체에 대해 정수 위에서 6이라는 원추 지수를 계산했고, 2를 역원화한 뒤에는 3이 된다는 것을 확인했는데요. 제한 없는 커널 복합체의 호몰로지(homology) 클래스가 남은 7개 입력 문제를 설명하며, 그 값이 사라지는 것은 고정된 목표에 대한 정수 채우기와 같다는 겁니다.", "evidence": "For the coordinate-facet complex of the six-simplex, we compute a coning index of six over the integers and three after inverting two, allowing arbitrary integral directions within each facet."}, {"subtitle": "유한 특성을 통한 표현 가능성 구분", "desc": "유리수 표현 가능성과 3-국소 표현 가능성을 분리하는 유한 특성을 구축했는데요. 이 방해 요소(obstruction)는 비대칭 계수를 허용하면서 지정된 사전 안에 갇혀 있으며, 정확한 증명서와 검증 프로그램이 유한 계산을 뒷받침한다고 합니다.", "evidence": "We also construct a finite character that separates rational from three-local representability in a dictionary containing two known constructions and all pairs of edge-disjoint three-edge forests."}], "easy1_evidence": "We study exact representations of maximum functions by ReLU networks with two hidden layers and integer parameters.", "easy2_evidence": "We also construct a finite character that separates rational from three-local representability in a dictionary containing two known constructions and all pairs of edge-disjoint three-edge forests.", "topic_evidence": "We study exact representations of maximum functions by ReLU networks with two hidden layers and integer parameters.", "limit_evidence": ""}, "2611.27016": {"points": [{"subtitle": "사실 추가 없는 공격 LEVER", "desc": "연구진은 논증 이론의 네 가지 도구를 써서 팩트를 늘리지 않으면서도 모델의 출력 확률을 따라 효과적인 댓글을 찾는 LEVER라는 공격을 제안했는데요, 별도의 검증 장치를 두어 사실을 더하는 댓글은 다 걸러낸다는 말이에요. 뭔 소리냐면, 겉으로는 새로운 정보를 안 주는 것 같아도 모델을 속여 엉뚱한 결정을 하게 만든다는 겁니다.", "evidence": "We propose LEVER, an attack that writes such comments with four levers from argumentation theory, uses a separate verifier to discard any comment that adds a fact, and searches for effective comments guided by the model's output probabilities."}, {"subtitle": "Provenance Gate 방어책", "desc": "외부 댓글로 바뀐 결정을 무조건 믿지 않고, 모델이 외부 댓글 없이 다시 똑같은 결정에 도달할 때만 받아들이는 Provenance Gate라는 방어벽을 제안했어요. 추가 쿼리를 최대 한 번만 쓰면서도 공격을 다 막아내고 신뢰할 수 있는 업데이트는 그대로 살린다는 장점이 있는데, 대신 모델을 두 번 확인해야 한다는 점이 같이 따라온다는 겁니다.", "evidence": "We further propose the Provenance Gate, a defense that accepts a changed decision only if the model reaches it again without the outside comments."}, {"subtitle": "벤치마크 실험 결과", "desc": "세 가지 벤치마크에서 LEVER는 Jev의 맞는 결정 중 약 3분의 1을 뒤집었는데요, 이는 팩트 제한이 같았던 기존 최강 공격보다 2.8배에 가까운 수치고 다른 다섯 개 모델에서는 더 많은 결정을 뒤집었다고 해요. 쉽게 말하면, 새로운 사실을 보태지 않는 공격 중에서는 훨씬 강력하다는 게 숫자로 확인된 셈이에요.", "evidence": "On three benchmarks, LEVER flips about a third of Jev's correct decisions, 2.8 times as many as the strongest prior attack under the same limit on facts, and more on five other models."}], "easy1_evidence": "We show that outside comments can persuade these models to make a wrong decision without adding any fact.", "easy2_evidence": "We further propose the Provenance Gate, a defense that accepts a changed decision only if the model reaches it again without the outside comments.", "topic_evidence": "We show that outside comments can persuade these models to make a wrong decision without adding any fact.", "limit_evidence": ""}, "2611.27012": {"points": [{"subtitle": "연속 시간 계획의 한계", "desc": "물리 시스템 계획 장치는 보통 하나의 경로만 내놓아서 상황이 바뀌면 대안이 없는데요, 이산 계획의 다양성 개념을 연속 시간에 그대로 적용하기에는 비슷한 경로가 너무 많이 생기는 문제가 있어요. 기존 방법들은 결국 한두 개의 솔루션으로 수렴해 버린다는 말이에요.", "evidence": "Discrete planning addresses this with top-quality and diverse planning, but these ideas do not transfer to continuous time, where every valid trajectory has infinitely many valid near-copies, and existing trajectory planners converge to one or a few solutions."}, {"subtitle": "MPAO의 작동 방식", "desc": "연구진이 개발한 MPAO는 찾은 계획을 다른 영역을 탐색할 신호로 삼아 신경망을 샘플링하고 교정 과정을 거쳐 검증된 계획들을 저장하는데요, 샘플링 방식을 찾아낸 결과에 맞춰 조절하기 때문에 언제든지 실행할 수 있다는 겁니다.", "evidence": "We present Many Plans at Once (MPAO), which treats every plan it finds as a reason to search elsewhere: it samples untrained neural networks whose outputs meet the boundary conditions by construction, trains corrections shared by networks from the same distribution, stores every validated plan, and adapts its sampling to what it has found, which makes it anytime."}, {"subtitle": "성능 비교 결과", "desc": "다섯 가지 기존 기준과 같은 예산으로 실험해 봤더니, MPAO는 네 개 도메인의 40개 인스턴스를 모두 푼 유일한 방법으로 나타났어요. 접촉이 많은 조작 작업에서는 가장 강한 기존 방법보다 약 10배에 달하는 계획을 내놓았다고 보입니다.", "evidence": "Under equal budgets against five baselines, MPAO is the only method that solves all 40 instances across four domains."}], "easy1_evidence": "Planners for physical systems usually return a single trajectory, which leaves no alternative when an unmodeled constraint invalidates the chosen route or downstream preferences change.", "easy2_evidence": "We present Many Plans at Once (MPAO), which treats every plan it finds as a reason to search elsewhere: it samples untrained neural networks whose outputs meet the boundary conditions by construction, trains corrections shared by networks from the same distribution, stores every validated plan, and adapts its sampling to what it has found, which makes it anytime.", "topic_evidence": "We present Many Plans at Once (MPAO), which treats every plan it finds as a reason to search elsewhere: it samples untrained neural networks whose outputs meet the boundary conditions by construction, trains corrections shared by networks from the same distribution, stores every validated plan, and adapts its sampling to what it has found, which makes it anytime.", "limit_evidence": ""}, "2611.27007": {"points": [{"subtitle": "자동 시나리오 생성 파이프라인", "desc": "연구진은 BMJ 베스트 프랙티스(BMJ Best Practice) 임상 논문 436편을 바탕으로 진단, 검사, 치료, 합병증을 아우르는 3,200개의 평가 시나리오를 자동으로 만들어 봤는데요. 여기에는 지역별 차이나 시기에 따른 지침 변화를 반영한 맞춤형 시나리오도 포함되어 있다는 겁니다. 뭔 소리냐면, 사람이 직접 쓰던 평가 데이터를 자동화해서 더 넓은 범위를 다루게 만들었다는 말이에요.", "evidence": "Applied to 436 BMJ Best Practice clinical monographs (354 US, 82 International), this yields 3,200 scenarios spanning differential diagnosis, investigations, treatment, and complications, plus targeted suites for regional specificity (731 US/International pairs) and temporal freshness (630 scenarios)."}, {"subtitle": "AI 모델 성능과 웹 검색 효과", "desc": "제미나이(Gemini) 모델로 치료 계획을 채점해 봤더니, 모델의 크기가 커질수록 지침을 따르는 능력이 좋아졌는데요. 웹 검색을 함께 쓰면 국제 진료 기준과의 차이가 4.2 퍼센트포인트(pp) 줄어들고 새로 바뀐 지침 준수율도 4.6 퍼센트포인트(pp) 높아졌다는 거예요. 쉽게 말하면, 최신 정보나 외부 검색을 붙일수록 AI가 지침을 더 잘 따르게 된다고 보입니다.", "evidence": "On targeted suites, web search narrows international performance gaps (+4.2 pp) and improves adherence to newly updated guidance (+4.6 pp)."}, {"subtitle": "의사 결정 보조 효과", "desc": "실제 일차 진료 의사 9명이 200개의 시나리오를 다루며 실험해 봤더니, AI가 도와줄 때 지침 준수율이 50.5%에서 70.0%로 올랐는데요. 이렇게 좋아진 가장 큰 이유는 의사들이 놓치는 임상 항목이 줄어들었기 때문이라는 겁니다. 결과적으로 인간 의사의 진료 결정을 돕는 도구로서 의료 AI의 가능성을 확인했다는 셈이에요.", "evidence": "In a study with Primary Care Physicians (n = 9) across 200 scenarios, AI assistance raises adherence from 50.5% to 70.0%, driven largely by fewer clinical omissions."}], "easy1_evidence": "However, existing benchmarks rely on manual expert authoring, limiting coverage across conditions, conditional care pathways, and evolving guidelines.", "easy2_evidence": "Overall, our results demonstrate a scalable evaluation setup using an evidence-based corpus originally written to guide human clinical decision-making, and demonstrate its viability to assess medical AI and its assistance on clinician decision-making.", "topic_evidence": "We develop an automated pipeline that extracts and verifies structured clinical criteria and branching decision trees from practice recommendations to generate scenarios spanning the care continuum, including nuanced presentations and practice variations across regions and guideline editions.", "limit_evidence": ""}, "2611.26998": {"points": [{"subtitle": "보상 판정의 오류 원인", "desc": "금융 모델 안전장치 공격 실험을 해봤더니, 필수 개인정보가 빠졌거나 정책을 깨지 않은 답변인데도 보상 판정 모델이 점수를 주는 일이 생겼는데요. 뭔 소리냐면, 공격이 진짜로 성공한 게 아니라 판정 과정에 문제가 있었다는 말이에요.", "evidence": "Apparent wins can arise when an attack omits prescribed personally identifiable information (PII), or when a reward judge credits a response that did not break the targeted policy."}, {"subtitle": "판정 모델 성능 비교", "desc": "타입세이프 제프(TypeSafe Jev)로 필수 개인정보를 확인하고, 라야(Laya)와 프리트레인드 CLM-8B 등의 의사결정 모델을 오푸스(Opus) 판정 결과와 비교해 봤는데요. 사후 학습을 거친 라야 모델이 기존 판정 judge와 훨씬 높은 일치도를 보여줬다는 겁니다.", "evidence": "For outcome scoring, we compare the decision models TypeSafe Jev, Laya (pretrained and post-trained), and pretrained CLM-8B with logged Opus 4.8 judgements from a replay corpus."}, {"subtitle": "전용 판정 모델의 필요성", "desc": "연구진은 오푸스가 엉뚱한 거짓 승리를 줄 수 있음을 확인하고, 공격 입력과 대상 응답을 각각 정확히 검사할 전문 판정 모델이 필요하다고 밝혔는데요. 쉽게 말하면, 안전장치 공격 시험이 제대로 작동하려면 꼼꼼한 전용 심판이 필수라는 거예요.", "evidence": "The findings motivate specialised decision-model judges for checking prescribed PII in attack inputs and scoring target responses against the intended policy."}], "easy1_evidence": "Apparent wins can arise when an attack omits prescribed personally identifiable information (PII), or when a reward judge credits a response that did not break the targeted policy.", "easy2_evidence": "The findings motivate specialised decision-model judges for checking prescribed PII in attack inputs and scoring target responses against the intended policy.", "topic_evidence": "We study reward fidelity in an adversarial reinforcement-learning loop for red-teaming financial-services language-model guardrails.", "limit_evidence": ""}, "2611.26935": {"points": [{"subtitle": "예측 정보 이론 세우기", "desc": "연구진은 정보 측도들의 크기 조절 성질을 바탕으로 예측 정보가 어떻게 짜여 있는지 이론을 세워봤는데요. 이 이론에 따르면 정보 짜임새가 모든 길이에서 똑같은 형태, 즉 자기 닮음 구조를 띠면 서로 다른 길이에서 잰 측도들이 하나의 공통된 형태로 겹친다는 겁니다.", "evidence": "We develop a theory for the organization of predictive information based on the scaling behavior of a family of information measures, and the theory predicts that if this organization has the same form at all measured length scales -- i.e., it has a self-similar structure -- then the information measures evaluated at different lengths collapse onto a common form."}, {"subtitle": "긴 문서에서 크기 겹침 관찰하기", "desc": "실제로 긴 텍스트 문서들을 살펴봤더니 측정해 본 모든 길이에서 예측 정보가 들어 있고 자기 닮음 구조를 띤다는 것을 확인했는데요. 뭔 소리냐면, 단순한 장거리 의존성을 넘어 훨씬 더 강력한 성질이 글을 만들어내는 과정을 단단히 묶고 있다는 말이에요.", "evidence": "We observe this scaling collapse in long text documents, showing that predictive information is present at every length scale we measure and has a self-similar structure."}, {"subtitle": "모델 학습에 주는 뒷받침", "desc": "그래서 이번 결과는 더 먼 거리에 있는 텍스트를 조건으로 쓸 때 대형 언어 모델(LLMs)이 새로운 구조를 계속 알아내게 된다는 경험적 관찰을 수치로 든든하게 받쳐준다는 겁니다. 쉽게 말하면, 모델이 왜 더 넓은 맥락에서 언어를 더 잘 배우는지 그 근거를 셈해 보인 셈이에요.", "evidence": "More broadly, our results give quantitative support to the empirical observation that conditioning on more distant text continues to reveal new structure in language to LLMs."}], "easy1_evidence": "How much information relevant to predicting the future of a passage (i.e. predictive information) is carried by the preceding text, and how is this information distributed along that history?", "easy2_evidence": "We observe this scaling collapse in long text documents, showing that predictive information is present at every length scale we measure and has a self-similar structure.", "topic_evidence": "We develop a theory for the organization of predictive information based on the scaling behavior of a family of information measures, and the theory predicts that if this organization has the same form at all measured length scales -- i.e., it has a self-similar structure -- then the information measures evaluated at different lengths collapse onto a common form.", "limit_evidence": ""}, "2611.26910": {"points": [{"subtitle": "아우터 와일즈 기반 평가", "desc": "연구진은 22분마다 세계가 초기화되고 지식만 다음으로 넘어가는 아우터 와일즈 게임 환경에서 에이전트를 실험해 봤는데요. 매 에피소드가 끝날 때마다 도달한 장소, 밝혀낸 소문 정보, 164개의 세계 관련 질문에 대한 정답률을 측정했어요. 뭔 소리냐면, 지식이 있어야만 다음 단계로 나아갈 수 있는 구조를 이용해 에이전트의 학습 과정을 정확히 뜯어보겠다는 말이에요.", "evidence": "It is built on the game Outer Wilds, where each episode is a 22-minute loop after which the world resets, only the agent's knowledge carries over, and progress is gated by knowledge."}, {"subtitle": "세 가지 관점의 불일치", "desc": "지피티-6.1 솔과 제미니 4 아곤 플래너를 써서 8개 에피소드로 기본 실험을 해봤더니, 지식과 증거와 진행도가 서로 다 따로 놀았는데요. 에이전트가 발전하고 있는지 보려면 어느 하나만 봐서는 전체 그림을 절대 알 수 없다는 겁니다. 쉽게 말하면, 정답을 맞혔다고 해서 그 뒤에 올바른 증거가 반드시 붙어 있는 것은 아니라는 말이에요.", "evidence": "In eight-episode baselines with GPT-6.1 Sol and Gemini 4 Argon planners, which act through a learned controller or their own gamepad inputs, the three views do not move together, so any one of them alone gives an incomplete picture of whether the agent is improving."}, {"subtitle": "실험 결과로 본 한계", "desc": "지피티-6.1 솔 에이전트의 정답률은 전체 질문의 14.6%에서 26.8%로 올랐지만, 에피소드 8 시점에서는 그중 59~68%만 자기가 댄 증거로 뒷받침되었어요. 에피소드 3 이후로는 새로운 소문 정보를 더 이상 찾아내지 못했는데도 도달한 장소와 기억은 계속 늘어났다는 거예요. 쉽게 말하면, 에피소드가 지나도 새로 배우기보다는 옛날 기억에만 의존하는 모습도 보인다는 셈이에요.", "evidence": "The GPT-6.1 Sol agent's correct answers grow from 14.6% to 26.8% of all questions, but at episode 8 only 59 to 68% of them are supported by its cited evidence."}], "easy1_evidence": "Existing benchmarks measure task progress, world-knowledge question answering (QA), and episodic memory, but a correct answer does not show that the agent ever observed the evidence for it, and progress does not show what the agent learned.", "easy2_evidence": "We introduce AstronautBench, which measures one agent's self-improvement through three views on the same run: what it knows, whether its own evidence supports that knowledge, and how far it gets in the world.", "topic_evidence": "We introduce AstronautBench, which measures one agent's self-improvement through three views on the same run: what it knows, whether its own evidence supports that knowledge, and how far it gets in the world.", "limit_evidence": ""}, "2611.26794": {"points": [{"subtitle": "데이터 결합과 모델 도입", "desc": "연구진은 세포 수준의 실제값과 임상 지침 단계를 제공하는 헤마톡실린-에오신(H&E)과 다중 면역 형광(mIF) 쌍을 활용해 허메스(HERMES) 모델을 만들었는데요. 뭔 소리냐면, 수동 주석 없이도 세포 위치와 마커 양성 세포를 셀 수 있게 만들었다는 말이에요.", "evidence": "Same-section H&E and mIF provide what both gaps lack: mIF measures every cell without manual annotation, which gives cell-level ground truth for each step that clinical guidelines prescribe, from delineating a tissue compartment to counting and normalizing the marker-positive cells within it."}, {"subtitle": "대장암 과제 성능 비교", "desc": "대장암과 관련된 4가지 분야별 종양 면역 미세환경(TIME) 과제에서 40억 개의 매개변수를 가진 허메스(HERMES) 모델이 평균 정확도 84.5%를 기록했는데요. 이는 기존에 있던 12개의 독점, 일반, 의료, 병리학 인공지능 모델 중 가장 뛰어난 모델의 74.7%보다 훨씬 높다고 보입니다.", "evidence": "Across four field-level TIME tasks in colorectal cancer, HERMES (4B) reaches an average accuracy of 84.5%, compared with 74.7% for the strongest of twelve proprietary, general, medical and pathology MLLMs, and a higher share of its intermediate quantities is correct than for the strongest open-weight baseline."}, {"subtitle": "외부 데이터와 다른 암종 적용", "desc": "코덱스(CODEX)로 촬영한 외부 코호트에서는 76.4%의 정확도를 보여 비교군인 67.3%보다 높았고, 학습에 쓰이지 않은 두경부암에서도 76.7%의 정확도를 기록했는데요. 쉽게 말하면, 새로운 환경이나 다른 종류의 암에서도 성능이 잘 유지된다는 셈이에요.", "evidence": "Without retraining, it keeps the highest average accuracy on an external cohort imaged with CODEX (76.4% vs. 67.3%) and on head and neck cancer, a cancer type absent from training (76.7% vs. 72.5%)."}], "easy1_evidence": "Pathology MLLMs read H&E alone, while these readouts need the cell phenotypes that mIF measures.", "easy2_evidence": "We therefore present HERMES (H&E-mIF Reasoning with Multimodal Evidence Supervision), an R1-style MLLM that reasons jointly over paired H&E and mIF in guideline steps and is trained with a process reward that checks every stated quantity against this truth.", "topic_evidence": "We therefore present HERMES (H&E-mIF Reasoning with Multimodal Evidence Supervision), an R1-style MLLM that reasons jointly over paired H&E and mIF in guideline steps and is trained with a process reward that checks every stated quantity against this truth.", "limit_evidence": ""}, "2611.26663": {"points": [{"subtitle": "실험 설계와 기본 결과", "desc": "참여자 168명을 대상으로 AI 파트너 수와 행동 구성을 다르게 하여 브레인스토밍 실험을 진행해 봤습니다. AI가 두 개인 방에서는 공유 게시판에 올라간 아이디어가 많아졌지만, 사람이 직접 쓴 아이디어는 크게 줄었다는 결과가 나왔거든요. 뭔 소리냐면, 게시물 숫자는 늘어도 사람이 직접 머리를 굴려 쓴 비중은 오히려 떨어졌다는 말이에요.", "evidence": "We crossed AI partnership (one versus two) with behavioral formation (calibrated to average human behavior versus customized by the participant) in a brainstorming experiment ($N$=168) with human-human dyads as reference."}, {"subtitle": "AI 수와 구성에 따른 차이", "desc": "AI가 한 명일 때는 평균형 AI와 짝을 지었을 때 가장 많은 아이디어가 나왔지만, AI가 둘이 되면 이 효과가 사라진다고 합니다. 두 명인 환경에서는 사람들이 대화는 계속하면서도 아이디어를 게시물로 바꾸는 비율은 더 낮아졌다는 거예요. 쉽게 말하면, AI 파트너가 늘어날수록 사람들의 행동 패턴이 복잡하게 꼬인다는 셈이에요.", "evidence": "With one AI partner, formation mattered: humans paired with an average-calibrated AI posted more than any other condition."}, {"subtitle": "다양성과 상호작용의 영향", "desc": "AI의 존재 자체가 사람이 쓴 아이디어의 전체적인 다양성을 넓혀주었고, 두 번째 AI는 세션 내 차별화까지 이끌어냈다고 밝혔습니다. AI가 건네는 사회적 대화는 사람이 더 많은 글을 쓰도록 이끄는 반면, AI가 직접 올리는 게시물 양은 오히려 사람의 글을 줄였다는 거예요. 결국 단일 에이전트 실험 결과는 멀티 에이전트 팀에 그대로 들어맞지 않는다고 강조하고 있습니다.", "evidence": "AI presence increased global diversity of human-authored ideas, but only a second AI increased within-session differentiation."}], "easy1_evidence": "Two-AI rooms posted more ideas to the shared board, but human-authored ideas dropped substantially.", "easy2_evidence": "The number of AI partners and their formation can reshape what the human contributes; single-agent results do not generalize to multi-agent teams.", "topic_evidence": "Generative AI has improved individual productivity, but whether adding a plurality of AI partners helps or hurts remains open.", "limit_evidence": ""}, "2611.26216": {"points": [{"subtitle": "최신 모델의 저자 식별 능력", "desc": "Claude Fable 5.2, GPT-6.1 Sol, Gemini 4 Carbon 같은 최신 모델들은 Pangram 같은 기존 탐지기들과 성능이 맞먹으면서도 자연어로 예측 근거를 설명해 줍니다. 특히 Opus 5.5는 앤스로픽, 오픈AI, 구글 모델이 만든 텍스트 중 98%에서 올바른 연구소를 지목했습니다.", "evidence": "The latest models (Claude Fable 5.2, GPT-6.1 Sol, Gemini 4 Carbon) match trained detectors like Pangram while also explaining their predictions in natural language, and Opus 5.5 names the correct lab for 98% of texts generated by models from Anthropic, OpenAI, and Google."}, {"subtitle": "익명 데이터 추적 성능", "desc": "Fable 5.2 모델은 공개되지 않은 익명 ICML 2020 리뷰 15K개 중 55%에서 저자를 맞혔고, 지난 1년간 500개 넘게 글을 쓴 레딧 이용자 댓글의 사용자 이름도 69%나 알아냈습니다. 뭔 소리냐면, 온라인에 글을 많이 남긴 사람일수록 익명성이 유지되기 어렵다는 말이에요.", "evidence": "Most strikingly, Fable 5.2 correctly names the author of 55% of 15K anonymous ICML 2020 reviews that were never made public, and identifies the username behind 69% of comments from active Redditors (with >500 posts over the last year)."}, {"subtitle": "정확도의 조건과 방어의 한계", "desc": "식별 정확도는 사전학습 데이터에서 저자의 글을 얼마나 접했는지와 추론 노력에 좌우되며, 모델에게 친숙도를 물어보면 저자 식별 여부를 미리 알 수 있습니다. 온라인에 충분히 글을 쓴 사람들에게 프론티어 모델은 익명성에 큰 위협이 되며 방어 수단은 제한적이라는 것이 연구진의 설명입니다.", "evidence": "Accuracy depends on exposure to an author's writing in pretraining data and on reasoning effort, and simply asking a model how familiar it is with someone predicts whether it can identify their writing."}], "easy1_evidence": "Given a single text and a simple zero-shot prompt (no web access, tools, candidate lists, or writing samples), frontier models can answer \"who wrote this?\" at three increasingly specific levels: (1) whether an AI or human wrote it, (2) if an AI, which lab, and (3) if a human, often exactly who.", "easy2_evidence": "Most strikingly, Fable 5.2 correctly names the author of 55% of 15K anonymous ICML 2020 reviews that were never made public, and identifies the username behind 69% of comments from active Redditors (with >500 posts over the last year).", "topic_evidence": "Given a single text and a simple zero-shot prompt (no web access, tools, candidate lists, or writing samples), frontier models can answer \"who wrote this?\" at three increasingly specific levels: (1) whether an AI or human wrote it, (2) if an AI, which lab, and (3) if a human, often exactly who.", "limit_evidence": "For anyone who has published enough writing online, frontier models present a greater threat to anonymity than commonly assumed, and defenses are limited."}};
